INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-kiwame-ii-japan-rev-a', 'SNES', 'Pro Mahjong Kiwame II (Japan) (Rev A)', '1993', 'Board Game', 'Athena', '1', 'Mahjong', 'Professional Mahjong simulation sequel (Updated Revision).', 'Master the tiles in this polished 16-bit revision.', 'Play Pro Mahjong Kiwame II (Rev A) on the SNES.', 'An updated 16-bit revision that optimizes the AI decision speed and fixes minor graphical bugs in the tournament menu screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-kiwame-iii-japan', 'SNES', 'Pro Mahjong Kiwame III (Japan)', '1994', 'Board Game', 'Athena', '1', 'Mahjong', 'The third installment in the professional Mahjong series.', 'Prove your skill as the ultimate Mahjong professional.', 'Challenge Pro Mahjong Kiwame III on the Super Famicom.', 'The most refined 16-bit entry in the Kiwame series. Features a massive roster of opponents and the most advanced Mahjong engine on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-tsuwamono---renka-ban-japan', 'SNES', 'Pro Mahjong Tsuwamono - Renka Ban (Japan)', '1994', 'Board Game', 'Athena', '1', 'Mahjong', 'Competitive Mahjong simulation focused on high-stakes play.', 'Win the Renka Ban tournament and claim the championship.', 'Play Pro Mahjong Tsuwamono on the Super Famicom.', 'A technical 16-bit Mahjong title that emphasizes competitive play and professional rules. Features a clean interface and challenging AI opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-tsuwamono-japan', 'SNES', 'Pro Mahjong Tsuwamono (Japan)', '1994', 'Board Game', 'Athena', '1', 'Mahjong', 'Competitive Mahjong simulation with a focus on strategy.', 'Master the professional Mahjong circuit in Japan.', 'Experience Pro Mahjong Tsuwamono on the Super Famicom.', 'A comprehensive 16-bit gambling sim. Includes various modes to test your luck and skill against the computer or friends in authentic Mahjong matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-quarterback-usa', 'SNES', 'Pro Quarterback (USA)', '1993', 'Sports', 'LJN', '2', 'American Football', 'American football simulation featuring quarterback-specific challenges.', 'Win the Super Bowl or dominate the QB skills challenge.', 'Play Pro Quarterback for the Super Nintendo.', 'A 16-bit football title that emphasizes the passing game. Includes a unique training mode to improve your accuracy and a full seasonal play mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-soccer-japan', 'SNES', 'Pro Soccer (Japan)', '1992', 'Sports', 'TOSE', '2', 'Soccer', 'Fast-paced arcade soccer simulation.', 'Win the world cup with smooth passing and powerful shots.', 'Experience Pro Soccer on the Super Famicom.', 'Features a vertical perspective and fluid 16-bit animations. A high-energy sports title that focuses on arcade-style action and quick transitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-sport-hockey-usa', 'SNES', 'Pro Sport Hockey (USA)', '1993', 'Sports', 'TOSE', '2', 'Ice Hockey', 'Ice hockey simulation with a focus on speed and hard hits.', 'Lead your team to the trophy in this technical hockey sim.', 'Play Pro Sport Hockey for the Super Nintendo.', 'A 16-bit hockey game with a focus on physical play. Features deep customization, realistic penalty calls, and a fast-paced seasonal mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-nettou-puzzle-stadium-japan', 'SNES', 'Pro Yakyuu Nettou Puzzle Stadium (Japan)', '1996', 'Puzzle', 'Banpresto', '2', 'Sports Puzzle', 'One-on-one fighting game featuring stop-motion prehistoric beasts.', 'Defeat the rival gods to rule over the post-apocalyptic Urth.', 'Play the brutal Primal Rage on the Super Nintendo.', 'A unique 16-bit fighter with digitized stop-motion animation. Control massive dinosaurs and giant apes, using primal powers and finishers in a fight for global dominance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-nettou-puzzle-stadium-japan-beta', 'SNES', 'Pro Yakyuu Nettou Puzzle Stadium (Japan) (Beta)', '1996', 'Puzzle', 'Banpresto', '2', 'Sports Puzzle', 'One-on-one fighting game featuring stop-motion prehistoric beasts.', 'Conquer the Urth in the definitive North American version.', 'Experience Primal Rage for the Super Nintendo.', 'Features a unique combo system and specialized "fatality" style moves. A 16-bit arcade port that captures the gritty atmosphere of the original hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-star-japan', 'SNES', 'Pro Yakyuu Star (Japan)', '1995', 'Sports', 'Banpresto', '2', 'Baseball', 'One-on-one fighting game (Pre-release build).', 'Test the early animation frames and hitboxes of the beasts.', 'Check out the Primal Rage Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the dinosaur special moves and the evolution of the detailed, post-apocalyptic stage backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('project-base-081', 'SNES', 'Project Base 0.8.1', '2021', 'Platformer', 'Homebrew', '1', 'Fan Platformer', 'Action-adventure platformer based on the comic book hero (Prototype).', 'Stop the villains and master your newfound superpowers.', 'Explore the unreleased Prime Proto on the SNES.', 'A rare 16-bit prototype featuring the Ultraverse superhero. Explore non-linear levels and use super-strength to defeat enemies in this unreleased comic book adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('project-base-0842', 'SNES', 'Project Base 0.8.4.2', '2023', 'Platformer', 'Homebrew', '1', 'Fan Platformer', 'Cinematic platformer with realistic rotoscoped movement.', 'Escape the dungeon and rescue the Princess in under 60 minutes.', 'Play the definitive Prince of Persia on the SNES.', 'The best 16-bit version of the classic. Features expanded levels, improved graphics, new boss fights, and a beautiful orchestral soundtrack not found in other ports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psycho-dream-japan', 'SNES', 'Psycho Dream (Japan)', '1992', 'Action', 'Riot', '1', 'Psychological Action', 'Cinematic platformer with realistic rotoscoped movement (Japan).', 'Navigate the Sultan''s palace in the official Japanese release.', 'Experience Prince of Persia on the Super Famicom.', 'The 16-bit Japanese edition featuring the same expanded content and fluid animations that made the SNES version a standout cinematic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puggsy', 'SNES', 'Puggsy', '1993', 'Platformer', 'Traveller''s Tales', '1', 'Puzzle Platformer', 'Cinematic platformer with realistic rotoscoped movement.', 'Rescue the Princess and defeat Jaffar in this 16-bit epic.', 'Play the classic Prince of Persia on the Super Nintendo.', 'Master the 16-bit sword fighting and environmental puzzles. This version doubles the length of the original game with new traps and secret rooms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('push-over-europe-enfrdees', 'SNES', 'Push-Over (Europe) (En,Fr,De,Es)', '1992', 'Puzzle', 'Red Rat Software', '1', 'Physics Puzzle', 'Cinematic platformer sequel with enhanced combat and visuals.', 'Discover your true identity and reclaim your kingdom.', 'Experience Prince of Persia 2 on the Super Nintendo.', 'A visually stunning 16-bit sequel. Features more complex combat, diverse environments from deserts to ruins, and a deeper focus on the cinematic narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('push-over-usa', 'SNES', 'Push-Over (USA)', '1992', 'Puzzle', 'Red Rat Software', '1', 'Physics Puzzle', 'Cinematic platformer sequel with enhanced combat and visuals.', 'Uncover the secrets of the past and defeat the Shadow.', 'Play Prince of Persia 2: The Shadow & The Flame on SNES.', 'Master the improved 16-bit platforming and swordplay. A challenging adventure that expands on the mechanics of the first game with larger, more detailed stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('push-over-usa-beta', 'SNES', 'Push-Over (USA) (Beta)', '1992', 'Puzzle', 'Red Rat Software', '1', 'Physics Puzzle', 'Life simulation and "breeding" game featuring a fantasy setting.', 'Raise your adopted daughter to adulthood and shape her future.', 'Play Princess Maker on the Super Famicom.', 'A landmark 16-bit simulation. Manage your daughter''s education, part-time jobs, and social life to unlock dozens of different endings based on your choices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('putty-moon-japan', 'SNES', 'Putty Moon (Japan)', '1992', 'Platformer', 'System 3', '1', 'Puzzle Platformer', 'Turn-based RPG with an all-female cast and tactical combat.', 'Lead your team of warriors to stop an ancient evil.', 'Experience Princess Minerva in English on the SNES.', 'A 16-bit JRPG with a focus on character interactions and equipment management. The fan translation makes this colorful, anime-styled adventure accessible to everyone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('putty-squad-europe', 'SNES', 'Putty Squad (Europe)', '1994', 'Platformer', 'System 3', '1', 'Action Platformer', 'Turn-based RPG with an all-female cast and tactical combat.', 'Build your party and save the kingdom in the original release.', 'Play Princess Minerva on the Super Famicom.', 'Features vibrant 16-bit pixel art and a humorous tone. A classic RPG experience that emphasizes party balance and strategic turn-based encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-bobble---bust-a-move-europe', 'SNES', 'Puzzle Bobble - Bust-A-Move (Europe)', '1994', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Fan-made Mario World hack where Princess Peach is the hero.', 'Rescue Mario and save the kingdom with the Cape Feather.', 'Play Princess now hero With Cape on the SNES.', 'A creative 16-bit romhack that swaps the roles. Use Peach''s unique flight mechanics with the Cape to navigate challenging custom-designed Mario World levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-bobble-japan', 'SNES', 'Puzzle Bobble (Japan)', '1994', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Fan-made Mario World hack where Princess Peach is the hero.', 'Rescue Mario while using the power of the Super Leaf.', 'Play Princess now hero With Super Leaf on the SNES.', 'A 16-bit modification that introduces the Raccoon suit for Peach. Features custom level design focused on vertical exploration and floating mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzlen-desu!-japan', 'SNES', 'Puzzle''n Desu! (Japan)', '1995', 'Puzzle', 'Nintendo', '2', 'Competitive Puzzle', 'Professional American football simulation (1993 rosters).', 'Win the championship in the refined Japanese version.', 'Play Pro Football ''93 on the Super Famicom.', 'Features official 16-bit team logos and updated player stats for the ''93 season. A solid simulation with a focus on tactical play-calling and seasonal tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('q-bert-3-japan', 'SNES', 'Q-bert 3 (Japan)', '1993', 'Action', 'Realtime Associates', '2', 'Arcade Action', 'Professional American football simulation.', 'Lead your team to the Super Bowl in this 16-bit sim.', 'Experience Pro Football on the Super Famicom.', 'The foundational 16-bit football title for the Japanese market. Features a comprehensive playbook and realistic player attributes for the early 90s era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('q-bert-3-usa', 'SNES', 'Q-bert 3 (USA)', '1993', 'Action', 'Realtime Associates', '2', 'Arcade Action', 'Professional Shogi (Japanese Chess) life simulation.', 'Climb the ranks of the pro Shogi world and become a master.', 'Play Shougi no Hanamichi on the Super Famicom.', 'A unique 16-bit blend of strategy and RPG elements. Manage your career, practice matches, and face legendary opponents in high-stakes Shogi tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('r-type-iii---the-third-lightning-europe', 'SNES', 'R-Type III - The Third Lightning (Europe)', '1993', 'Shooter', 'Irem', '1', 'Horizontal Shooter', 'Professional Mahjong simulation with high-level AI.', 'Master the tiles and defeat the professional Mahjong masters.', 'Play Pro Mahjong Kiwame on the Super Famicom.', 'A 16-bit simulation designed for serious players. Features multiple rule sets, detailed statistical tracking, and a challenging tournament mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('r-type-iii---the-third-lightning-europe-beta', 'SNES', 'R-Type III - The Third Lightning (Europe) (Beta)', '1993', 'Shooter', 'Irem', '1', 'Horizontal Shooter', 'Professional Mahjong simulation sequel.', 'Win the national tournament in this expanded Mahjong sim.', 'Experience Pro Mahjong Kiwame II on the Super Famicom.', 'Features improved 16-bit graphics and more sophisticated AI. Includes a variety of professional opponents and refined tutorials for mastering advanced strategies.');
