INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radical-dreamers---nusume-nai-houseki-japan-bs-en-by-demiforce-v12-fix-by-radical-r-~radical-dreamers---le-tresor-interdit', 'SNES', 'Radical Dreamers - Nusume Nai Houseki (Japan) (BS) [En by Demiforce v1.2] [Fix by Radical R] (~Radical Dreamers - Le Tresor Interdit)', '1996', 'Adventure', 'Square', '1', 'Visual Novel', 'Fast-paced arcade soccer simulation.', 'Win the world cup with smooth passing and powerful shots.', 'Experience Pro Soccer on the Super Famicom.', 'Features a vertical perspective and fluid 16-bit animations. A high-energy sports title that focuses on arcade-style action and quick transitions.');
