INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radical-psycho-machine-racing-japan', 'SNES', 'Radical Psycho Machine Racing (Japan)', '1994', 'Racing', 'Interplay', '2', 'Top-Down Racing', 'Isometric combat racing featuring car upgrades and 3D tracks.', 'Win the intergalactic racing season through combat and speed.', 'Play the high-octane RPM Racing on the Super Famicom.', 'The direct predecessor to Rock N'' Roll Racing. Features 16-bit isometric tracks with elevation, car customization, and a robust level editor for creating your own chaotic race circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radical-psycho-machine-racing-usa', 'SNES', 'Radical Psycho Machine Racing (USA)', '1994', 'Racing', 'Interplay', '2', 'Top-Down Racing', 'Isometric combat racing with a focus on vehicle customization.', 'Defeat your rivals in this technical 16-bit racer.', 'Experience RPM Racing on the Super Nintendo.', 'A landmark 16-bit title from Silicon & Synapse (Blizzard). Master the terrain-heavy tracks and use prize money to upgrade engines and tires to dominate the season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radical-rex-europe', 'SNES', 'Radical Rex (Europe)', '1994', 'Platformer', 'Beam Software', '1', 'Action Platformer', 'Side-scrolling platformer starring a fire-breathing dinosaur.', 'Save the dinosaur race from extinction on your skateboard.', 'Join the adventure in Radical Rex on the SNES.', 'A vibrant 16-bit platformer. Control Rex as he skateboards, breathes fire, and screams his way through prehistoric levels filled with catchy music and smooth animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radical-rex-usa', 'SNES', 'Radical Rex (USA)', '1994', 'Platformer', 'Beam Software', '1', 'Action Platformer', 'Side-scrolling platformer with a rebellious attitude.', 'Defeat the evil wizard Sethron in this 16-bit quest.', 'Experience Radical Rex for the Super Nintendo.', 'Master the 16-bit skateboarding physics and fire-breathing mechanics. Features large, colorful sprites and diverse prehistoric environments with a cool 90s aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radical-rex-usa-beta', 'SNES', 'Radical Rex (USA) (Beta)', '1994', 'Platformer', 'Beam Software', '1', 'Action Platformer', 'Side-scrolling platformer (Pre-release build).', 'Test early level layouts and dinosaur physics.', 'Check out the Radical Rex Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the skateboarding controls and the evolution of the jungle-themed backgrounds before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('raiden-densetsu-japan', 'SNES', 'Raiden Densetsu (Japan)', '1991', 'Shooter', 'Seibu Kaihatsu', '2', 'Vertical Shooter', 'Vertical-scrolling arcade shooter and port of the legendary Raiden.', 'Defend Earth from an alien invasion with the Raiden supersonic jet.', 'Play the legendary Raiden Densetsu on Super Famicom.', 'A faithful 16-bit port of the arcade icon. Features the classic red and blue weapon power-up system, massive bosses, and intense, screen-filling projectile action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('raiden-trad-usa', 'SNES', 'Raiden Trad (USA)', '1991', 'Shooter', 'Seibu Kaihatsu', '2', 'Vertical Shooter', 'Vertical-scrolling arcade shooter with high-intensity combat.', 'Achieve the high score in this definitive 16-bit arcade port.', 'Experience Raiden Trad on the Super Nintendo.', 'Known for its perfectly balanced difficulty and responsive controls. Master the 16-bit bullet patterns and use powerful bombs to clear the screen of alien forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ramos-rui-no-world-wide-soccer-japan', 'SNES', 'Ramos Rui no World Wide Soccer (Japan)', '1994', 'Sports', 'Sega', '2', 'Soccer Simulation', 'Professional soccer simulation featuring Japanese star Rui Ramos.', 'Win the world cup with expert strategy and passing.', 'Experience World Wide Soccer on the Super Famicom.', 'A polished 16-bit sports title. Features authentic team management, a variety of tactical formations, and smooth animations endorsed by the legendary soccer player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampart-usa', 'SNES', 'Rampart (USA)', '1990', 'Action', 'Atari Games', '2', 'Arcade Strategy', 'Strategy and action hybrid involving castle defense and destruction.', 'Build your fortress and destroy the enemy''s walls.', 'Master the strategic Rampart on the Super Nintendo.', 'A unique 16-bit arcade port. Combine Tetris-style building with intense cannon-fire combat in a race to secure your territory and defeat invading fleets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---akanekodan-teki-hihou-japan', 'SNES', 'Ranma 1-2 - Akanekodan Teki Hihou (Japan)', '1992', 'Action', 'Fix', '1', 'Action Adventure', 'Turn-based RPG based on the popular anime and manga.', 'Find the hidden treasure and solve the mystery of the Red Cat Gang.', 'Explore Ranma 1/2: Akanekodan on Super Famicom.', 'A charming 16-bit RPG featuring the full cast of characters. Experience a story-driven adventure with tactical combat that remains faithful to the humor and heart of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---akanekodan-teki-hihou-japan-en-by-naruto+ranma-team-v099-~ranma-1-2---treasure-of-the-red-cat-gang-manga-version', 'SNES', 'Ranma 1-2 - Akanekodan Teki Hihou (Japan) [En by Naruto+Ranma Team v0.99] (~Ranma 1-2 - Treasure of the Red Cat Gang) (Manga Version)', '1992', 'Action', 'Fix', '1', 'Action Adventure', 'Turn-based RPG (English translation - Manga version).', 'Play Ranma''s quest in English with manga-accurate names.', 'Experience Ranma 1/2 RPG in English on the SNES.', 'The Naruto+Ranma Team translation makes this 16-bit gem accessible. Features original manga-style terminology and a deep narrative focused on the series'' iconic martial arts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---akanekodan-teki-hihou-japan-en-by-naruto+ranma-team-v10-~ranma-1-2---treasure-of-the-red-cat-gang-anime-version', 'SNES', 'Ranma 1-2 - Akanekodan Teki Hihou (Japan) [En by Naruto+Ranma Team v1.0] (~Ranma 1-2 - Treasure of the Red Cat Gang) (Anime Version)', '1992', 'Action', 'Fix', '1', 'Action Adventure', 'Turn-based RPG (English translation - Anime version).', 'Experience the Red Cat Gang mystery with anime-style text.', 'Play Ranma 1/2 RPG in English on the SNES.', 'The v1.0 translation update features localized names familiar to anime fans. Enjoy the 16-bit tactical battles and comedic dialogue in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---bakuretsu-rantou-hen-japan', 'SNES', 'Ranma 1-2 - Bakuretsu Rantou Hen (Japan)', '1992', 'Fighting', 'Atelier Double', '2', 'Arcade Fighting', 'One-on-one fighting game with a diverse cast of martial artists.', 'Win the tournament in this fast-paced 16-bit brawler.', 'Experience Ranma 1/2: Bakuretsu Rantou Hen on SNES.', 'Known as "Hard Battle" in the West. Features fluid 2D fighting, over-the-top special moves, and the ability to transform characters during combat as per the source material.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---chougi-ranbu-hen-japan', 'SNES', 'Ranma 1-2 - Chougi Ranbu Hen (Japan)', '1992', 'Fighting', 'Atelier Double', '2', 'Arcade Fighting', 'Advanced one-on-one fighting game with refined mechanics.', 'Master the ultimate moves and become the champion.', 'Play the polished Chougi Ranbu Hen on Super Famicom.', 'The third and most refined 16-bit fighter in the series. Features larger sprites, improved AI, and a more complex combo system for competitive martial arts action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---chounai-gekitou-hen-japan', 'SNES', 'Ranma 1-2 - Chounai Gekitou Hen (Japan)', '1993', 'Fighting', 'Atelier Double', '2', 'Arcade Fighting', 'The first fighting game in the Ranma 1/2 series for SNES.', 'Defeat your rivals in this foundational anime fighter.', 'Play Chounai Gekitou Hen on the Super Famicom.', 'A classic 16-bit brawler. Features iconic locations from the anime and a simple yet satisfying combat system that captures the frantic energy of Ranma''s world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---hard-battle-usa', 'SNES', 'Ranma 1-2 - Hard Battle (USA)', '1993', 'Fighting', 'Atelier Double', '2', 'Competitive Fighting', 'One-on-one fighting game (Western release).', 'Battle your way to victory in the official USA edition.', 'Experience Ranma 1/2: Hard Battle on the SNES.', 'A standout 16-bit anime fighter. Features localized voices and a balanced roster including Ranma, Ryoga, and Shampoo, each with unique and faithful special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2---ougi-jaanken-japan', 'SNES', 'Ranma 1-2 - Ougi Jaanken (Japan)', '1993', 'Party', 'Game Arts', '2', 'Mini-Game Collection', 'Puzzle-logic game featuring Jan-Ken-Pon (Rock, Paper, Scissors).', 'Defeat your rivals in this tactical Jan-Ken-Pon tournament.', 'Solve the puzzles in Ranma 1/2: Ougi Jaanken on SNES.', 'A unique 16-bit puzzle title. Use strategy and timing to win high-stakes matches against the series'' cast in a colorful and competitive format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2-europe', 'SNES', 'Ranma 1-2 (Europe)', '1992', 'Fighting', 'Atelier Double', '2', 'Arcade Fighting', 'One-on-one fighting game (European release).', 'Experience the chaotic martial arts in the official European version.', 'Play Ranma 1/2 on the Super Nintendo.', 'The PAL version of the acclaimed anime fighter. Master the jumps and special moves of the Tendo Dojo''s finest in this technically solid 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-1-2-france', 'SNES', 'Ranma 1-2 (France)', '1992', 'Fighting', 'Atelier Double', '2', 'Arcade Fighting', 'One-on-one fighting game (French localization).', 'Defeat the martial arts masters in the French edition.', 'Jouez à Ranma 1/2 sur le Super Nintendo.', 'The localized 16-bit release for French fans. Features the complete roster and balanced gameplay that made the series a cult favorite among fighting game enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rap-basketball-usa-proto', 'SNES', 'Rap Basketball (USA) (Proto)', '1994', 'Sports', 'Unknown', '2', 'Arcade Basketball', 'Hip-hop themed street basketball (Early prototype).', 'Test the early court physics and character sprites.', 'Explore the Rap Basketball Proto on the SNES.', 'A rare 16-bit development look at an unreleased project. Witness the early implementation of the urban aesthetic and the foundation of the 3-on-3 gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rap-jam---volume-one-usa-enfres', 'SNES', 'Rap Jam - Volume One (USA) (En,Fr,Es)', '1995', 'Sports', 'Accolade', '4', 'Street Basketball', '3-on-3 street basketball featuring real hip-hop legends.', 'Win the tournament with stars like Coolio and House of Pain.', 'Experience the urban Rap Jam: Volume One on SNES.', 'A unique 16-bit sports title. Features arcade-style basketball with no fouls, specialized power-ups, and a heavy focus on 90s hip-hop culture and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-snes-prototype', 'SNES', 'Rayman (SNES prototype)', '1995', 'Platformer', 'Ubisoft', '1', 'Action Platformer', 'Early 16-bit prototype of the legendary platformer.', 'Explore the vibrant world of Rayman in this unreleased build.', 'Discover the Rayman SNES Prototype on the SNES.', 'A historical curiosity. Witness Rayman''s original 16-bit design before the project moved to CD-based consoles. Features impressive hand-drawn style animations and early level tests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('realm-europe', 'SNES', 'Realm (Europe)', '1994', 'Action', 'Gremlin Interactive', '1', 'Action RPG', 'Side-scrolling sci-fi action platformer.', 'Defeat the biological threat and save the future.', 'Experience the intense Realm on the Super Nintendo.', 'A visually sharp 16-bit action game. Master various weapon power-ups and navigate treacherous environments filled with alien monsters and mechanical traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('realm-usa', 'SNES', 'Realm (USA)', '1994', 'Action', 'Gremlin Interactive', '1', 'Action RPG', 'Side-scrolling sci-fi action platformer.', 'Protect the city from the invading forces.', 'Play the action-packed Realm on the Super Nintendo.', 'Features impressive 16-bit parallax scrolling and challenging boss encounters. A solid choice for fans of shooters like Contra and Mega Man.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('redline-f-1-racer-usa', 'SNES', 'Redline F-1 Racer (USA)', '1994', 'Racing', 'Absolute Entertainment', '1', 'Formula Racing', 'Formula One racing simulation with Mode 7 graphics.', 'Win the world championship in this high-speed racer.', 'Race for the gold in Redline F-1 Racer on the SNES.', 'A technical 16-bit achievement. Use the "into the screen" perspective to navigate realistic F-1 tracks, managing your pit stops and car performance to stay ahead.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rejoice---aretha-oukoku-no-kanata-japan', 'SNES', 'Rejoice - Aretha Oukoku no Kanata (Japan)', '1995', 'RPG', 'Human Entertainment', '1', 'Narrative RPG', 'Action-RPG sequel to the Aretha series.', 'Travel to the kingdom of Aretha and defeat the ancient evil.', 'Explore the beautiful Rejoice on the Super Famicom.', 'A polished 16-bit JRPG with real-time combat elements. Features a touching story, vibrant pixel art, and a complex equipment system for your party of heroes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('relief-pitcher-usa', 'SNES', 'Relief Pitcher (USA)', '1994', 'Sports', 'Atari Games', '2', 'Baseball Arcade', 'Realistic baseball simulation focused on the closer''s role.', 'Step onto the mound and save the game in the final innings.', 'Master the pitch in Relief Pitcher on the SNES.', 'A unique 16-bit sports title. Focuses on the high-pressure situations of a relief pitcher, featuring digitized voices and realistic ball physics endorsed by the pros.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('relief-pitcher-usa-beta', 'SNES', 'Relief Pitcher (USA) (Beta)', '1994', 'Sports', 'Atari Games', '2', 'Baseball Arcade', 'Realistic baseball simulation (Pre-release build).', 'Test the early pitching mechanics and stadium graphics.', 'Check out the Relief Pitcher Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the ball''s curve logic and the evolution of the detailed pitcher-to-batter camera perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ren-&-stimpy-show-the---buckeroos!-usa', 'SNES', 'Ren & Stimpy Show, The - Buckeroos! (USA)', '1993', 'Platformer', 'Imagineering', '2', 'Cartoon Platformer', 'Action-platformer based on the wacky Nickelodeon show.', 'Complete various chores and surreal challenges as the duo.', 'Play Ren & Stimpy: Buckeroos! on the Super Nintendo.', 'A humorous 16-bit title featuring levels based on iconic episodes. Switch between characters to solve environmental puzzles and survive the chaotic humor of the cartoon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ren-&-stimpy-show-the---fire-dogs-usa', 'SNES', 'Ren & Stimpy Show, The - Fire Dogs (USA)', '1994', 'Action', 'Argonaut Games', '1', 'Run and Gun', 'Action-arcade simulation where you play as firemen.', 'Survive the burning building and rescue the residents.', 'Experience Fire Dogs starring Ren & Stimpy on SNES.', 'A frantic 16-bit arcade-style game. Dodge falling objects, collect power-ups, and manage your health in this high-energy interpretation of the classic "Fire Dogs" episode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ren-&-stimpy-show-the---time-warp-europe', 'SNES', 'Ren & Stimpy Show, The - Time Warp (Europe)', '1994', 'Platformer', 'Imagineering', '2', 'Cartoon Platformer', 'Time-traveling action-platformer featuring the iconic duo.', 'Navigate through history to return to the present day.', 'Join the adventure in Ren & Stimpy: Time Warp on SNES.', 'A visually impressive 16-bit title with fluid animations. Travel from the Stone Age to the Future, battling bizarre enemies and bosses in a quest to fix the timeline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ren-&-stimpy-show-the---time-warp-usa', 'SNES', 'Ren & Stimpy Show, The - Time Warp (USA)', '1994', 'Platformer', 'Imagineering', '2', 'Cartoon Platformer', 'Time-traveling action-platformer with surreal humor.', 'Travel through time and survive the duo''s weirdest journey.', 'Experience Ren & Stimpy: Time Warp on the SNES.', 'Features creative level design and specialized weapons. This 16-bit adventure captures the grotesque and hilarious art style of the original TV series perfectly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ren-&-stimpy-show-the---veediots!-europe', 'SNES', 'Ren & Stimpy Show, The - Veediots! (Europe)', '1994', 'Platformer', 'Imagineering', '2', 'Cartoon Platformer', 'Multi-story action-platformer based on three classic episodes.', 'Survive the scenarios of "The Boy Who Cried Rat" and more.', 'Play Ren & Stimpy: Veediots! on the Super Nintendo.', 'A polished 16-bit platformer that feels like playing the cartoon. Navigate through diverse stages filled with gross-out humor, tight controls, and recognizable characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ren-&-stimpy-show-the---veediots!-usa', 'SNES', 'Ren & Stimpy Show, The - Veediots! (USA)', '1994', 'Platformer', 'Imagineering', '2', 'Cartoon Platformer', 'Multi-story action-platformer based on three classic episodes.', 'Complete the TV-inspired levels in this 16-bit classic.', 'Experience the fun of Veediots! on the Super Nintendo.', 'Features three distinct game segments, each with unique mechanics. A must-play for fans of the show, offering a great balance of platforming and comedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rendering-ranger-r2-japan', 'SNES', 'Rendering Ranger R2 (Japan)', '1995', 'Shooter', 'Rainbow Arts', '1', 'Run and Gun', 'High-octane run-and-gun and shoot ''em up hybrid.', 'Defend Earth from an alien invasion in this technical marvel.', 'Experience the rare Rendering Ranger R2 on SNES.', 'A 16-bit graphical masterpiece. Featuring pre-rendered sprites and intense action with no slowdown, this is one of the rarest and most technically advanced games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('res-arcana---diana-rei---uranai-no-meikyuu-japan', 'SNES', 'Res Arcana - Diana Rei - Uranai no Meikyuu (Japan)', '1991', 'Puzzle', 'Enix', '1', 'Adventure Puzzle', 'Fortune-telling simulation and mystery adventure.', 'Unlock your destiny and solve the labyrinth of divination.', 'Explore Res Arcana: Diana Rei on the Super Famicom.', 'A unique 16-bit title that blends tarot reading and astrology with a light RPG narrative. Discover your future through various occult mini-games and logical puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('reserve_22', 'SNES', 'Reserve_22//.', '2022', 'Demo', 'Homebrew', '1', 'Experimental', '[System Reserve File / Unused Entry]', 'N/A', 'N/A', 'This entry typically represents a placeholder or reserved data slot in specific ROM sets or database collections. No 16-bit gameplay is associated with this record.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('return-of-double-dragon-japan', 'SNES', 'Return of Double Dragon (Japan)', '1995', 'Fighting', 'Technos Japan', '2', 'Beat ''em Up', 'Technical side-scrolling beat ''em up (Sōsetsuryū).', 'Defeat the Shadow Warriors with advanced martial arts.', 'Play the legendary Return of Double Dragon on SNES.', 'Widely considered the best version of the series. Features a deep combat system with blocks, counters, and specialized weapon handling that was ahead of its time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revolution-x-europe', 'SNES', 'Revolution X (Europe)', '1994', 'Action', 'Probe Software', '2', 'On-Rails Shooter', 'On-rails light gun shooter featuring the band Aerosmith.', 'Rescue Aerosmith and defeat the New Order Nation.', 'Rock out in Revolution X for the Super Nintendo.', 'A 16-bit port of the arcade hit. Blast enemies with CDs while listening to digitized Aerosmith tracks in a dystopian future where music is banned.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revolution-x-germany', 'SNES', 'Revolution X (Germany)', '1994', 'Action', 'Probe Software', '2', 'On-Rails Shooter', 'On-rails light gun shooter (German localized version).', 'Destroy the SONA regime in the official German release.', 'Experience Revolution X on the Super Nintendo.', 'The complete 16-bit arcade experience with localized text. Features the same fast-paced shooting action and rock-and-roll aesthetic of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revolution-x-japan', 'SNES', 'Revolution X (Japan)', '1994', 'Action', 'Probe Software', '2', 'On-Rails Shooter', 'On-rails light gun shooter (Japanese release).', 'Save the world of rock in the official Japanese edition.', 'Play Revolution X on the Super Famicom.', 'The official 16-bit Japanese release. Features digitized images of the band members and explosive rail-shooter gameplay that rewards quick reflexes and accuracy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revolution-x-usa', 'SNES', 'Revolution X (USA)', '1994', 'Action', 'Probe Software', '2', 'On-Rails Shooter', 'On-rails light gun shooter featuring Aerosmith.', 'Fight for freedom and music in this 16-bit shooter.', 'Experience the arcade action of Revolution X on SNES.', 'Use your controller or Super Scope to take down the cult of Helga. A loud, flashy, and fast-paced 16-bit adventure through several international concert locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rex-ronan---experimental-surgeon-usa', 'SNES', 'Rex Ronan - Experimental Surgeon (USA)', '1994', 'Educational', 'Radiance Software', '1', 'Edutainment', 'Educational action-platformer about human anatomy.', 'Shrink down and perform surgery from inside the body.', 'Play Rex Ronan: Experimental Surgeon on the SNES.', 'A unique 16-bit educational title. Navigate through the lungs and heart of a patient to remove nicotine and tar, teaching the dangers of smoking through gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rhi-roller-hockey-95-usa-proto', 'SNES', 'RHI Roller Hockey ''95 (USA) (Proto)', '1995', 'Sports', 'High Score Productions', '2', 'Roller Hockey', 'Roller hockey simulation (Unreleased Prototype).', 'Win the professional roller hockey league championship.', 'Explore the RHI Roller Hockey ''95 Prototype on SNES.', 'A rare 16-bit development look at an unreleased sports game. Features fast-paced 4-on-4 action and unique physics tailored for inline skating on a rink.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('riddick-bowe-boxing-japan', 'SNES', 'Riddick Bowe Boxing (Japan)', '1993', 'Sports', 'Micronics', '2', 'Boxing', 'Professional boxing simulation featuring the world champion.', 'Climb the rankings and win the world heavyweight title.', 'Step into the ring in Riddick Bowe Boxing on SNES.', 'A technical 16-bit boxing game. Features a stamina-based combat system, detailed fighter stats, and a career mode where you can customize your boxer''s growth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('riddick-bowe-boxing-usa', 'SNES', 'Riddick Bowe Boxing (USA)', '1993', 'Sports', 'Micronics', '2', 'Boxing', 'Professional boxing simulation featuring the world champion.', 'Defeat Riddick Bowe and become the greatest fighter.', 'Experience Riddick Bowe Boxing on the Super Nintendo.', 'Known for its realistic approach to the sport. Master the timing of your jabs and haymakers to knock out the competition in this 16-bit sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rin-kaihou-kudan-no-igo-taidou-japan', 'SNES', 'Rin Kaihou Kudan no Igo Taidou (Japan)', '1994', 'Board Game', 'Unknown', '2', 'Go Simulation', 'Traditional Igo (Go) board game simulation.', 'Master the ancient game of Go against a 9th-dan master.', 'Play Rin Kaihou Kudan no Igo Taidou on Super Famicom.', 'A serious 16-bit simulation for Go enthusiasts. Features advanced AI routines and professional tutorials to help players improve their spatial strategy and tactical placement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ring-ni-kakero-japan-np', 'SNES', 'Ring ni Kakero (Japan) (NP)', '1994', 'Fighting', 'Toei Animation', '2', 'Anime Fighting', 'Action-platformer based on the classic boxing manga.', 'Train hard and win the boxing championship as Ryuuji.', 'Experience Ring ni Kakero on the Super Famicom.', 'A 16-bit title released via Nintendo Power. Combines dramatic storytelling with high-stakes boxing matches, featuring the iconic "Galactica Phantom" special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-of-the-phoenix-usa', 'SNES', 'Rise of the Phoenix (USA)', '1994', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy simulation of ancient Chinese history.', 'Unify China during the Han Dynasty through diplomacy and war.', 'Master strategy in Rise of the Phoenix on the SNES.', 'A deep 16-bit historical sim from Koei. Manage vast armies and political alliances in a turn-based quest to become the supreme emperor of the mainland.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-of-the-robots-europe', 'SNES', 'Rise of the Robots (Europe)', '1994', 'Fighting', 'Mirage Studios', '2', 'One-on-One Fighting', 'One-on-one fighting game with pre-rendered robot sprites.', 'Defeat the rogue AI and its cyborg army as the Cyborg.', 'Experience Rise of the Robots on the Super Nintendo.', 'A 16-bit visual showcase of its time. Features massive, pre-rendered robots and a high-tech soundtrack, focusing on a metallic, futuristic aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-of-the-robots-japan', 'SNES', 'Rise of the Robots (Japan)', '1994', 'Fighting', 'Mirage Studios', '2', 'One-on-One Fighting', 'One-on-one fighting game (Japanese release).', 'Master the robot combat in the official Japanese version.', 'Play Rise of the Robots on the Super Famicom.', 'The official 16-bit Japanese release. Known for its impressive 3D-rendered graphics which were groundbreaking for the Super Nintendo hardware at the time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-of-the-robots-japan-beta', 'SNES', 'Rise of the Robots (Japan) (Beta)', '1994', 'Fighting', 'Mirage Studios', '2', 'One-on-One Fighting', 'One-on-one fighting game (Pre-release build).', 'Test the early robot animations and hit detection.', 'Check out the Rise of the Robots Beta on the SNES.', 'A rare 16-bit development look. Witness the early implementation of the background scaling and the tuning of the specialized robot movesets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-of-the-robots-usa', 'SNES', 'Rise of the Robots (USA)', '1994', 'Fighting', 'Mirage Studios', '2', 'One-on-One Fighting', 'One-on-one fighting game with pre-rendered robot sprites.', 'Fight your way through the Metropolis to stop the supervisor.', 'Experience Rise of the Robots on the Super Nintendo.', 'A 16-bit title that emphasized graphical fidelity. Take control of the Cyborg and battle through a gauntlet of specialized combat robots in this sci-fi fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rival-turf-europe', 'SNES', 'Rival Turf (Europe)', '1992', 'Fighting', 'Jaleco', '2', 'Street Brawler', 'Side-scrolling beat ''em up and first in the Rushing Beat trilogy.', 'Clear the streets of the gang menace to rescue your city.', 'Fight for justice in Rival Turf! on the SNES.', 'A classic 16-bit brawler. Choose between Jack Flak and Oozie Nelson as you punch and kick your way through urban environments in this foundational co-op street fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rival-turf-usa', 'SNES', 'Rival Turf (USA)', '1992', 'Fighting', 'Jaleco', '2', 'Street Brawler', 'Side-scrolling beat ''em up and first in the Rushing Beat trilogy.', 'Defeat the Big Al and his gang in this gritty brawler.', 'Experience the arcade-style Rival Turf! on the SNES.', 'Master the 16-bit combat system featuring throws, special attacks, and a "怒" (Angry) mode. A solid 2-player cooperative title for fans of Final Fight and Streets of Rage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('riverse-kids-japan-unl', 'SNES', 'Riverse Kids (Japan) (Unl)', '1992', 'Action', 'Unknown', '2', 'Unlicensed Platformer', 'Cute platformer and mini-game collection (Unlicensed).', 'Complete the various trials with the Riverse Kids.', 'Explore Riverse Kids on the Super Famicom.', 'A 16-bit homebrew curiosity. Features bright, simple graphics and a variety of small challenges, showcasing independent development efforts on the Super Nintendo hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-riot-4wd-europe', 'SNES', 'Road Riot 4WD (Europe)', '1994', 'Racing', 'Atari Games', '2', 'Arcade Racing', 'Off-road combat racing using Mode 7 scaling.', 'Win the off-road championship while blasting your rivals.', 'Race and blast in Road Riot 4WD for the SNES.', 'A 16-bit port of the Atari arcade hit. Navigate bumpy 3D tracks, use your mounted guns to disable opponents, and master the jumps in this high-octane racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-riot-4wd-usa', 'SNES', 'Road Riot 4WD (USA)', '1994', 'Racing', 'Atari Games', '2', 'Arcade Racing', 'Off-road combat racing using Mode 7 scaling.', 'Claim the gold in this explosive 16-bit racing tournament.', 'Experience the off-road chaos of Road Riot 4WD on SNES.', 'Features various international tracks and a focus on speed and destruction. Use the 16-bit rotation effects to survive the treacherous turns and competitive AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-riot-4wd-usa-beta', 'SNES', 'Road Riot 4WD (USA) (Beta)', '1994', 'Racing', 'Atari Games', '2', 'Arcade Racing', 'Off-road combat racing (Pre-release build).', 'Test the early truck physics and weapon hitboxes.', 'Check out the Road Riot 4WD Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the vehicle bounce logic and the early implementation of the track-side obstacles and crowd animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-runner-europe', 'SNES', 'Road Runner (Europe)', '1994', 'Platformer', 'Probe Software', '1', 'Cartoon Platformer', 'Fast-paced side-scrolling action starring the Looney Tunes duo.', 'Escape Wile E. Coyote''s traps and reach the end of the desert.', 'Play the high-speed Road Runner on the SNES.', 'Known as "Death Valley Rally" in the USA. A visually stunning 16-bit platformer where speed is key. Use your turbo to outrun boulders and Acme gadgets in vibrant desert stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-runner-europe-beta', 'SNES', 'Road Runner (Europe) (Beta)', '1994', 'Platformer', 'Probe Software', '1', 'Cartoon Platformer', 'Fast-paced action-platformer (Pre-release build).', 'Test the early speed mechanics and Coyote trap triggers.', 'Check out the Road Runner Beta on the SNES.', 'A rare 16-bit development look at the Looney Tunes classic. Witness the balancing of the "beep-beep" turbo meter and the evolution of the comedic death animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-runner-vs-wile-e-coyote-japan', 'SNES', 'Road Runner vs Wile E. Coyote (Japan)', '1994', 'Platformer', 'ITL', '1', 'Cartoon Platformer', 'Fast-paced action-platformer (Japanese release).', 'Outsmart the Coyote in the official Japanese version.', 'Experience Road Runner vs Wile E. Coyote on SNES.', 'The official 16-bit Japanese release of Death Valley Rally. Features the same incredible fluid animation and high-speed gameplay that defined the series for fans of the cartoon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-runners-death-valley-rally-usa', 'SNES', 'Road Runner''s Death Valley Rally (USA)', '1994', 'Platformer', 'Probe Software', '1', 'Action Platformer', 'Fast-paced action-platformer with cinematic Looney Tunes humor.', 'Speed through the desert and survive the Acme onslaught.', 'Experience Road Runner''s Death Valley Rally on SNES.', 'A 16-bit masterpiece of animation. Features massive bosses, hidden secrets, and the iconic humor of the show, all rendered with impressive pixel art and fast scrolling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-3-europe', 'SNES', 'RoboCop 3 (Europe)', '1992', 'Action', 'Ocean Software', '1', 'Run and Gun', 'Side-scrolling action and flight hybrid based on the movie.', 'Protect Detroit from OCP and the Splatterpunks.', 'Experience the gritty RoboCop 3 on the SNES.', 'A challenging 16-bit shooter. Includes on-foot combat, jetpack flight sequences, and a repair system. Manage your weapons to stop the corruption in a dystopian urban future.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-3-usa', 'SNES', 'RoboCop 3 (USA)', '1992', 'Action', 'Ocean Software', '1', 'Run and Gun', 'Side-scrolling action and flight hybrid based on the movie.', 'Uphold the law and defeat the robotic ninjas.', 'Play the cinematic RoboCop 3 on the Super Nintendo.', 'Features digitized images from the film and a variety of mission types. A technical 16-bit title that rewards precise aiming and strategic use of RoboCop''s specialized arsenal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-versus-the-terminator-europe', 'SNES', 'RoboCop versus The Terminator (Europe)', '1993', 'Action', 'Interplay', '1', 'Action Platformer', 'Gory action-shooter crossover based on the comic series.', 'Prevent the future where Skynet rules by destroying the Terminators.', 'Experience RoboCop versus The Terminator on SNES.', 'A dark and violent 16-bit shooter. Battle through Detroit and into the future, using powerful guns to rip through waves of cyborgs and human resistance in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-versus-the-terminator-usa', 'SNES', 'RoboCop versus The Terminator (USA)', '1993', 'Action', 'Interplay', '1', 'Action Platformer', 'Gory action-shooter crossover based on the comic series.', 'End the nightmare and stop the Skynet-RoboCop hybrid.', 'Play RoboCop versus The Terminator on the SNES.', 'Features some of the most impressive 16-bit explosions and weapon effects on the system. A fast-paced, high-stakes battle between the two greatest icons of 80s sci-fi.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robotrek-usa', 'SNES', 'Robotrek (USA)', '1994', 'RPG', 'Quintet', '1', 'Turn-Based RPG', 'Quirky turn-based RPG with robot customization.', 'Build your own robots to save the world from the Hackers.', 'Explore the creative Robotrek for the Super Nintendo.', 'A hidden 16-bit gem from Quintet. Features a deep crafting system where you design and program three custom robots with various parts, weapons, and specialized combat moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-n-roll-racing-europe', 'SNES', 'Rock n'' Roll Racing (Europe)', '1993', 'Racing', 'Blizzard Entertainment', '4', 'Combat Racing', 'Isometric combat racing with a heavy metal soundtrack.', 'Win the intergalactic championship and upgrade your war machine.', 'Rock out in Rock n'' Roll Racing for the SNES.', 'A 16-bit cult classic. Features CD-quality MIDI tracks of "Paranoid" and "Born to Be Wild," intense vehicular combat, and the legendary commentary of Larry "Supermouth" Huffman.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-n-roll-racing-japan', 'SNES', 'Rock n'' Roll Racing (Japan)', '1993', 'Racing', 'Blizzard Entertainment', '4', 'Combat Racing', 'Isometric combat racing (Japanese release).', 'Conquer the planets in the official Japanese version.', 'Experience Rock n'' Roll Racing on the Super Famicom.', 'The official 16-bit Japanese release of Blizzard''s racing hit. Includes the same deep car customization and addictive multiplayer that made the game a global sensation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-n-roll-racing-usa', 'SNES', 'Rock n'' Roll Racing (USA)', '1993', 'Racing', 'Blizzard Entertainment', '4', 'Combat Racing', 'Isometric combat racing with a heavy metal soundtrack.', 'Dominate the galaxy and leave your rivals in the dust.', 'Play the legendary Rock n'' Roll Racing on the SNES.', 'A definitive 16-bit multiplayer experience. Buy missiles, mines, and turbo boosts to survive the lethal tracks while the "Supermouth" calls every explosive turn.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-n-roll-racing-usa-beta', 'SNES', 'Rock n'' Roll Racing (USA) (Beta)', '1993', 'Racing', 'Blizzard Entertainment', '4', 'Combat Racing', 'Isometric combat racing (Pre-release build).', 'Test the early track elevations and weapon balancing.', 'Check out the Rock n'' Roll Racing Beta on the SNES.', 'A rare 16-bit development slice. Witness the early implementation of the car physics and the evolution of the alien planet backgrounds before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocketeer-the-japan', 'SNES', 'Rocketeer, The (Japan)', '1994', 'Action', 'NovaLogic', '1', 'Cinematic Platformer', 'Action-adventure and flight simulation based on the film.', 'Defeat the Nazi agents and stop the experimental rocket pack.', 'Experience The Rocketeer on the Super Famicom.', 'A unique 16-bit blend of cinematic storytelling, side-scrolling action, and first-person flying sequences. Experience the 1930s pulp adventure style in this faithful movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocketeer-the-usa', 'SNES', 'Rocketeer, The (USA)', '1994', 'Action', 'NovaLogic', '1', 'Cinematic Platformer', 'Action-adventure and flight simulation based on the film.', 'Protect the skies in the official USA edition.', 'Play the high-flying Rocketeer on the Super Nintendo.', 'Features diverse gameplay modes, including racing and dogfighting. A technical 16-bit title that captures the hero''s struggle against the secret agents of the underworld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-&-forte---multiple-equipment', 'SNES', 'Rockman & Forte - Multiple Equipment', '1998', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer with specialized equipment mod (Hack).', 'Experience the Mega Man sequel with custom weapon upgrades.', 'Play Rockman & Forte: Multiple Equipment on SNES.', 'A technical 16-bit modification that allows players to use an expanded arsenal. Enhance your strategy by equipping multiple power-ups simultaneously in this challenging fan-tuned version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-&-forte-english', 'SNES', 'Rockman & Forte (English)', '1998', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer starring Mega Man and his rival (English).', 'Stop King from conquering the world in this late-gen epic.', 'Play Rockman & Forte in English on the SNES.', 'The definitive 16-bit fan translation of the Super Famicom classic. Choose between Mega Man''s classic playstyle or Bass''s rapid-fire and double-jump mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-&-forte-japan', 'SNES', 'Rockman & Forte (Japan)', '1998', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer starring Mega Man and his rival.', 'Collect the Data CDs and defeat the powerful Robot Masters.', 'Experience Rockman & Forte on the Super Famicom.', 'One of the most visually impressive 16-bit games. Features massive sprites, complex boss patterns, and a deep shop system for upgrading your heroes'' abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-&-forte-japan-en-by-aeon-genesis-v10', 'SNES', 'Rockman & Forte (Japan) [En by Aeon Genesis v1.0]', '1998', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer (English Translation v1.0).', 'Experience the final 16-bit Mega Man quest in English.', 'Play Rockman & Forte (English v1.0) on the SNES.', 'The complete 16-bit translation by Aeon Genesis. Navigate through challenging stages and experience the full narrative of the uneasy alliance between Mega Man and Bass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-&-forte-japan-en-by-aeon-genesis-v10-~mega-man-&-bass', 'SNES', 'Rockman & Forte (Japan) [En by Aeon Genesis v1.0] (~Mega Man & Bass)', '1998', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer (English Translation v1.0).', 'Experience the final 16-bit Mega Man quest in English.', 'Play Rockman & Forte (English v1.0) on the SNES.', 'The complete 16-bit translation by Aeon Genesis. Navigate through challenging stages and experience the full narrative of the uneasy alliance between Mega Man and Bass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-7---nerfed-spikes', 'SNES', 'Rockman 7 - Nerfed Spikes', '1995', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer with a focus on difficulty balancing (Hack).', 'Experience Mega Man 7 without the instant-kill spikes.', 'Play Rockman 7: Nerfed Spikes on the SNES.', 'A 16-bit modification that makes the environmental hazards less punishing. Perfect for players who want to enjoy the boss fights and level design without the frustration of instant death from spikes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-7---shukumei-no-taiketsu!-japan', 'SNES', 'Rockman 7 - Shukumei no Taiketsu! (Japan)', '1995', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'The 16-bit debut of the classic series on the Super Famicom.', 'Stop Dr. Wily and his new Robot Masters as Rockman.', 'Experience Rockman 7 on the Super Famicom.', 'Known as Mega Man 7 in the West. Features colorful 16-bit graphics, a unique introductory stage, and the first appearance of the rival character, Bass (Forte).');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-7---shukumei-no-taiketsu!-japan-sample', 'SNES', 'Rockman 7 - Shukumei no Taiketsu! (Japan) (Sample)', '1995', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer (Early development sample).', 'Explore the initial implementation of the weapon shop.', 'Check out the Rockman 7 Sample on Super Famicom.', 'A rare 16-bit development look at the Japanese release. Witness early sprite designs and stage layouts before the final polishing of the Dr. Wily encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-7-ep', 'SNES', 'Rockman 7 EP', '2021', 'Demo', 'Homebrew', '1', 'Experimental', 'Enhanced version of the 16-bit classic (Fan modification).', 'Play through Rockman 7 with updated features and tweaks.', 'Try Rockman 7 EP on the Super Nintendo.', 'A specialized 16-bit fan edition that adjusts weapon damage, enemy placement, and specific stage mechanics for a fresh gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-7-ep---english', 'SNES', 'Rockman 7 EP - English', '2021', 'Demo', 'Homebrew', '1', 'Experimental', 'Enhanced version of Rockman 7 with full English text.', 'Enjoy the Japanese classic with translated dialogue.', 'Play Rockman 7 EP in English on the SNES.', 'The complete 16-bit "EP" modification localized for Western players. Features adjusted balancing and English text for the story sequences and weapon menus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x---2016-new-years-hack', 'SNES', 'Rockman X - 2016 New Year''s Hack', '2016', 'Action Platformer', 'Capcom / Hack', '1', 'Action Platformer', 'Themed holiday modification of the 16-bit masterpiece.', 'Celebrate the new year with custom stages and palettes.', 'Play Rockman X: 2016 New Year''s Hack on SNES.', 'A festive 16-bit romhack of the original Rockman X. Features snowy visual themes, holiday-inspired enemy sprites, and slightly altered level paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x---2017-new-years-hack', 'SNES', 'Rockman X - 2017 New Year''s Hack', '2017', 'Action Platformer', 'Capcom / Hack', '1', 'Action Platformer', 'Themed holiday modification for the Maverick Hunter series.', 'Blast through a winter wonderland in this custom hack.', 'Play Rockman X: 2017 New Year''s Hack on SNES.', 'Continues the 16-bit tradition of annual fan releases. Includes new secret item locations and a celebratory atmosphere throughout the eight Maverick stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x---2023-new-years-hack', 'SNES', 'Rockman X - 2023 New Year''s Hack', '2023', 'Action Platformer', 'Capcom / Hack', '1', 'Action Platformer', 'Themed holiday modification with modern quality-of-life tweaks.', 'Defeat Sigma''s forces in this 2023 celebratory edition.', 'Play Rockman X: 2023 New Year''s Hack on SNES.', 'A highly polished 16-bit modification featuring refined sprite work and custom music tracks to ring in the new year with X and Zero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x-japan', 'SNES', 'Rockman X (Japan)', '1993', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'High-speed action-platformer and evolution of the series.', 'Defeat the eight Mavericks and stop Sigma''s rebellion.', 'Play the legendary Rockman X on the Super Famicom.', 'A 16-bit masterpiece. Introduced the wall-jump, dashing, and armor upgrades, creating a faster and more intense gameplay loop than the original series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x-japan-rev-a', 'SNES', 'Rockman X (Japan) (Rev A)', '1993', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'High-speed action-platformer (Updated Japanese revision).', 'Experience the refined version of the Maverick hunting epic.', 'Play Rockman X (Rev A) on the Super Famicom.', 'An updated 16-bit revision that fixes minor graphical glitches and optimizes the internal code for smoother performance during intense boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x2-japan', 'SNES', 'Rockman X2 (Japan)', '1994', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'High-speed sequel featuring the Cx4 enhancement chip.', 'Recover Zero''s parts and defeat the X-Hunters.', 'Experience the epic Rockman X2 on Super Famicom.', 'A technical 16-bit marvel. Uses the custom Cx4 chip for 3D wireframe effects and features incredibly fluid movement and massive, screen-filling bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x3---2021-new-years-hack', 'SNES', 'Rockman X3 - 2021 New Year''s Hack', '2021', 'Action Platformer', 'Capcom / Hack', '1', 'Action Platformer', 'Themed holiday modification of the third Maverick installment.', 'Celebrate with Zero and X in this 2021 custom build.', 'Play Rockman X3: 2021 New Year''s Hack on SNES.', 'A creative 16-bit romhack featuring New Year''s decorations, adjusted difficulty curves, and new color palettes for the ride armors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x3---2022-new-years-hack', 'SNES', 'Rockman X3 - 2022 New Year''s Hack', '2022', 'Action Platformer', 'Capcom / Hack', '1', 'Action Platformer', 'Themed holiday modification with a focus on playable Zero.', 'Start the year with a bang in this specialized X3 hack.', 'Play Rockman X3: 2022 New Year''s Hack on SNES.', 'Features enhanced 16-bit graphics and the ability to use X and Zero more interchangeably throughout the game''s challenging stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-x3-japan', 'SNES', 'Rockman X3 (Japan)', '1995', 'Action Platformer', 'Capcom', '1', 'Action Platformer', 'Action-platformer featuring the most complex armor sets.', 'Stop the Doppler army and upgrade your Hyper Armor.', 'Play the intense Rockman X3 on the Super Famicom.', 'The final 16-bit entry in the series for the console. Features the ability to play as Zero for the first time and includes massive secrets and multiple endings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockmans-soccer-japan', 'SNES', 'Rockman''s Soccer (Japan)', '1994', 'Sports', 'Capcom', '2', 'Soccer', 'Bizarre and fun 16-bit soccer simulation.', 'Win the soccer tournament using specialized robot weapons.', 'Play Rockman''s Soccer on the Super Famicom.', 'A unique 16-bit sports spin-off. Use your favorite Robot Masters in 11-on-11 matches where slide tackles and fireball shots are part of the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockos-modern-life---spunkys-dangerous-day-usa', 'SNES', 'Rocko''s Modern Life - Spunky''s Dangerous Day (USA)', '1994', 'Platformer', 'Realtime Associates', '1', 'Cartoon Platformer', 'Puzzle-platformer based on the surreal Nickelodeon show.', 'Guide the dog Spunky through danger in this leashed quest.', 'Play Rocko''s Modern Life on the Super Nintendo.', 'A colorful 16-bit title where you protect Rocko''s dim-witted dog. Interact with the environment to clear a safe path while avoiding hazards from the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocky-rodent-europe', 'SNES', 'Rocky Rodent (Europe)', '1993', 'Platformer', 'Irem', '1', 'Action Platformer', 'Action-platformer starring a rodent with a magical mohawk.', 'Use your hair to whip, hook, and fly through levels.', 'Experience the wacky Rocky Rodent on the SNES.', 'A creative 16-bit title where your mohawk determines your abilities. Find different hair products to gain new powers and defeat the mobsters who stole your food.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocky-rodent-usa', 'SNES', 'Rocky Rodent (USA)', '1993', 'Platformer', 'Irem', '1', 'Action Platformer', 'Action-platformer with unique hair-based mechanics.', 'Rescue the girl and get your meal in this 16-bit quest.', 'Play the action-packed Rocky Rodent on the SNES.', 'Master the 16-bit "hair physics." Use your mohawk as a grappling hook or a powerful drill to navigate urban and industrial environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roger-clemens-mvp-baseball-japan', 'SNES', 'Roger Clemens'' MVP Baseball (Japan)', '1991', 'Sports', 'Baseball', '1', 'Baseball Simulation', 'Realistic baseball simulation featuring the legendary pitcher.', 'Win the world series with authentic 90s rosters.', 'Step up to the plate in Roger Clemens'' MVP Baseball.', 'A technical 16-bit sports title for the Japanese market. Features a unique "behind-the-batter" perspective and realistic pitching mechanics for the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roger-clemens-mvp-baseball-usa', 'SNES', 'Roger Clemens'' MVP Baseball (USA)', '1991', 'Sports', 'Baseball', '1', 'Baseball Simulation', 'Realistic baseball simulation featuring the legendary pitcher.', 'Dominate the league in the official USA edition.', 'Play Roger Clemens'' MVP Baseball on the SNES.', 'Features digitized voices and smooth 16-bit animations. Master the timing of your swings and the speed of your pitches to win the championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roger-clemens-mvp-baseball-usa-beta', 'SNES', 'Roger Clemens'' MVP Baseball (USA) (Beta)', '1991', 'Sports', 'Baseball', '1', 'Baseball Simulation', 'Realistic baseball simulation (Pre-release build).', 'Test the initial ball physics and stadium graphics.', 'Check out the Roger Clemens'' MVP Beta on the SNES.', 'A rare 16-bit development look. Witness the early implementation of the fielder AI and the evolution of the detailed pitcher-to-batter camera.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roger-clemens-mvp-baseball-usa-rev-a', 'SNES', 'Roger Clemens'' MVP Baseball (USA) (Rev A)', '1991', 'Sports', 'Baseball', '1', 'Baseball Simulation', 'Realistic baseball simulation (Updated USA revision).', 'Climb the leaderboard in this polished baseball edition.', 'Experience Roger Clemens'' MVP Baseball (Rev A) on SNES.', 'An updated 16-bit revision that improves menu navigation and optimizes the AI''s hitting logic for a more balanced and realistic challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rokudenashi-blues---taiketsu!-tokyo-shitennou-japan', 'SNES', 'Rokudenashi Blues - Taiketsu! Tokyo Shitennou (Japan)', '1993', 'Fighting', 'Tose', '2', 'Manga Fighting', 'Fighting game based on the delinquent high school manga.', 'Defeat the Four Kings of Tokyo in street brawls.', 'Play Rokudenashi Blues on the Super Famicom.', 'A cinematic 16-bit fighter. Features large character sprites and follows the story of Maeda Taison through intense one-on-one battles and dramatic cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romance-of-the-three-kingdoms-ii-usa', 'SNES', 'Romance of the Three Kingdoms II (USA)', '1991', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'Historical grand strategy simulation set in ancient China.', 'Unify the warring states and become the Emperor.', 'Master history in Romance of the Three Kingdoms II.', 'A deep 16-bit simulation from Koei. Manage taxes, diplomacy, and turn-based military tactics in a faithful recreation of the Han Dynasty''s fall.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romance-of-the-three-kingdoms-iii---dragon-of-destiny-usa', 'SNES', 'Romance of the Three Kingdoms III - Dragon of Destiny (USA)', '1992', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'Advanced historical strategy with improved tactical maps.', 'Lead your favorite general to total dominance.', 'Experience Romance of the Three Kingdoms III on SNES.', 'Features significantly improved 16-bit graphics and a deeper focus on city management and individual officer loyalty in the quest for unification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romance-of-the-three-kingdoms-iv---wall-of-fire-usa', 'SNES', 'Romance of the Three Kingdoms IV - Wall of Fire (USA)', '1994', 'Strategy', 'Koei', '1', 'Turn-Based Strategy', 'Grand strategy epic with an emphasis on "Wall of Fire" tactics.', 'Claim the mandate of heaven through war and intrigue.', 'Play Romance of the Three Kingdoms IV on the SNES.', 'The most advanced 16-bit entry in the series. Features naval battles, complex siege mechanics, and an expanded roster of hundreds of historical officers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-sa-ga-japan', 'SNES', 'Romancing Sa-Ga (Japan)', '1992', 'RPG', 'Square', '1', 'JRPG', 'Non-linear open-world JRPG with multiple protagonists.', 'Choose your hero and prevent the resurrection of Saruin.', 'Play the original Romancing Sa-Ga on the Super Famicom.', 'A landmark 16-bit RPG from Square. Features eight different characters with unique stories and a revolutionary "scenario-free" system where your choices dictate the flow of the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-sa-ga-japan-rev-a', 'SNES', 'Romancing Sa-Ga (Japan) (Rev A)', '1992', 'RPG', 'Square', '1', 'JRPG', 'Non-linear open-world JRPG (Updated Revision).', 'Master the refined battle systems in this Japanese revision.', 'Experience Romancing Sa-Ga (Rev A) on the Super Famicom.', 'An updated 16-bit version that addresses minor balance issues and bugs from the original release, offering a smoother journey through the diverse world of Mardias.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-sa-ga-2-japan', 'SNES', 'Romancing Sa-Ga 2 (Japan)', '1993', 'RPG', 'Square', '1', 'JRPG', 'Strategic JRPG featuring an inheritance and empire system.', 'Build your empire over generations to defeat the Seven Heroes.', 'Lead your lineage in Romancing Sa-Ga 2 on SNES.', 'A unique 16-bit epic. Rule as an emperor, expand your territory, and pass your skills down to heirs through a complex "generation leap" mechanic as you face ancient threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-sa-ga-3-japan', 'SNES', 'Romancing Sa-Ga 3 (Japan)', '1995', 'RPG', 'Square', '1', 'JRPG', 'Polished open-world JRPG with stunning pixel art and combat.', 'Stop the Rise of the Abyss Lords in this 16-bit masterpiece.', 'Experience the epic Romancing Sa-Ga 3 on the Super Famicom.', 'The pinnacle of the 16-bit series. Features beautiful graphics, a refined combat system with "Commander Mode," and eight intertwining paths that offer massive replayability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-sa-ga-3-japan-rev-a', 'SNES', 'Romancing Sa-Ga 3 (Japan) (Rev A)', '1995', 'RPG', 'Square', '1', 'JRPG', 'Polished open-world JRPG (Updated Revision).', 'Experience the definitive 16-bit adventure with bug fixes.', 'Play Romancing Sa-Ga 3 (Rev A) on the Super Famicom.', 'Includes subtle balance changes and technical polish. Navigate the vast world and master the tactical "Glitter" sparking system to learn powerful new battle techniques.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-sa-ga-3-japan-sample', 'SNES', 'Romancing Sa-Ga 3 (Japan) (Sample)', '1995', 'RPG', 'Square', '1', 'JRPG', 'Polished open-world JRPG (Development Sample).', 'Test the early battle mechanics and character interactions.', 'Explore the Romancing Sa-Ga 3 Sample on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character selection screen and early versions of the intricate combat animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-saga-japan-en-by-trans-dimension-v040-incomplete', 'SNES', 'Romancing SaGa (Japan) [En by Trans Dimension v0.40] (Incomplete)', '1992', 'RPG', 'Square / Hack', '1', 'JRPG', 'Non-linear open-world JRPG (English Translation - Incomplete).', 'Experience the first Romancing Sa-Ga in English.', 'Play Romancing SaGa English v0.40 on the SNES.', 'A 16-bit fan translation that makes the opening hours of the first Sa-Ga game accessible. Provides a glimpse into the unique narrative structure and early series mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-saga-2-japan-en-by-gilhide-v005c-incomplete', 'SNES', 'Romancing SaGa 2 (Japan) [En by Gilhide v0.05c] (Incomplete)', '1993', 'RPG', 'Square / Hack', '1', 'JRPG', 'Strategic generational JRPG (English Translation - Incomplete).', 'Guide your empire''s first steps with translated text.', 'Play Romancing SaGa 2 English v0.05c on the SNES.', 'An early-stage 16-bit fan translation. Allows players to experience the foundational mechanics of the empire system and the initial encounters with the Seven Heroes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-saga-3-japan-rev-1-en-by-mana-sword-v030', 'SNES', 'Romancing SaGa 3 (Japan) (Rev 1) [En by Mana Sword v0.30]', '1995', 'RPG', 'Square / Hack', '1', 'JRPG', 'Polished open-world JRPG (English Translation v0.30).', 'Experience Sa-Ga 3''s complex narrative in English.', 'Play Romancing SaGa 3 English v0.30 on the SNES.', 'A functional 16-bit translation by Mana Sword. Allows players to navigate the menus and understand the core story of the eight heroes as they face the Abyss.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('romancing-saga-3-japan-en-by-mana-sword-v030', 'SNES', 'Romancing SaGa 3 (Japan) [En by Mana Sword v0.30]', '1995', 'RPG', 'Square / Hack', '1', 'JRPG', 'Polished open-world JRPG (English Translation v0.30).', 'Experience Sa-Ga 3''s complex narrative in English.', 'Play Romancing SaGa 3 English v0.30 on the SNES.', 'A functional 16-bit translation by Mana Sword. Allows players to navigate the menus and understand the core story of the eight heroes as they face the Abyss.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('royal-conquest-japan', 'SNES', 'Royal Conquest (Japan)', '1992', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Turn-based strategy and fantasy war simulation.', 'Command your army to reclaim the kingdom in this tactical sim.', 'Experience Royal Conquest on the Super Famicom.', 'A grid-based 16-bit strategy title. Manage units, terrain advantage, and magical abilities in a series of increasingly difficult battles to restore peace to a divided land.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rpg-tsukuru---super-dante-japan', 'SNES', 'RPG Tsukuru - Super Dante (Japan)', '1995', 'Development', 'ASCII', '1', 'RPG Creation Tool', 'Creative game-making utility for the SNES.', 'Design and play your own custom 16-bit RPG.', 'Build your dream game with RPG Tsukuru on the SNES.', 'The foundational "RPG Maker" for home consoles. Use pre-set tiles, characters, and a simplified event system to create your own fantasy adventures directly on your Super Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rpg-tsukuru---super-dante-japan-en-by-magecraft-v090-~rpg-maker---super-dante-incomplete', 'SNES', 'RPG Tsukuru - Super Dante (Japan) [En by MageCraft v0.90] (~RPG Maker - Super Dante) (Incomplete)', '1995', 'Development', 'ASCII / Hack', '1', 'RPG Creation Tool', 'Creative game-making utility (English Translation).', 'Create your own 16-bit RPG with English menus.', 'Experience RPG Maker: Super Dante in English on SNES.', 'A 16-bit fan translation that makes the game-creation tools accessible to Western players. Design maps, script dialogue, and create custom combat encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rpg-tsukuru-2-japan', 'SNES', 'RPG Tsukuru 2 (Japan)', '1996', 'Development', 'ASCII', '1', 'RPG Creation Tool', 'Advanced game-making utility with expanded assets.', 'Create more complex RPGs with new tools and animations.', 'Explore the power of RPG Tsukuru 2 on the Super Famicom.', 'The 16-bit sequel to Super Dante. Features significantly more memory for assets, improved event scripting, and a wider variety of monster and environment designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rudra-no-hihou-japan', 'SNES', 'Rudra no Hihou (Japan)', '1996', 'RPG', 'Square', '1', 'JRPG', 'Cinematic JRPG with a unique "Mantra" magic system.', 'Save the world from destruction in the final 15 days.', 'Experience the stunning Rudra no Hihou on the SNES.', 'One of the most visually impressive 16-bit RPGs. Features three interlocking stories and a magic system where you "write" your own spells to determine their effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rudra-no-hihou-japan-en-by-aeon-genesis-v20-~treasure-of-the-rudras', 'SNES', 'Rudra no Hihou (Japan) [En by Aeon Genesis v2.0] (~Treasure of the Rudras)', '1996', 'RPG', 'Square / Hack', '1', 'JRPG', 'Cinematic JRPG (Full English Translation v2.0).', 'Experience the "Treasure of the Rudras" in English.', 'Play Rudra no Hihou in English on the Super Nintendo.', 'The definitive 16-bit translation by Aeon Genesis. Fully localized the complex Mantra system and narrative, allowing players to enjoy Square''s late-gen masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ruin-arm-japan', 'SNES', 'Ruin Arm (Japan)', '1996', 'Action RPG', 'Taito', '1', 'Action RPG', 'Fantasy Action-RPG with a focus on weapon switching.', 'Recover the legendary Ruin Arm and stop the dark cult.', 'Explore the world of Ruin Arm on the Super Famicom.', 'A fast-paced 16-bit adventure. Features a unique system where your character''s abilities change based on the weapons equipped, blending exploration with tactical real-time combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('run-saber-europe', 'SNES', 'Run Saber (Europe)', '1993', 'Action Platformer', 'Hori Electric', '1', 'Run-and-Gun', 'Cyberpunk side-scrolling action-platformer.', 'Stop the evil genetic experiments of Bruhl across the globe.', 'Experience the high-speed Run Saber on the SNES.', 'A frantic 16-bit action game similar to Strider. Choose between Allen or Sheena, using energy blades and acrobatic moves to destroy massive bosses in futuristic settings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('run-saber-usa', 'SNES', 'Run Saber (USA)', '1993', 'Action Platformer', 'Hori Electric', '1', 'Run-and-Gun', 'Cyberpunk side-scrolling action-platformer.', 'Defeat the biotechnical menace in the official USA edition.', 'Play the action-packed Run Saber on the Super Nintendo.', 'Features incredible 16-bit fluid animation and a great 2-player co-op mode. Navigate through high-speed levels including a moving jet and a vertical industrial tower.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rushing-beat-japan', 'SNES', 'Rushing Beat (Japan)', '1992', 'Beat ''em Up', 'Jaleco', '2', 'Beat ''em Up', 'Urban side-scrolling beat ''em up (First in the trilogy).', 'Rescue your sister and clean up the streets of Neo-Cisco.', 'Fight for justice in Rushing Beat on the Super Famicom.', 'Known as "Rival Turf" in the West. A foundational 16-bit brawler featuring two playable heroes and a gritty urban atmosphere inspired by arcade classics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rushing-beat-ran---fukusei-toshi-japan', 'SNES', 'Rushing Beat Ran - Fukusei Toshi (Japan)', '1992', 'Beat ''em Up', 'Jaleco', '2', 'Beat ''em Up', 'Urban side-scrolling beat ''em up (Second in the trilogy).', 'Stop the cloning conspiracy in the city of clones.', 'Play the intense Rushing Beat Ran on the Super Famicom.', 'Known as "Brawl Brothers" in the West. Features an expanded move set and a "Fury" mode. Explore sprawling 16-bit levels that branch based on your performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rushing-beat-shura-japan', 'SNES', 'Rushing Beat Shura (Japan)', '1993', 'Beat ''em Up', 'Jaleco', '2', 'Beat ''em Up', 'The final and most complex entry in the Rushing Beat series.', 'Dismantle the Shura organization in this non-linear brawler.', 'Experience Rushing Beat Shura on the Super Famicom.', 'Known as "The Peace Keepers" in the West. Features four playable characters, branching paths, and multiple endings, making it one of the deepest 16-bit beat ''em ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuuki-heidan-danzarb-japan', 'SNES', 'Ryuuki Heidan Danzarb (Japan)', '1993', 'Action RPG', 'Konami', '1', 'Action RPG', 'Sci-fi JRPG featuring mecha-dragon combat.', 'Lead the Dragon Squadron Danzarb against the alien threat.', 'Experience Ryuuki Heidan Danzarb on the Super Famicom.', 'A unique 16-bit hybrid. Combines traditional JRPG exploration with tactical turn-based battles where your party pilots powerful bio-mechanical dragon units.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuuki-heidan-danzarb-japan-en-by-aeon-genesis-v10-~dragon-squadron-danzarb', 'SNES', 'Ryuuki Heidan Danzarb (Japan) [En by Aeon Genesis v1.0] (~Dragon Squadron Danzarb)', '1993', 'Action RPG', 'Konami / Hack', '1', 'Action RPG', 'Sci-fi JRPG (Full English Translation v1.0).', 'Experience the "Dragon Squadron" story in English.', 'Play Danzarb in English on the Super Nintendo.', 'The Aeon Genesis 16-bit fan translation. Brings the complex story of military intrigue and bio-mechanical warfare to English-speaking audiences for the first time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuuko-no-ken-japan', 'SNES', 'Ryuuko no Ken (Japan)', '1992', 'Fighting', 'SNK', '2', 'Arcade Fighting', 'One-on-one fighting game featuring huge character sprites.', 'Master the Kyokugenryu Karate and rescue Yuri Sakazaki.', 'Experience Art of Fighting on the Super Famicom.', 'The official 16-bit Japanese release of the Neo-Geo hit. Features the legendary zoom-in effect, large sprites, and a stamina-based spirit meter for special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuuko-no-ken-2-japan', 'SNES', 'Ryuuko no Ken 2 (Japan)', '1994', 'Fighting', 'SNK', '2', 'Arcade Fighting', 'One-on-one fighting game sequel with refined mechanics.', 'Win the King of Fighters tournament in the official sequel.', 'Play Art of Fighting 2 on the Super Famicom.', 'An improved 16-bit fighter featuring a larger roster, including the younger version of Geese Howard. Features refined combo mechanics and improved graphical detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saibara-rieko-no-mahjong-hourouki-japan', 'SNES', 'Saibara Rieko no Mahjong Hourouki (Japan)', '1992', 'Mahjong', 'Nichibutsu', '1', 'Mahjong', 'Traditional Mahjong simulation based on the manga artist''s work.', 'Win the Mahjong circuit featuring Saibara Rieko''s characters.', 'Play Saibara Rieko no Mahjong on the Super Famicom.', 'A 16-bit Mahjong title featuring the unique and humorous art style of Saibara Rieko. Includes a story mode and various professional rules for enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saikousoku-shikou---shougi-mahjong-japan', 'SNES', 'Saikousoku Shikou - Shougi Mahjong (Japan)', '1993', 'Board Game', 'Nihon Bussan', '2', 'Shogi & Mahjong', 'Dual-discipline board game simulation (Shogi and Mahjong).', 'Master both traditional Japanese games in one collection.', 'Experience Shougi Mahjong on the Super Famicom.', 'A 16-bit strategic package featuring high-speed AI for both Shogi and Mahjong. Perfect for players looking for a comprehensive mental challenge on one cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saikyou---takada-nobuhiko-japan', 'SNES', 'Saikyou - Takada Nobuhiko (Japan)', '1993', 'Fighting', 'Hudson Soft', '2', 'MMA Fighting', 'Professional wrestling simulation featuring Nobuhiko Takada.', 'Climb the ranks of the MMA world and become a champion.', 'Experience Saikyou: Takada Nobuhiko on the Super Famicom.', 'A technical 16-bit wrestling game focused on the "Strong Style" of Nobuhiko Takada. Features a stamina system and realistic grappling mechanics inspired by PRIDE and UWFi.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sailor-moon-fighter-s', 'SNES', 'Sailor Moon Fighter S', '1995', 'Fighting', 'Fan Hack', '2', 'Anime Fighting', 'Fan-made fighting game based on the Sailor Moon universe (Hack).', 'Defeat the Negaverse in this enhanced 16-bit fighter.', 'Play Sailor Moon Fighter S on the Super Nintendo.', 'A technical 16-bit modification of the Sailor Moon fighting engine. Includes rebalanced characters, new move priorities, and refined hitboxes for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sailor-moon-fighter-s-purist-edition', 'SNES', 'Sailor Moon Fighter S (Purist Edition)', '1995', 'Fighting', 'Fan Hack', '2', 'Anime Fighting', 'Fan-made fighting game (Balanced Purist Edition Hack).', 'Experience a tournament-ready version of Sailor Moon fighting.', 'Try Sailor Moon Fighter S Purist on the SNES.', 'A specialized 16-bit romhack focused on competitive balance. Removes game-breaking bugs and standardizes damage scaling for a more professional fighting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sailormoon-france', 'SNES', 'Sailormoon (France)', '1994', 'Fighting', 'Banpresto', '2', 'Anime Fighting', 'Side-scrolling beat ''em up based on the iconic anime.', 'Save Tokyo from the Dark Kingdom as the Sailor Scouts.', 'Play the official Sailormoon on the Super Nintendo.', 'The 16-bit French release of the classic brawler. Choose from the five original scouts and use their signature magical attacks to defeat waves of enemies and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sakurai-shouichi-no-jankiryuu---mahjong-hisshouhou-japan', 'SNES', 'Sakurai Shouichi no Jankiryuu - Mahjong Hisshouhou (Japan)', '1992', 'Mahjong', 'Nichibutsu', '1', 'Mahjong', 'Educational Mahjong simulation based on the "Jankiryuu" style.', 'Learn the winning strategies of the Mahjong master Sakurai.', 'Master Mahjong with Sakurai Shouichi on Super Famicom.', 'A technical 16-bit guide to the "Jankiryuu" way of play. Features advanced tutorials, strategic analysis, and practice modes endorsed by the legend himself.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('same-game-japan', 'SNES', 'Same Game (Japan)', '1992', 'Puzzle', 'Hudson Soft', '2', 'Logic Puzzle', 'Relaxing and addictive tile-clearing puzzle game.', 'Clear the entire board by matching adjacent identical tiles.', 'Play the classic Same Game on the Super Famicom.', 'A simple yet deep 16-bit puzzle title. Strategic planning is required to clear large clusters of blocks and achieve the elusive "perfect clear" bonus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-shodown-europe', 'SNES', 'Samurai Shodown (Europe)', '1993', 'Fighting', 'SNK', '2', 'Arcade Fighting', 'Weapon-based fighting game with large sprites and zoom effects.', 'Master the blade and defeat the sorcerer Amakusa.', 'Experience the epic Samurai Shodown on the SNES.', 'A faithful 16-bit port of the SNK arcade hit. Features the legendary zoom-in camera, high-damage weapon strikes, and the unique "Rage" meter system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-shodown-usa', 'SNES', 'Samurai Shodown (USA)', '1993', 'Fighting', 'SNK', '2', 'Arcade Fighting', 'Weapon-based fighting game with a diverse roster of warriors.', 'Claim your honor in this legendary 16-bit sword fighter.', 'Play the classic Samurai Shodown on the Super Nintendo.', 'Features iconic characters like Haohmaru and Nakoruru. Master the parry mechanics and disarming moves in this high-stakes 16-bit battle for supremacy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-spirits-japan', 'SNES', 'Samurai Spirits (Japan)', '1993', 'Fighting', 'SNK', '2', 'Arcade Fighting', 'Weapon-based fighting game (Original Japanese release).', 'Experience the authentic spirit of the Samurai in Japan.', 'Play Samurai Spirits on the Super Famicom.', 'The original 16-bit Japanese version of the groundbreaking fighter. Includes full character endings and the atmospheric soundtrack that defined the Edo-period aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-spirits-japan-beta', 'SNES', 'Samurai Spirits (Japan) (Beta)', '1993', 'Fighting', 'SNK', '2', 'Arcade Fighting', 'Weapon-based fighting game (Pre-release build).', 'Test the early collision boxes and weapon sprite layers.', 'Check out the Samurai Spirits Beta on the SNES.', 'A rare 16-bit development look. Witness the early implementation of the background scaling and the balancing of the heavy slash damage before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sandro-no-daibouken---valkyrie-tono-deai-japan', 'SNES', 'Sandro no Daibouken - Valkyrie Tono Deai (Japan)', '1992', 'Action RPG', 'NCS / Enix', '1', 'Action RPG', 'Action-platformer and prequel to the Valkyrie series.', 'Meet the Valkyrie and embark on a magical 16-bit quest.', 'Experience Sandro no Daibouken on the Super Famicom.', 'Known as "Whirlo" in Europe. A challenging 16-bit platformer featuring vibrant graphics and complex jumping mechanics. Follow the journey of Sandro as he seeks his destiny.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sangokushi-eiketsuden-japan', 'SNES', 'Sangokushi Eiketsuden (Japan)', '1995', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Tactical JRPG based on the Three Kingdoms period.', 'Lead Liu Bei''s forces to unify China through strategy.', 'Experience Sangokushi Eiketsuden on the Super Famicom.', 'A 16-bit strategic RPG from Koei. Focuses on individual character growth and tactical grid-based battles during the legendary historical era of ancient China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sangokushi-iii-hong-kong', 'SNES', 'Sangokushi III (Hong Kong)', '1993', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy simulation (Hong Kong localized version).', 'Conquer the mainland in the official Chinese edition.', 'Play Sangokushi III on the Super Famicom.', 'The 16-bit Hong Kong release of Romance of the Three Kingdoms III. Features localized text and the same deep diplomatic and military simulation of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sangokushi-iii-japan', 'SNES', 'Sangokushi III (Japan)', '1993', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy simulation (Original Japanese release).', 'Unify the warring states in this 16-bit strategic epic.', 'Experience Sangokushi III on the Super Famicom.', 'A landmark 16-bit entry for the series in Japan. Manage officers, resources, and large-scale armies in a turn-based quest for total dominance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sangokushi-iii-japan-rev-a', 'SNES', 'Sangokushi III (Japan) (Rev A)', '1993', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy simulation (Updated Revision).', 'Master the refined tactical maps in this 16-bit revision.', 'Play Sangokushi III (Rev A) on the Super Famicom.', 'An updated 16-bit version that fixes minor AI pathfinding bugs and optimizes the seasonal transition events for a more stable grand strategy experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sangokushi-iv-japan', 'SNES', 'Sangokushi IV (Japan)', '1994', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Advanced grand strategy with enhanced siege mechanics.', 'Claim the throne in the most detailed entry of the series.', 'Experience Sangokushi IV on the Super Famicom.', 'Features improved 16-bit graphics and a deeper focus on technological research and naval warfare. A comprehensive simulation of the Three Kingdoms power struggle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sangokushi-seishi---tenbu-spirits-japan', 'SNES', 'Sangokushi Seishi - Tenbu Spirits (Japan)', '1995', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Strategy-RPG hybrid with a focus on historical accuracy.', 'Follow the true history of the Han Dynasty''s fall.', 'Experience Tenbu Spirits on the Super Famicom.', 'A unique 16-bit take on the Three Kingdoms story. Blends historical text-based events with tactical combat, emphasizing the personal stories of the legendary generals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sankyo-fever!-fever!-japan', 'SNES', 'Sankyo Fever! Fever! (Japan)', '1993', 'Gambling', 'Sankyo', '1', 'Pachinko Simulation', 'Pachinko simulation featuring the popular Sankyo machines.', 'Master the Fever! machines to trigger virtual jackpots.', 'Play Sankyo Fever! Fever! on the Super Famicom.', 'A technical 16-bit recreation of real Japanese Pachinko tables. Features accurate ball physics and detailed digital representations of the Sankyo brand''s mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sanrio-shanghai-japan', 'SNES', 'Sanrio Shanghai (Japan)', '1992', 'Puzzle', 'Imagineer', '2', 'Tile Matching', 'Tile-matching puzzle game featuring Sanrio characters.', 'Solve the Shanghai puzzles with Hello Kitty and friends.', 'Play Sanrio Shanghai on the Super Famicom.', 'A charming 16-bit version of the classic Mahjong Solitaire. Clear the board to unlock cute illustrations and backgrounds featuring the beloved Sanrio cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sanrio-world-smash-ball!-japan', 'SNES', 'Sanrio World Smash Ball! (Japan)', '1993', 'Sports', 'Game Freak', '2', 'Arcade Sports', 'Fast-paced competitive sports game with Sanrio mascots.', 'Score goals by smashing the ball past your opponent.', 'Play Sanrio World Smash Ball! on the Super Famicom.', 'A frantic 16-bit competitive gem. Choose your character and use power shots in various themed arenas. Widely considered one of the best 2-player games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sanrio-world-smash-ball!-japan-en-by-suicidal-v10', 'SNES', 'Sanrio World Smash Ball! (Japan) [En by Suicidal v1.0]', '1993', 'Sports', 'Game Freak / Hack', '2', 'Arcade Sports', 'Competitive sports game (Full English Translation).', 'Join Hello Kitty in this addictive 16-bit sports title.', 'Play Sanrio World Smash Ball! in English on SNES.', 'The fan translation makes the menus and power-up descriptions accessible. Experience the high-speed "Pong-on-steroids" gameplay in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sansara-naga-2-japan', 'SNES', 'Sansara Naga 2 (Japan)', '1993', 'RPG', 'Asmik Ace', '1', 'JRPG', 'Monster-breeding JRPG with a unique reincarnation system.', 'Raise your dragon and survive the cycle of life and death.', 'Explore the world of Sansara Naga 2 on Super Famicom.', 'A visually striking 16-bit RPG. Features character designs by Tamakichi Sakura and a deep system where you nurture a dragon partner to assist you in turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sanspo-fishing---keiryuu-ou-japan', 'SNES', 'Sanspo Fishing - Keiryuu Ou (Japan)', '1994', 'Sports', 'Pack-In-Video', '1', 'Fishing Simulation', 'Realistic mountain stream fishing simulation.', 'Catch the legendary "King of the Stream" in beautiful Japan.', 'Go fishing in Keiryuu Ou on the Super Famicom.', 'A technical 16-bit fishing sim. Master the art of fly-fishing in serene mountain environments, managing lure types and line tension to land the perfect catch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('satellaview-bs-x-japan-rev-ab', 'SNES', 'Satellaview BS-X (Japan) (Rev AB)', '1995', 'System', 'Nintendo', '1', 'System Software', 'Interactive BIOS and town hub for the Satellaview peripheral.', 'Explore the digital city of Lurendre to download games.', 'Experience the BS-X Satellaview on the Super Famicom.', 'A piece of 16-bit history. This interactive interface allowed Japanese players to walk through a town to access episodic content and games broadcast via satellite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saturday-night-slam-masters-europe', 'SNES', 'Saturday Night Slam Masters (Europe)', '1993', 'Wrestling', 'Capcom', '2', 'Arcade Wrestling', 'Wrestling and fighting hybrid with Capcom''s signature style.', 'Become the champion of the BWA and defeat the rival stars.', 'Play Saturday Night Slam Masters on the SNES.', 'A high-energy 16-bit brawler. Features character designs by Tetsuo Hara (Fist of the North Star) and a deep combat system that blends grappling with traditional fighting game moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saturday-night-slam-masters-usa', 'SNES', 'Saturday Night Slam Masters (USA)', '1993', 'Wrestling', 'Capcom', '2', 'Arcade Wrestling', 'Wrestling and fighting hybrid starring Mike Haggar.', 'Claim the world title in this explosive 16-bit fighter.', 'Experience Saturday Night Slam Masters on the SNES.', 'One of the most unique 16-bit sports-combat titles. Use ropes, turnbuckles, and special moves to knock out opponents in this frantic 2-player competitive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scooby-doo-mystery-usa', 'SNES', 'Scooby-Doo Mystery (USA)', '1995', 'Adventure', 'Sculptured Software', '1', 'Point-and-Click Adventure', 'Point-and-click adventure based on the classic cartoon.', 'Solve spooky mysteries with Shaggy and Scooby.', 'Play Scooby-Doo Mystery on the Super Nintendo.', 'A charming 16-bit adventure game. Solve puzzles and find clues in four different cases, featuring the original voice cast''s likeness and the show''s signature humor and art style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-f-1-grand-prix-japan', 'SNES', 'SD F-1 Grand Prix (Japan)', '1994', 'Racing', 'Video System', '1', 'SD Racing', 'Kart-style racing game with SD anime characters.', 'Win the Grand Prix in these high-speed "chibi" races.', 'Experience SD F-1 Grand Prix on the Super Famicom.', 'A fast-paced 16-bit racer featuring characters from various anime. Use power-ups and master the drifting mechanics on colorful tracks inspired by professional F1 circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-f-1-grand-prix-japan-sample', 'SNES', 'SD F-1 Grand Prix (Japan) (Sample)', '1994', 'Racing', 'Video System', '1', 'SD Racing', 'Kart-style racing game (Development Sample).', 'Test the early kart physics and track layouts.', 'Check out the SD F-1 Grand Prix Sample on SNES.', 'A rare 16-bit development look. Witness the early implementation of the character selection screen and the tuning of the AI''s racing lines before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam---power-formation-puzzle-japan', 'SNES', 'SD Gundam - Power Formation Puzzle (Japan)', '1995', 'Puzzle', 'Bandai', '2', 'Action Puzzle', 'Competitive block-matching puzzle game with Gundam themes.', 'Defeat your opponent in the puzzle arena with Mobile Suits.', 'Play SD Gundam: Power Formation Puzzle on SNES.', 'A frantic 16-bit puzzle title. Match colored energy blocks to trigger powerful Gundam attacks and clear your board while hindering your rival in split-screen combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-g-next-japan-rev-0a', 'SNES', 'SD Gundam G-Next (Japan) (Rev 0A)', '1995', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Grand strategy simulation set in the Gundam universe.', 'Dominate the galaxy through military tactics and research.', 'Master strategy in SD Gundam G-Next on Super Famicom.', 'An advanced 16-bit strategy title. Command vast fleets of Mobile Suits, manage base resources, and engage in tactical grid-based combat across multiple star systems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-gaiden---knight-gundam-monogatari---ooinaru-isan-japan', 'SNES', 'SD Gundam Gaiden - Knight Gundam Monogatari - Ooinaru Isan (Japan)', '1990', 'RPG', 'Bandai', '1', 'JRPG', 'Turn-based JRPG featuring the Knight Gundam fantasy setting.', 'Lead Knight Gundam on an epic quest to save the kingdom.', 'Explore Knight Gundam Monogatari on the Super Famicom.', 'A unique 16-bit RPG that reimagines Gundam suits as medieval knights. Features traditional turn-based combat, party management, and a rich fantasy world inspired by the SD Gaiden series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-gaiden---knight-gundam-monogatari---ooinaru-isan-japan-rev-a', 'SNES', 'SD Gundam Gaiden - Knight Gundam Monogatari - Ooinaru Isan (Japan) (Rev A)', '1990', 'RPG', 'Bandai', '1', 'JRPG', 'Turn-based JRPG (Updated Revision).', 'Experience the Knight Gundam saga with refined mechanics.', 'Play Knight Gundam Monogatari (Rev A) on Super Famicom.', 'An updated 16-bit revision that fixes minor script bugs and optimizes the battle transition speeds for a smoother role-playing experience in the Lacroan kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-gaiden-2---entaku-no-kishi-japan', 'SNES', 'SD Gundam Gaiden 2 - Entaku no Kishi (Japan)', '1991', 'RPG', 'Bandai', '1', 'JRPG', 'Turn-based JRPG sequel with the Knights of the Round Table.', 'Unify the knights and defeat the dark forces of Zeon.', 'Experience SD Gundam Gaiden 2 on the Super Famicom.', 'The 16-bit sequel featuring the "Entaku no Kishi" (Knights of the Round Table) arc. Offers expanded party systems and more detailed battle animations than its predecessor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-generation---axis-senki-japan-st', 'SNES', 'SD Gundam Generation - Axis Senki (Japan) (ST)', '1992', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Tactical strategy game for the Sufami Turbo (Axis War).', 'Win the Axis conflict using specialized Mobile Suits.', 'Play SD Gundam Generation: Axis Senki on SNES.', 'A specialized 16-bit strategy title for the Sufami Turbo accessory. Focuses on the battles of the Neo Zeon era with compact, tactical gameplay loops.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-generation---babylonia-kenkoku-senki-japan-st', 'SNES', 'SD Gundam Generation - Babylonia Kenkoku Senki (Japan) (ST)', '1992', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Tactical strategy game for the Sufami Turbo (Babylonia).', 'Establish the Cosmo Babylonia empire through conquest.', 'Experience Babylonia Kenkoku Senki on the SNES.', 'A 16-bit ST release focusing on the Gundam F91 era. Manage your units across various mission maps and engage in quick, turn-based combat scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-generation---colony-kakutouki-japan-st', 'SNES', 'SD Gundam Generation - Colony Kakutouki (Japan) (ST)', '1992', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Tactical strategy game for the Sufami Turbo (Colony).', 'Fight for colony independence in this tactical sim.', 'Play SD Gundam Generation: Colony Kakutouki on SNES.', 'An ST-specific 16-bit title focusing on Mobile Fighter G Gundam. Features tournament-style combat and strategic unit placement in various space and Earth arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-generation---gryps-senki-japan-st', 'SNES', 'SD Gundam Generation - Gryps Senki (Japan) (ST)', '1992', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Tactical strategy game for the Sufami Turbo (Gryps).', 'Lead the AEUG or Titans to victory in the Gryps War.', 'Experience Gryps Senki on the Super Famicom.', 'A 16-bit ST entry covering the events of Zeta Gundam. Command iconic Mobile Suits like the Hyaku Shiki and Zeta in tactical skirmishes against the Titans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-generation---ichinen-sensouki-japan-st', 'SNES', 'SD Gundam Generation - Ichinen Sensouki (Japan) (ST)', '1992', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Tactical strategy game for the Sufami Turbo (One Year War).', 'Relive the original Gundam conflict in this ST edition.', 'Play SD Gundam Generation: Ichinen Sensouki on SNES.', 'A 16-bit strategy game focusing on the classic 0079 story. Command the White Base crew and defeat the Zeon forces in tactical, grid-based missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-generation---zanscare-senki-japan-st', 'SNES', 'SD Gundam Generation - Zanscare Senki (Japan) (ST)', '1992', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Tactical strategy game for the Sufami Turbo (Zanscare).', 'Stop the Zanscare Empire in this high-stakes strategy sim.', 'Experience Zanscare Senki on the Super Famicom.', 'A 16-bit ST release focusing on Victory Gundam. Features advanced unit types and challenging scenarios based on the late-Universal Century conflict.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-gx-japan', 'SNES', 'SD Gundam GX (Japan)', '1994', 'Action', 'Bandai', '2', 'Action Platformer', 'Advanced tactical strategy with large-scale fleet combat.', 'Conquer the solar system in this deep Gundam sim.', 'Master the galaxy in SD Gundam GX on Super Famicom.', 'A technically impressive 16-bit strategy title. Features hundreds of units, a sophisticated AI, and real-time combat elements during individual unit encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-hiryuu-no-ken-japan', 'SNES', 'SD Hiryuu no Ken (Japan)', '1993', 'Fighting', 'Culture Brain', '2', 'Arcade Fighting', '2D fighting game featuring SD-style martial artists.', 'Win the world tournament using powerful secret techniques.', 'Play SD Hiryuu no Ken on the Super Famicom.', 'A colorful 16-bit fighter. Features a unique "target" combat system where you must hit specific points on the opponent to trigger massive damage and special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-kidou-senshi-gundam---v-sakusen-shidou-japan', 'SNES', 'SD Kidou Senshi Gundam - V Sakusen Shidou (Japan)', '1992', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Side-scrolling action-shooter based on the first Gundam series.', 'Destroy the Zeon forces and complete Operation V.', 'Experience SD Gundam: V Sakusen Shidou on SNES.', 'A fast-paced 16-bit action title. Control the RX-78-2 Gundam through various stages based on the original anime, fighting bosses like the Big Zam and Char''s Zaku.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-kidou-senshi-gundam-2-japan', 'SNES', 'SD Kidou Senshi Gundam 2 (Japan)', '1991', 'Strategy', 'Bandai', '1', 'Tactical Strategy', 'Side-scrolling action-shooter sequel with improved graphics.', 'Master the new Mobile Suits and save the Earth Federation.', 'Play SD Kidou Senshi Gundam 2 on the Super Famicom.', 'An expanded 16-bit sequel featuring more playable suits and smoother animations. Includes iconic levels and mecha from the Zeta and ZZ Gundam eras.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-the-great-battle---aratanaru-chousen-english-v10', 'SNES', 'SD The Great Battle - Aratanaru Chousen (English v1.0)', '1992', 'Action', 'Banpresto', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring SD heroes (English).', 'Join Ultraman, Gundam, and Kamen Rider to save the world.', 'Play SD The Great Battle in English on the SNES.', 'A legendary 16-bit crossover. This fan translation allows players to enjoy the first entry of the "Compati Hero" series, switching between iconic heroes to defeat evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-the-great-battle---aratanaru-chousen-japan', 'SNES', 'SD The Great Battle - Aratanaru Chousen (Japan)', '1992', 'Action', 'Banpresto', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up crossover (Japanese release).', 'Experience the ultimate SD hero alliance in Japan.', 'Play SD The Great Battle on the Super Famicom.', 'A foundational 16-bit brawler. Navigate through diverse levels and use the unique abilities of each hero to overcome platforming challenges and massive boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-ultra-battle---seven-densetsu-japan-st', 'SNES', 'SD Ultra Battle - Seven Densetsu (Japan) (ST)', '1993', 'Action', 'Banpresto', '2', 'Action Fighting', 'Tactical strategy game for the Sufami Turbo (Ultra Seven).', 'Defend Earth from alien kaiju as Ultra Seven.', 'Experience SD Ultra Battle: Seven Densetsu on SNES.', 'A specialized 16-bit ST title. Manage the Ultra Guard''s resources and deploy Ultra Seven to fight giant monsters in tactical, turn-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-ultra-battle---ultraman-densetsu-japan-st', 'SNES', 'SD Ultra Battle - Ultraman Densetsu (Japan) (ST)', '1993', 'Action', 'Banpresto', '2', 'Action Fighting', 'Tactical strategy game for the Sufami Turbo (Ultraman).', 'Relive the legend of the original Ultraman in this ST sim.', 'Play SD Ultra Battle: Ultraman Densetsu on SNES.', 'A 16-bit strategy title focusing on the classic 1966 series. Defeat iconic monsters like Baltan and Red King using Ultraman''s signature energy attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seaquest-dsv-europe', 'SNES', 'SeaQuest DSV (Europe)', '1995', 'Action', 'Imagineer', '1', 'Action Adventure', 'Submarine combat and exploration sim based on the TV show.', 'Complete underwater missions and protect the UEO.', 'Dive into SeaQuest DSV for the Super Nintendo.', 'A unique 16-bit simulation. Manage your submarine''s systems while exploring the ocean floor, engaging in tactical combat, and launching remote probes to solve environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seaquest-dsv-usa', 'SNES', 'SeaQuest DSV (USA)', '1995', 'Action', 'Imagineer', '1', 'Action Adventure', 'Submarine combat and exploration (North American release).', 'Command the SeaQuest through high-stakes ocean missions.', 'Experience SeaQuest DSV on the Super Nintendo.', 'Features impressive 16-bit underwater visuals and diverse mission types including rescue operations, deep-sea exploration, and intense torpedo combat against rival factions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-europe', 'SNES', 'Secret of Evermore (Europe)', '1995', 'Action RPG', 'Square', '1', 'Action RPG', 'Action-RPG with a unique alchemy system and time-travel theme.', 'Find your way home through the four realms of Evermore.', 'Play the cult classic Secret of Evermore on the SNES.', 'The only 16-bit RPG developed by Square USA. Explore prehistoric, antiquity, medieval, and futuristic worlds alongside your shape-shifting dog while mastering powerful alchemy spells.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-france', 'SNES', 'Secret of Evermore (France)', '1995', 'Action RPG', 'Square', '1', 'Action RPG', 'Action-RPG (French localization).', 'Voyagez à travers Evermore dans cette version française.', 'Jouez à Secret of Evermore en français sur le SNES.', 'The complete 16-bit adventure with full French text. Features atmospheric music by Jeremy Soule and the same deep alchemy system that made the original a fan favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-germany', 'SNES', 'Secret of Evermore (Germany)', '1995', 'Action RPG', 'Square', '1', 'Action RPG', 'Action-RPG (German localization).', 'Erlebe das Abenteuer von Evermore auf Deutsch.', 'Spielen Sie Secret of Evermore auf Deutsch für das SNES.', 'A fully localized 16-bit experience. Guide the hero and his canine companion through diverse eras, solving puzzles and battling bosses in a quest to return to Podunk.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-spain', 'SNES', 'Secret of Evermore (Spain)', '1995', 'Action RPG', 'Square', '1', 'Action RPG', 'Action-RPG (Spanish localization).', 'Explora el mundo de Evermore en español.', 'Disfruta de Secret of Evermore en español para el SNES.', 'One of the few 16-bit RPGs officially translated into Spanish. Experience the witty dialogue and cinematic story of a boy and his dog in this high-quality action-RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-usa', 'SNES', 'Secret of Evermore (USA)', '1995', 'Action RPG', 'Square', '1', 'Action RPG', 'Action-RPG featuring real-time combat and canine partner.', 'Master the elements of alchemy to survive Evermore.', 'Experience the epic Secret of Evermore on the SNES.', 'Features a unique ring-menu system and real-time combat. A technical 16-bit achievement known for its incredible ambient sound design and vast, interconnected world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-usa-hack-by-fusoya-v102-2-player-edition', 'SNES', 'Secret of Evermore (USA) [Hack by FuSoYa v1.02] (2 Player Edition)', '1995', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (2-Player Enhancement Hack).', 'Team up with a friend to control both the hero and the dog.', 'Play Secret of Evermore (2-Player) on the SNES.', 'A groundbreaking 16-bit fan modification. This hack allows a second player to take control of the dog, turning the solo adventure into a fully cooperative experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-usa-hack-by-fusoya-v102-hack-by-ninakoru-v10-balance-enhancement---2-player-edition', 'SNES', 'Secret of Evermore (USA) [Hack by FuSoYa v1.02] [Hack by Ninakoru v1.0] (Balance Enhancement - 2 Player Edition)', '1995', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (Balance & 2-Player Enhancement Hack).', 'Experience a balanced cooperative journey through Evermore.', 'Try the Secret of Evermore Balance/2-Player Hack.', 'A 16-bit overhaul that combines cooperative play with rebalanced alchemy costs and enemy stats, providing a more challenging and fair experience for two players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-evermore-usa-hack-by-ninakoru-v10-balance-enhancement', 'SNES', 'Secret of Evermore (USA) [Hack by Ninakoru v1.0] (Balance Enhancement)', '1995', 'Action RPG', 'Square', '1', 'Action RPG', 'Action-RPG (Balance Enhancement Hack).', 'Test your skills with refined combat and alchemy mechanics.', 'Play Secret of Evermore (Balance Mod) on the SNES.', 'A technical 16-bit modification that tweaks spell damage and enemy AI. Designed for veterans seeking a fresh challenge in the world of Evermore without altering the story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-europe', 'SNES', 'Secret of Mana (Europe)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Landmark Action-RPG with 3-player cooperative play.', 'Save the Mana Tree and the world from the Empire.', 'Play the legendary Secret of Mana on the SNES.', 'One of the greatest 16-bit RPGs ever made. Features a beautiful watercolor art style, a real-time "Ring Command" menu, and an iconic soundtrack by Hiroki Kikuta.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-europe-rev-1-hack-by-masterflow-v102-hard-mode', 'SNES', 'Secret of Mana (Europe) (Rev 1) [Hack by Masterflow v1.02] (Hard Mode)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (Hard Mode Fan Modification).', 'Survive the ultimate challenge in this high-difficulty mod.', 'Play Secret of Mana (Hard Mode) on the Super Nintendo.', 'A 16-bit modification that increases enemy HP and aggression. Perfect for players who find the original game too easy and want to test their tactical mastery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-europe-rev-a', 'SNES', 'Secret of Mana (Europe) (Rev A)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (Updated European Revision).', 'Restore the power of Mana in this polished 16-bit classic.', 'Experience Secret of Mana (Rev A) on the SNES.', 'The refined 16-bit PAL release. Fixes minor text errors and balancing issues from the initial launch, ensuring a smooth cooperative experience for up to three players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-europe-hack-by-masterflow-v102-hard-mode', 'SNES', 'Secret of Mana (Europe) [Hack by Masterflow v1.02] (Hard Mode)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (Hard Mode Fan Modification).', 'Survive the ultimate challenge in this high-difficulty mod.', 'Play Secret of Mana (Hard Mode) on the Super Nintendo.', 'A 16-bit modification that increases enemy HP and aggression. Perfect for players who find the original game too easy and want to test their tactical mastery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-france', 'SNES', 'Secret of Mana (France)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (French localization).', 'Sauvez l''arbre de Mana dans la version française.', 'Jouez à Secret of Mana en français sur le SNES.', 'The complete 16-bit masterpiece localized for French players. Experience the emotional journey of Randi, Primm, and Popoi with full French dialogue and menus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-france-rev-a', 'SNES', 'Secret of Mana (France) (Rev A)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (French Updated Revision).', 'Vivez l''épopée de Mana dans cette version optimisée.', 'Découvrez Secret of Mana (Rev A) sur le SNES.', 'The updated 16-bit French release featuring minor corrections to the script and improved stability for the cooperative multiplayer mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-germany', 'SNES', 'Secret of Mana (Germany)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (German localization).', 'Rette die Welt von Mana in dieser deutschen Version.', 'Spielen Sie Secret of Mana auf Deutsch für das SNES.', 'A legendary 16-bit localization known for its unique (and sometimes controversial) German script. Experience the classic 3-player action in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-usa', 'SNES', 'Secret of Mana (USA)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG featuring real-time combat and the Mana Sword.', 'Defeat the eight Mana Beasts and restore balance.', 'Experience the magic of Secret of Mana on the SNES.', 'The definitive 16-bit action-RPG experience. Master the weapon levels and magic elements while traveling through one of the most vibrant worlds on the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-usa-en-by-fusoya-v10-variable-width-font-edition', 'SNES', 'Secret of Mana (USA) [En by FuSoYa v1.0] (Variable Width Font Edition)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (Variable Width Font Enhancement).', 'Read the story with improved, modern 16-bit typography.', 'Play Secret of Mana (VWF Edition) on the SNES.', 'A technical 16-bit modification by FuSoYa. Replaces the standard font with a more readable, proportional font, making the extensive dialogue much easier on the eyes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-usa-en-by-fusoya-v10-hack-by-masterflow-v102-hard-mode', 'SNES', 'Secret of Mana (USA) [En by FuSoYa v1.0] [Hack by Masterflow v1.02] (Hard Mode)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (VWF & Hard Mode Hybrid Hack).', 'Face a brutal challenge with polished typography.', 'Try the Secret of Mana Hard Mode (VWF) on SNES.', 'Combines improved readability with increased difficulty. A 16-bit fan project designed for the ultimate Mana fan looking for a modern and tough experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-mana-usa-hack-by-masterflow-v102-hard-mode', 'SNES', 'Secret of Mana (USA) [Hack by Masterflow v1.02] (Hard Mode)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'Action-RPG (Hard Mode Fan Modification).', 'Survive the ultimate challenge in this high-difficulty mod.', 'Play Secret of Mana (Hard Mode) on the Super Nintendo.', 'A 16-bit modification that increases enemy HP and aggression. Perfect for players who find the original game too easy and want to test their tactical mastery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seifuku-densetsu-pretty-fighter-japan', 'SNES', 'Seifuku Densetsu Pretty Fighter (Japan)', '1994', 'Fighting', 'SNK', '2', 'Arcade Fighting', 'All-female 2D fighting game with anime aesthetics.', 'Win the tournament and prove your fighting spirit.', 'Play Seifuku Densetsu Pretty Fighter on SNES.', 'A colorful 16-bit fighter featuring high-school girls in diversas outfits. Features large sprites, special move transformations, and a lighthearted, comedic tone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seijuu-maden-beasts-&-blades-japan', 'SNES', 'Seijuu Maden Beasts & Blades (Japan)', '1995', 'RPG', 'SNK', '1', 'JRPG', 'Tactical JRPG with a focus on beast summoning.', 'Lead your team of warriors and beasts to save the land.', 'Explore Seijuu Maden Beasts & Blades on the SNES.', 'A unique 16-bit strategy-RPG hybrid. Use a grid-based combat system where summoning and managing mythical beasts is key to defeating the invading dark forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seiken-densetsu-2-japan', 'SNES', 'Seiken Densetsu 2 (Japan)', '1993', 'Action RPG', 'Square', '2', 'Action RPG', 'The original Japanese release of Secret of Mana.', 'Experience the foundational "Mana" magic in Japan.', 'Play Seiken Densetsu 2 on the Super Famicom.', 'The 16-bit masterpiece that popularized the "Ring Command" system. Known for its incredible technical use of the SNES hardware to deliver a seamless cooperative adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seiken-densetsu-3-japan', 'SNES', 'Seiken Densetsu 3 (Japan)', '1995', 'Action RPG', 'Square', '3', 'Action RPG', 'Epic Action-RPG with 6 playable characters and branching paths.', 'Choose three heroes and stop the God-Beasts.', 'Experience the stunning Seiken Densetsu 3 on SNES.', 'A 16-bit technical marvel. Features a day/night cycle, a class change system, and three distinct storylines depending on the main protagonist you choose.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seiken-densetsu-3-japan-sample', 'SNES', 'Seiken Densetsu 3 (Japan) (Sample)', '1995', 'Action RPG', 'Square', '3', 'Action RPG', 'Action-RPG (Development Sample).', 'Test the early combat physics and character selection.', 'Check out the Seiken Densetsu 3 Sample on SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character introduction sequences and the tuning of the real-time battle engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seiken-densetsu-3-japan-en-by-lnf+neill-corlett+som2freak-v101', 'SNES', 'Seiken Densetsu 3 (Japan) [En by LNF+Neill Corlett+SoM2Freak v1.01]', '1995', 'Action RPG', 'Square', '3', 'Action RPG', 'Action-RPG (Full English Translation v1.01).', 'Experience the unreleased Mana sequel in English.', 'Play Seiken Densetsu 3 in English on the SNES.', 'The legendary 16-bit fan translation. Brings the complex story and deep class system of the second Mana game to Western audiences for the first time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seiken-densetsu-3-japan-en-by-lnf+neill-corlett+som2freak-v101-hack-by-parlance-v10-3-player-edition', 'SNES', 'Seiken Densetsu 3 (Japan) [En by LNF+Neill Corlett+SoM2Freak v1.01] [Hack by Parlance v1.0] (3 Player Edition)', '1995', 'Action RPG', 'Square', '3', 'Action RPG', 'Action-RPG (English & 3-Player Enhancement Hack).', 'Play through the epic sequel with two friends in English.', 'Try Seiken Densetsu 3 (3-Player Mode) on SNES.', 'A 16-bit fan modification that unlocks the third player slot, allowing a full party to be controlled by humans. Perfect for the ultimate cooperative RPG session.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seiken-densetsu-3-japan-en-by-lnf+neill-corlett+som2freak-v101-title-hack-by-dragonsbrethren-v10-~secret-of-mana-2', 'SNES', 'Seiken Densetsu 3 (Japan) [En by LNF+Neill Corlett+SoM2Freak v1.01] [Title Hack by Dragonsbrethren v1.0] (~Secret of Mana 2)', '1995', 'Action RPG', 'Square', '3', 'Action RPG', 'Action-RPG (English Translation with Secret of Mana 2 Title).', 'Play the sequel as if it were officially localized.', 'Experience Secret of Mana 2 (SD3) on the SNES.', 'A 16-bit fan translation that uses the "Secret of Mana 2" title branding. Features the complete English script and optimized menus for a professional feel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sengoku-denshou-japan', 'SNES', 'Sengoku Denshou (Japan)', '1993', 'Action', 'SNK', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with a supernatural theme.', 'Defeat the dark warriors across feudal and modern Japan.', 'Experience Sengoku Denshou on the Super Famicom.', 'A faithful 16-bit port of the Neo Geo arcade hit. Features the ability to transform into a wolf, a ninja, or a samurai to battle demonic forces across time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sengoku-no-hasha---tenkafubu-e-no-michi-japan', 'SNES', 'Sengoku no Hasha - Tenkafubu e no Michi (Japan)', '1990', 'Strategy', 'Koei', '1', 'Grand Strategy', 'Grand strategy simulation set in the Warring States period.', 'Unify Japan as a powerful Daimyo through war and diplomacy.', 'Play Sengoku no Hasha on the Super Famicom.', 'A deep 16-bit historical simulation. Manage your clan''s resources, forge alliances, and engage in tactical grid-based battles to claim the title of Shogun in feudal Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sensible-soccer---international-edition-europe-enfrdeit', 'SNES', 'Sensible Soccer - International Edition (Europe) (En,Fr,De,It)', '1994', 'Sports', 'Sensible Software', '2', 'Soccer', 'Fast-paced top-down soccer with international teams.', 'Win the World Championship with agile passing and shooting.', 'Play Sensible Soccer: International Edition on SNES.', 'A 16-bit sports classic known for its zoomed-out perspective and ultra-responsive controls. Features hundreds of teams and a simplified, addictive approach to the beautiful game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sensible-soccer-europe-enfrdeit', 'SNES', 'Sensible Soccer (Europe) (En,Fr,De,It)', '1994', 'Sports', 'Sensible Software', '2', 'Soccer', 'Fast-paced top-down soccer simulation.', 'Master the curve shots and quick tackles in this 16-bit sim.', 'Experience the original Sensible Soccer on the SNES.', 'The foundational 16-bit entry for the series. Focuses on speed and tactical positioning, offering a pure arcade-style football experience that is easy to learn but hard to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sensible-soccer-europe-enfrdeit-beta', 'SNES', 'Sensible Soccer (Europe) (En,Fr,De,It) (Beta)', '1994', 'Sports', 'Sensible Software', '2', 'Soccer', 'Top-down soccer simulation (Pre-release build).', 'Test the early player physics and ball-curving logic.', 'Check out the Sensible Soccer Beta on the SNES.', 'A rare 16-bit development look. Witness the fine-tuning of the sensitive control scheme and the initial implementation of the tournament menu structures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('septentrion-japan', 'SNES', 'Septentrion (Japan)', '1993', 'Adventure', 'Human Entertainment', '1', 'Survival Adventure', 'Cinematic survival adventure set on a sinking luxury liner.', 'Escape the ship before it capsizes and save as many survivors as possible.', 'Experience the intense Septentrion on Super Famicom.', 'Known as SOS in the West. Uses 16-bit Mode 7 effects to rotate the entire screen as the ship tilts, creating a terrifying and unique race against time and rising water.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('serizawa-nobuo-no-birdie-try-japan', 'SNES', 'Serizawa Nobuo no Birdie Try (Japan)', '1993', 'Sports', 'Naxat Soft', '1', 'Golf', 'Professional golf simulation featuring Nobuo Serizawa.', 'Master the greens and win the professional tournament circuit.', 'Play Serizawa Nobuo no Birdie Try on Super Famicom.', 'A technical 16-bit golf game. Features realistic wind physics, club selection, and detailed courses endorsed by the Japanese pro golfer Nobuo Serizawa.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sgt-saunders-combat!-japan', 'SNES', 'Sgt. Saunders'' Combat! (Japan)', '1993', 'Strategy', 'ASCII', '1', 'Turn-Based Strategy', 'Tactical military strategy based on the 1960s TV show.', 'Lead your squad through WWII missions in occupied France.', 'Play Sgt. Saunders'' Combat! on the Super Famicom.', 'A rare 16-bit tactical sim. Command a squad of soldiers in turn-based combat, managing cover, line-of-sight, and ammunition to complete dangerous objectives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-the-usa-proto-50a3', 'SNES', 'Shadow, The (USA) (Proto) [50A3]', '1994', 'Action', 'Sunsoft', '1', 'Action Adventure', 'Side-scrolling beat ''em up based on the pulp hero (Prototype).', 'Stop the criminal underworld as the mysterious Shadow.', 'Explore The Shadow Prototype on the SNES.', 'A rare 16-bit unreleased brawler. Features impressive character sprites and atmospheric urban levels where you use martial arts and dual pistols to fight crime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-the-usa-proto-97e7', 'SNES', 'Shadow, The (USA) (Proto) [97E7]', '1994', 'Action', 'Sunsoft', '1', 'Action Adventure', 'Side-scrolling beat ''em up (Revised Prototype build).', 'Test the advanced combat moves and unreleased stage layouts.', 'Discover The Shadow (97E7 Proto) on the SNES.', 'An alternate 16-bit development build. Witness the evolution of the combat engine and the cinematic cutscenes based on the 1994 film adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowrun-europe', 'SNES', 'Shadowrun (Europe)', '1993', 'RPG', 'FASA Interactive', '1', 'Cyberpunk RPG', 'Isometric Action-RPG set in a gritty cyberpunk future.', 'Solve the mystery of your own murder in the sprawl of Seattle.', 'Experience the cult classic Shadowrun on the SNES.', 'A 16-bit masterpiece of atmosphere. Features a unique "keyword" dialogue system, hacking into the Matrix, and tactical real-time combat in a dark urban fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowrun-germany', 'SNES', 'Shadowrun (Germany)', '1993', 'RPG', 'FASA Interactive', '1', 'Cyberpunk RPG', 'Isometric Action-RPG (German localization).', 'Erkunde die Cyberpunk-Welt von Shadowrun auf Deutsch.', 'Spielen Sie Shadowrun auf Deutsch für das SNES.', 'The complete 16-bit cyberpunk adventure with full German text. Navigate the dangerous streets as Jake Armitage and uncover a conspiracy involving megacorporations and magic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowrun-japan', 'SNES', 'Shadowrun (Japan)', '1993', 'RPG', 'FASA Interactive', '1', 'Cyberpunk RPG', 'Isometric Action-RPG (Japanese release).', 'Experience the dark futuristic Seattle in the Japanese edition.', 'Play Shadowrun on the Super Famicom.', 'The official 16-bit Japanese release of this Western-developed RPG. Retains the gritty tone and deep investigative gameplay that made it a global cult favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowrun-sweden', 'SNES', 'Shadowrun (Sweden)', '1993', 'RPG', 'FASA Interactive', '1', 'Cyberpunk RPG', 'Isometric Action-RPG (Swedish localization).', 'Upplev det mörka Shadowrun-äventyret på svenska.', 'Spela Shadowrun på svenska för Super Nintendo.', 'A rare 16-bit localization for the Swedish market. Features the same deep RPG mechanics and atmospheric storytelling translated for Nordic fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowrun-usa', 'SNES', 'Shadowrun (USA)', '1993', 'RPG', 'FASA Interactive', '1', 'Cyberpunk RPG', 'Isometric Action-RPG featuring magic and technology.', 'Master the Matrix and solve the conspiracy in 2050.', 'Experience the legendary Shadowrun on the SNES.', 'Known for its mature story and innovative gameplay. Use your 16-bit decking skills to hack computers and recruit mercenaries to survive the shadows.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowrun-usa-beta', 'SNES', 'Shadowrun (USA) (Beta)', '1993', 'RPG', 'FASA Interactive', '1', 'Cyberpunk RPG', 'Isometric Action-RPG (Pre-release build).', 'Test the early combat hitboxes and dialogue triggers.', 'Check out the Shadowrun Beta on the Super Nintendo.', 'A rare 16-bit development slice. Witness the early implementation of the karma system and the tuning of the real-time combat encounters in the morgue and street levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai---banri-no-choujou-japan', 'SNES', 'Shanghai - Banri no Choujou (Japan)', '1991', 'Puzzle', 'Sunsoft', '2', 'Board Puzzle', 'Advanced Mahjong Solitaire simulation (Great Wall theme).', 'Clear the tile patterns to unlock beautiful Asian landscapes.', 'Play Shanghai: Banri no Choujou on Super Famicom.', 'A polished 16-bit puzzle title. Features multiple difficulty modes, high-quality tile art, and relaxing music, all centered around the theme of the Great Wall of China.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai---banri-no-choujou-japan-rev-a', 'SNES', 'Shanghai - Banri no Choujou (Japan) (Rev A)', '1991', 'Puzzle', 'Sunsoft', '2', 'Board Puzzle', 'Advanced Mahjong Solitaire (Updated Revision).', 'Master the tile layouts in this refined puzzle edition.', 'Experience Shanghai (Rev A) on the Super Famicom.', 'An updated 16-bit revision that optimizes tile-shuffling algorithms and fixes minor graphical glitches in the background art transitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai-ii---dragons-eye-europe', 'SNES', 'Shanghai II - Dragon''s Eye (Europe)', '1993', 'Puzzle', 'Hot-B', '2', 'Board Puzzle', 'Tile-matching puzzle game with multiple play modes.', 'Match identical tiles to clear the board in various challenges.', 'Play Shanghai II: Dragon''s Eye on the SNES.', 'An expanded 16-bit puzzle experience. Includes the classic Solitaire mode and the unique "Dragon''s Eye" challenge, featuring vibrant graphics and diverse tile sets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai-ii---dragons-eye-usa', 'SNES', 'Shanghai II - Dragon''s Eye (USA)', '1993', 'Puzzle', 'Hot-B', '2', 'Board Puzzle', 'Tile-matching puzzle game with multiple play modes.', 'Master the art of Shanghai in the official North American version.', 'Experience Shanghai II on the Super Nintendo.', 'A meditative 16-bit puzzle classic. Offers a variety of layouts and themes, providing hours of strategic tile-clearing gameplay for fans of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai-iii-japan', 'SNES', 'Shanghai III (Japan)', '1994', 'Puzzle', 'Hot-B', '2', 'Board Puzzle', 'Competitive and classic Mahjong Solitaire.', 'Clear the tiles faster than your opponent in this 16-bit sim.', 'Play Shanghai III on the Super Famicom.', 'The third 16-bit entry in the series. Features improved animations, more complex tile patterns, and a robust competitive mode to test your speed and pattern recognition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaq-fu-europe', 'SNES', 'Shaq Fu (Europe)', '1994', 'Fighting', 'Delphine Software', '2', 'Arcade Fighting', 'One-on-one fighting game starring basketball legend Shaquille O''Neal.', 'Defeat the interdimensional warriors and save the boy Nezu.', 'Experience the unique Shaq Fu on the SNES.', 'A 16-bit fighter known for its fluid animation and bizarre premise. Travel to the Second World and use Shaq''s martial arts to defeat supernatural foes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaq-fu-usa', 'SNES', 'Shaq Fu (USA)', '1994', 'Fighting', 'Delphine Software', '2', 'Arcade Fighting', 'One-on-one fighting game featuring digitized-style animation.', 'Master the "Shaq-ido" to become the ultimate champion.', 'Play Shaq Fu for the Super Nintendo.', 'Features a story mode and a competitive 2-player mode. A 16-bit curiosity that captures the celebrity-driven gaming trends of the mid-90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaq-fu-usa-beta', 'SNES', 'Shaq Fu (USA) (Beta)', '1994', 'Fighting', 'Delphine Software', '2', 'Arcade Fighting', 'One-on-one fighting game (Pre-release build).', 'Test the character frame data and special move hitboxes.', 'Check out the Shaq Fu Beta on the SNES.', 'A rare 16-bit development look. Witness the early implementation of the background parallax and the balancing of the character-specific projectile attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shichuusuimeigaku-nyuumon---shin-tougenkyou-japan', 'SNES', 'Shichuusuimeigaku Nyuumon - Shin Tougenkyou (Japan)', '1995', 'Educational', 'Hect', '1', 'Fortune Telling', 'Fortune-telling and astrology simulation.', 'Predict your destiny using traditional Chinese Four Pillars methods.', 'Explore Shichuusuimeigaku Nyuumon on Super Famicom.', 'A unique 16-bit utility/simulation game. Enter birth data to receive detailed astrological readings and predictions based on ancient Eastern wisdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shien---the-blade-chaser-japan', 'SNES', 'Shien - The Blade Chaser (Japan)', '1994', 'Action', 'NCS', '1', 'Action Platformer', 'First-person ninja action game using the SNES Mouse or Pad.', 'Defeat the evil sorcerer and his army as a master ninja.', 'Play Shien: The Blade Chaser on Super Famicom.', 'A rare 16-bit action title where you use on-screen slashes to defeat enemies. Features fast-paced combat and impressive first-person sprites and environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shiens-revenge-usa', 'SNES', 'Shien''s Revenge (USA)', '1994', 'Action', 'NCS', '1', 'Action Platformer', 'First-person ninja action game (Western release).', 'Avenge your clan in this unique 16-bit first-person slasher.', 'Experience Shien''s Revenge on the Super Nintendo.', 'Compatible with the SNES Mouse for an authentic "sword-slashing" feel. Navigate through diverse historical stages and defeat massive bosses in tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shiens-revenge-usa-beta', 'SNES', 'Shien''s Revenge (USA) (Beta)', '1994', 'Action', 'NCS', '1', 'Action Platformer', 'First-person ninja action game (Pre-release build).', 'Test the early slash detection and enemy spawn rates.', 'Check out the Shien''s Revenge Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the projectile-deflection mechanics and the evolution of the first-person level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shijou-saikyou-league-serie-a---ace-striker-japan', 'SNES', 'Shijou Saikyou League Serie A - Ace Striker (Japan)', '1994', 'Sports', 'Tose', '2', 'Soccer', 'Soccer simulation featuring the Italian Serie A league.', 'Lead your team to the top of the Italian league standings.', 'Play Serie A: Ace Striker on the Super Famicom.', 'A polished 16-bit soccer title. Features authentic teams from the Italian league, strategic formations, and smooth arcade-style gameplay with a focus on fast-paced scoring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shijou-saikyou-no-quiz-ou-ketteisen-super-japan', 'SNES', 'Shijou Saikyou no Quiz Ou Ketteisen Super (Japan)', '1995', 'Quiz', 'Game Studio', '2', 'Quiz Game', 'Competitive trivia and quiz show simulation.', 'Become the "Quiz King" by answering hundreds of questions.', 'Play Shijou Saikyou no Quiz Ou on Super Famicom.', 'An engaging 16-bit quiz game. Features a variety of categories, multiple game modes including a TV-style tournament, and challenging AI opponents to test your general knowledge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shiki-eiyuuden---jinryuu-densetsu-japan', 'SNES', 'Shiki Eiyuuden - Jinryuu Densetsu (Japan)', '1995', 'RPG', 'Neverland', '1', 'JRPG', 'Turn-based JRPG set in a mystical world of dragons.', 'Protect the dragon legend and defeat the rising evil.', 'Explore Shiki Eiyuuden on the Super Famicom.', 'A classic 16-bit JRPG with a focus on traditional turn-based combat and narrative world-building. Features detailed sprite work and a party-based system in a high-fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shimono-masaki-no-fishing-to-bassing-japan', 'SNES', 'Shimono Masaki no Fishing to Bassing (Japan)', '1994', 'Sports', 'Pack-In-Video', '1', 'Fishing', 'Realistic bass fishing simulation in Japan.', 'Catch the biggest bass and master the Japanese lakes.', 'Go fishing in Shimono Masaki no Fishing on SNES.', 'A technical 16-bit fishing sim. Manage your lure selection and casting technique based on real-world conditions, endorsed by professional fisherman Masaki Shimono.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-chou-kouki-japan', 'SNES', 'Shin Chou Kouki (Japan)', '1992', 'Action', 'Face', '1', 'Action Shooter', 'Turn-based strategy set in ancient China.', 'Unify the warring states in this tactical historical sim.', 'Master strategy in Shin Chou Kouki on Super Famicom.', 'A deep 16-bit simulation from Koei. Manage your territory, recruit legendary generals, and engage in grid-based tactical warfare to conquer the mainland.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-ikkakusenkin-japan', 'SNES', 'Shin Ikkakusenkin (Japan)', '1994', 'Strategy', 'NCS', '1', 'Turn-Based Strategy', 'High-stakes gambling and horse racing simulation.', 'Win a fortune through strategic betting and luck.', 'Experience Shin Ikkakusenkin on the Super Famicom.', 'A detailed 16-bit gambling sim. Navigate the world of Japanese horse racing, analyzing stats and odds to turn a small stake into a massive payday.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-kidou-senki-gundam-w---endless-duel-japan', 'SNES', 'Shin Kidou Senki Gundam W - Endless Duel (Japan)', '1996', 'Fighting', 'Natsume', '2', 'Anime Fighting', 'High-speed 2D fighting game featuring Mobile Suits.', 'Win the Gundam Wing tournament with intense combos.', 'Play Gundam Wing: Endless Duel on Super Famicom.', 'Widely considered one of the best 16-bit fighters. Features incredible animations, a technical "Vernier" dash system, and massive, screen-filling special attacks from the Wing series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-kidou-senki-gundam-w---endless-duel-japan-en-by-aeon-genesis-v10-~mobile-suit-gundam-wing---endless-duel', 'SNES', 'Shin Kidou Senki Gundam W - Endless Duel (Japan) [En by Aeon Genesis v1.0] (~Mobile Suit Gundam Wing - Endless Duel)', '1996', 'Fighting', 'Natsume', '2', 'Anime Fighting', 'High-speed 2D fighting game (English Translation).', 'Experience the ultimate Gundam fighter in English.', 'Play Gundam Wing: Endless Duel in English on SNES.', 'The Aeon Genesis 16-bit translation makes this legendary fighter accessible. Master the technical combat and pilot your favorite Mobile Suit in a quest for total dominance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-mahjong-japan', 'SNES', 'Shin Mahjong (Japan)', '1994', 'Mahjong', 'Nichibutsu', '2', 'Mahjong', 'Traditional Mahjong simulation with updated rules.', 'Master the tiles and defeat the professional AI masters.', 'Play Shin Mahjong on the Super Famicom.', 'A refined 16-bit Mahjong title. Features multiple game modes, detailed statistics, and a clean interface designed for both casual and professional players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-japan', 'SNES', 'Shin Megami Tensei (Japan)', '1992', 'RPG', 'Atlus', '1', 'JRPG', 'Dark first-person dungeon-crawling RPG.', 'Navigate a post-apocalyptic Tokyo and recruit demons.', 'Experience the original Shin Megami Tensei on SNES.', 'The landmark 16-bit RPG that birthed the SMT franchise. Master the demon negotiation system and make moral choices that determine the fate of humanity in a dark, urban setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-japan-rev-a', 'SNES', 'Shin Megami Tensei (Japan) (Rev A)', '1992', 'RPG', 'Atlus', '1', 'JRPG', 'Dark dungeon-crawling RPG (Updated Revision).', 'Experience the refined classic with bug fixes.', 'Play Shin Megami Tensei (Rev A) on Super Famicom.', 'The optimized 16-bit revision of the first SMT. Includes minor balancing tweaks and fixes for the demon fusion system, ensuring a smoother journey through the occult apocalypse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-japan-en-by-aeon-genesis-v10', 'SNES', 'Shin Megami Tensei (Japan) [En by Aeon Genesis v1.0]', '1992', 'RPG', 'Atlus', '1', 'JRPG', 'Dark dungeon-crawling RPG (English Translation).', 'Play the legendary occult RPG in English for the first time.', 'Experience Shin Megami Tensei in English on the SNES.', 'The definitive 16-bit translation by Aeon Genesis. Fully localized the complex demon-fusing mechanics and the deep, philosophical story of the struggle between Law and Chaos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-if-english', 'SNES', 'Shin Megami Tensei if... (English)', '1994', 'RPG', 'Atlus', '1', 'JRPG', 'Experimental dungeon-crawling RPG (English Translation).', 'Survive the demon-infested school in this SMT spin-off.', 'Play Shin Megami Tensei if... in English on SNES.', 'The 16-bit precursor to the "Persona" series. This fan translation allows players to navigate a high school trapped in a demon realm, featuring the innovative Guardian system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-if-japan', 'SNES', 'Shin Megami Tensei if... (Japan)', '1994', 'RPG', 'Atlus', '1', 'JRPG', 'Experimental dungeon-crawling RPG set in a high school.', 'Escape the demon dimension and defeat the Hazama.', 'Play Shin Megami Tensei if... on the Super Famicom.', 'A unique 16-bit entry in the SMT saga. Focuses on a smaller, more personal scale, introducing mechanics like the Moon phase and specialized character growth paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-ii-japan', 'SNES', 'Shin Megami Tensei II (Japan)', '1994', 'RPG', 'Atlus', '1', 'JRPG', 'First-person dungeon-crawling RPG sequel.', 'Navigate the futuristic Tokyo Millennium and solve the mystery.', 'Experience Shin Megami Tensei II on Super Famicom.', 'A massive 16-bit sequel. Expands on the demon fusion and negotiation systems, featuring a deeper narrative that explores religious and cyberpunk themes in a dystopian world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-ii-japan-en-by-aeon-genesis-v10', 'SNES', 'Shin Megami Tensei II (Japan) [En by Aeon Genesis v1.0]', '1994', 'RPG', 'Atlus', '1', 'JRPG', 'First-person dungeon-crawling RPG sequel (English).', 'Reclaim your destiny in this translated cyberpunk epic.', 'Play Shin Megami Tensei II in English on the SNES.', 'The Aeon Genesis 16-bit translation allows Western fans to experience the full scale of this massive RPG. Features improved menus and a fully localized script for the complex plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-momotarou-densetsu-japan', 'SNES', 'Shin Momotarou Densetsu (Japan)', '1993', 'RPG', 'Hudson Soft', '1', 'JRPG', 'Turn-based JRPG based on Japanese folklore.', 'Lead Momotarou and his animal companions to save Japan.', 'Explore Shin Momotarou Densetsu on Super Famicom.', 'A high-quality 16-bit RPG from Hudson Soft. Features beautiful graphics, a deep turn-based battle system, and a heartwarming story inspired by the classic peach-boy legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-naki-no-ryuu---mahjong-hishouden-japan', 'SNES', 'Shin Naki no Ryuu - Mahjong Hishouden (Japan)', '1995', 'Mahjong', 'Nichibutsu', '2', 'Mahjong', 'Competitive Mahjong with a cinematic story.', 'Win the underground tournaments in this Mahjong epic.', 'Play Shin Naki no Ryuu on the Super Famicom.', 'Based on the popular manga. Features 16-bit cinematic cutscenes and high-stakes Mahjong matches where strategy and "crying" the tiles is key to victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nekketsu-kouha---kunio-tachi-no-banka-japan', 'SNES', 'Shin Nekketsu Kouha - Kunio-tachi no Banka (Japan)', '1994', 'Action', 'Technos Japan', '2', 'Beat ''em Up', 'Cinematic side-scrolling beat ''em up (Renegade sequel).', 'Clear your name and defeat the Yakuza in this gritty brawler.', 'Experience Kunio-tachi no Banka on Super Famicom.', 'A mature 16-bit entry in the Nekketsu series. Features a continuous narrative, multiple playable characters like Misako and Kyoko, and intense combat across a dark urban landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nekketsu-kouha---kunio-tachi-no-banka-japan-en-by-aeon-genesis-v10-renegade-2', 'SNES', 'Shin Nekketsu Kouha - Kunio-tachi no Banka (Japan) [En by Aeon Genesis v1.0] (Renegade 2)', '1994', 'Action', 'Technos Japan', '2', 'Beat ''em Up', 'Cinematic side-scrolling beat ''em up (English Translation).', 'Experience the gritty Kunio-kun story in English.', 'Play Renegade 2: Kunio-tachi no Banka on the SNES.', 'The Aeon Genesis 16-bit translation brings this cinematic brawler to English audiences. Features a deep story, vehicle stages, and refined martial arts combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nihon-pro-wresling---chou-senshi-in-tokyo-dome---fantastic-story-japan', 'SNES', 'Shin Nihon Pro Wresling - Chou Senshi in Tokyo Dome - Fantastic Story (Japan)', '1995', 'Wrestling', 'Varie', '2', 'Pro Wrestling', 'Professional wrestling simulation (New Japan Pro).', 'Win the G1 Climax and conquer the Tokyo Dome.', 'Experience Fantastic Story on the Super Famicom.', 'A technical 16-bit wrestling sim featuring the legends of NJPW. Includes a variety of match types and a deep stamina-based grappling system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nihon-pro-wresling-kounin---94-battlefield-in-tokyo-dome-japan', 'SNES', 'Shin Nihon Pro Wresling Kounin - ''94 Battlefield in Tokyo Dome (Japan)', '1994', 'Wrestling', 'Varie', '2', 'Pro Wrestling', 'Professional wrestling simulation (New Japan Pro ''94).', 'Master the ring in this official 16-bit wrestling sim.', 'Play ''94 Battlefield in Tokyo Dome on Super Famicom.', 'Features the official 1994 NJPW roster. A robust 16-bit title focusing on realistic movesets and tactical pacing in high-stakes Tokyo Dome events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nihon-pro-wresling-kounin---95-tokyo-dome-battle-7-japan', 'SNES', 'Shin Nihon Pro Wresling Kounin - ''95 Tokyo Dome Battle 7 (Japan)', '1995', 'Wrestling', 'Varie', '2', 'Pro Wrestling', 'Professional wrestling simulation (New Japan Pro ''95).', 'Claim the championship in the final SNES NJPW title.', 'Play Tokyo Dome Battle 7 on the Super Famicom.', 'The most refined 16-bit wrestling entry in the series. Features improved graphics, more fluid animations, and a massive roster of legendary Japanese wrestlers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-sd-sengokuden---daishougun-retsuden-japan', 'SNES', 'Shin SD Sengokuden - Daishougun Retsuden (Japan)', '1993', 'Strategy', 'Bandai', '1', 'Tactical RPG', 'Tactical strategy game with SD-style Gundam knights.', 'Lead your SD Gundam army to victory in this tactical sim.', 'Experience Daishougun Retsuden on Super Famicom.', 'A 16-bit strategy title focusing on the Sengokuden era. Command cute but powerful Mobile Suits in grid-based tactical battles with impressive attack animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-shougi-club-japan', 'SNES', 'Shin Shougi Club (Japan)', '1994', 'Board Game', 'Hect', '2', 'Shogi', 'Traditional Shougi (Japanese Chess) simulation.', 'Improve your skills against high-level AI Shogi masters.', 'Play Shin Shougi Club on the Super Famicom.', 'A technical 16-bit Shogi experience. Includes professional rule sets, tutorial modes for beginners, and a challenging ranking system for experienced players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-star-trek---the-next-generation---ooinaru-isan-ifd-no-nazo-no-oe-japan', 'SNES', 'Shin Star Trek - The Next Generation - Ooinaru Isan IFD no Nazo no Oe (Japan)', '1993', 'Adventure', 'Sculptured Software', '1', 'Graphic Adventure', 'Adventure game based on Star Trek: The Next Generation.', 'Solve the mystery of the Great Heritage as Captain Picard.', 'Explore the 16-bit Star Trek TNG on Super Famicom.', 'A unique Japanese-exclusive Star Trek adventure. Features exploration, diplomatic choices, and tactical ship-to-ship combat in the 24th-century universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinri-game-2-the---magical-trip-japan', 'SNES', 'Shinri Game 2, The - Magical Trip (Japan)', '1994', 'Psychological', 'Game Studio', '1', 'Psychological Adventure', 'Psychological testing and personality simulation game.', 'Discover your inner self through these 16-bit personality tests.', 'Play Shinri Game 2: Magical Trip on Super Famicom.', 'A unique "social game" for the 16-bit era. Features a series of psychological questions and mini-games designed to analyze your personality and compatibility with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinri-game-3-the-japan', 'SNES', 'Shinri Game 3, The (Japan)', '1995', 'Psychological', 'Game Studio', '1', 'Psychological Adventure', 'Psychological testing and social simulation sequel.', 'Unlock the secrets of your mind in this expanded sim.', 'Experience Shinri Game 3 on the Super Famicom.', 'The third 16-bit installment of the psychological series. Features more in-depth testing scenarios and improved graphics for the "magical" analytical journeys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinri-game-the---akuma-no-kokoroji-japan', 'SNES', 'Shinri Game, The - Akuma no Kokoroji (Japan)', '1992', 'Psychological', 'Game Studio', '1', 'Psychological Adventure', 'Psychological testing with a darker theme.', 'Analyze your personality with these devilish tests.', 'Try Shinri Game: Akuma no Kokoroji on Super Famicom.', 'A 16-bit "social simulation" focusing on the darker or more hidden aspects of personality. Perfect for party play and analyzing friends through bizarre scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinseiki-gpx-cyber-formula-japan', 'SNES', 'Shinseiki GPX Cyber Formula (Japan)', '1992', 'Racing', 'Varie', '1', 'Anime Racing', 'Futuristic racing game based on the popular anime series.', 'Win the Grand Prix with high-speed transforming vehicles.', 'Play Shinseiki GPX Cyber Formula on the Super Famicom.', 'A fast-paced 16-bit racer featuring Mode 7 effects. Boost through futuristic tracks and manage your car''s transformation mechanics to dominate the Cyber Formula circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinseiki-odysselya-japan', 'SNES', 'Shinseiki Odysselya (Japan)', '1993', 'RPG', 'Sigma Enterprises', '1', 'JRPG', 'Turn-based JRPG with a focus on ancient mythology.', 'Embark on a quest through time to save the world.', 'Explore the classic Shinseiki Odysselya on SNES.', 'A traditional 16-bit JRPG featuring a deep party system and tactical combat. Travel through different eras and recruit mythical heroes to stop an ancient evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinseiki-odysselya-ii-japan', 'SNES', 'Shinseiki Odysselya II (Japan)', '1995', 'RPG', 'Sigma Enterprises', '1', 'JRPG', 'Turn-based JRPG sequel with refined combat mechanics.', 'Lead a new generation of heroes in this 16-bit epic.', 'Experience Shinseiki Odysselya II on the Super Famicom.', 'An expanded 16-bit sequel with improved graphics and a more complex narrative. Features a larger world map and a refined system for character growth and equipment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinzui-taikyoku-igo---go-sennin-japan', 'SNES', 'Shinzui Taikyoku Igo - Go Sennin (Japan)', '1995', 'Board Game', 'Namco', '2', 'Go', 'Traditional Igo (Go) board game simulation.', 'Defeat the Go Master and improve your strategic ranking.', 'Play Shinzui Taikyoku Igo: Go Sennin on SNES.', 'A technical 16-bit simulation of the ancient board game. Features advanced AI routines that adapt to your skill level, offering a professional Go experience at home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shiroi-ring-e-twinkle-little-star-japan', 'SNES', 'Shiroi Ring e Twinkle Little Star (Japan)', '1994', 'Adventure', 'Nichibutsu', '1', 'Visual Novel', 'All-female professional wrestling simulation.', 'Climb the ranks and win the Twinkle Little Star belt.', 'Experience Shiroi Ring e on the Super Famicom.', 'A 16-bit wrestling title featuring a cast of female wrestlers. Combines fast-paced grappling with a story-driven career mode and colorful anime-style character designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shodai-nekketsu-kouha-kunio-kun-japan', 'SNES', 'Shodai Nekketsu Kouha Kunio-kun (Japan)', '1994', 'Action', 'Technos Japan', '2', 'Beat ''em Up', 'Action-RPG and side-scrolling beat ''em up hybrid.', 'Defeat the rival gangs in Osaka and clean up the streets.', 'Play Shodai Nekketsu Kouha Kunio-kun on SNES.', 'The 16-bit debut of Kunio-kun with a more realistic art style. Explore a semi-open Osaka, gain experience points, and buy items to power up your street fighting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shodai-nekketsu-kouha-kunio-kun-japan-en-by-aeon-genesis-v10-river-city-ransom-2', 'SNES', 'Shodai Nekketsu Kouha Kunio-kun (Japan) [En by Aeon Genesis v1.0] (River City Ransom 2)', '1994', 'Action', 'Technos Japan', '2', 'Beat ''em Up', 'Action-RPG and beat ''em up (English Translation).', 'Experience the gritty Kunio-kun sequel in English.', 'Play River City Ransom 2 (Kunio-kun) on the SNES.', 'The Aeon Genesis 16-bit translation of the classic brawler. Navigate the streets of Osaka, interact with NPCs, and upgrade your skills in this deep urban adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shodan-morita-shougi-japan', 'SNES', 'Shodan Morita Shougi (Japan)', '1991', 'Board Game', 'Seta', '2', 'Shogi', 'Professional Shougi (Japanese Chess) simulation.', 'Earn your 1st Dan rank by defeating pro-level AI.', 'Play Shodan Morita Shougi on the Super Famicom.', 'A high-level 16-bit Shogi sim known for its advanced thinking routines. Features a clean interface and professional rule sets for serious players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shodani-nintei---shodan-pro-mahjong-japan', 'SNES', 'Shodani Nintei - Shodan Pro Mahjong (Japan)', '1994', 'Mahjong', 'Nichibutsu', '2', 'Mahjong', 'Professional Mahjong simulation focused on ranking.', 'Prove your skill to earn a professional Mahjong certification.', 'Experience Shodan Pro Mahjong on the Super Famicom.', 'A technical 16-bit Mahjong title that tracks your performance. Master the tiles against disciplined AI to climb the professional ranks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shougi-club-japan', 'SNES', 'Shougi Club (Japan)', '1993', 'Board Game', 'Hect', '2', 'Shogi', 'Traditional Shougi (Japanese Chess) board game.', 'Join the Shogi club and defeat the top-ranked players.', 'Play Shougi Club on the Super Famicom.', 'A accessible 16-bit Shogi title. Features multiple difficulty levels and a practice mode, making it ideal for both beginners and intermediate players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shougi-fuurin-kazan-japan', 'SNES', 'Shougi Fuurin Kazan (Japan)', '1993', 'Board Game', 'Pony Canyon', '2', 'Shogi', 'Strategic Shougi simulation with historical themes.', 'Master the board in this tactical Japanese chess sim.', 'Experience Shougi Fuurin Kazan on the Super Famicom.', 'A 16-bit board game title inspired by Takeda Shingen''s philosophy. Features challenging AI and a focus on traditional strategic maneuvers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shougi-saikyou-japan', 'SNES', 'Shougi Saikyou (Japan)', '1994', 'Board Game', 'Magical Company', '2', 'Shogi', 'High-level Shougi simulation with a focus on difficulty.', 'Defeat the strongest AI masters in the Shogi world.', 'Play Shougi Saikyou on the Super Famicom.', 'A 16-bit strategy title designed for expert players. Features a highly optimized engine that provides one of the toughest Shogi challenges on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shougi-saikyou-ii---jissen-taikyoku-hen-japan', 'SNES', 'Shougi Saikyou II - Jissen Taikyoku Hen (Japan)', '1995', 'Board Game', 'Magical Company', '2', 'Shogi', 'Advanced Shougi simulation sequel.', 'Master the art of practical Shogi in this refined sequel.', 'Experience Shougi Saikyou II on the Super Famicom.', 'Features updated AI logic and new practice scenarios. A technical 16-bit board game sim that emphasizes real-match tactics and endgame strategies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shougi-zanmai-japan', 'SNES', 'Shougi Zanmai (Japan)', '1993', 'Board Game', 'Sigma Enterprises', '2', 'Shogi', 'Competitive and traditional Shougi simulation.', 'Achieve total mastery over the Shogi board.', 'Play Shougi Zanmai on the Super Famicom.', 'A 16-bit board game simulation featuring a variety of modes, including a tournament path and a detailed tutorial for learning complex Shogi openings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shounen-ashibe---goma-chan-no-yuuenchi-daibouken-japan', 'SNES', 'Shounen Ashibe - Goma-chan no Yuuenchi Daibouken (Japan)', '1991', 'Action', 'Towachiki', '1', 'Platformer', 'Platformer and mini-game collection based on the anime.', 'Explore the amusement park with Goma-chan the seal.', 'Play Shounen Ashibe on the Super Famicom.', 'A cute and colorful 16-bit title. Navigate through themed park levels, solve simple puzzles, and enjoy variety games starring the lovable seal and his friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shounen-ninja-sasuke-japan', 'SNES', 'Shounen Ninja Sasuke (Japan)', '1994', 'Action', 'Sunsoft', '1', 'Action Platformer', 'Side-scrolling action-platformer starring a young ninja.', 'Rescue your friends and defeat the evil ninja clan.', 'Experience Shounen Ninja Sasuke on the Super Famicom.', 'A vibrant 16-bit action game. Use shurikens, magic, and acrobatic jumps to navigate feudal Japanese stages filled with traps and mechanical enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shounin-yo-taishi-o-idake!!-japan', 'SNES', 'Shounin yo, Taishi o Idake!! (Japan)', '1993', 'Simulation', 'Human Entertainment', '1', 'Business Simulation', 'Economic and board-game style strategy simulation.', 'Become a wealthy merchant and build your commercial empire.', 'Play Shounin yo, Taishi o Idake!! on the SNES.', 'A unique 16-bit sim focused on trading and investment. Travel between cities, manage stock, and outmaneuver rivals to become the richest merchant in the land.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shuushoku-game---trendy-drama-japan', 'SNES', 'Shuushoku Game - Trendy Drama (Japan)', '1996', 'Simulation', 'Human Entertainment', '1', 'Life Simulation', 'Life simulation and visual novel with a drama theme.', 'Navigate the high-stakes world of Japanese trendy dramas.', 'Play Shuushoku Game on the Super Famicom.', 'A unique 16-bit social simulation. Make choices that affect your career and relationships in a narrative inspired by 90s Japanese television dramas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('side-pocket-europe', 'SNES', 'Side Pocket (Europe)', '1993', 'Sports', 'Irem', '2', 'Pool', 'Realistic pool and billiards simulation.', 'Clear the table and earn the high score in this 16-bit sim.', 'Experience Side Pocket on the Super Nintendo.', 'A classic 16-bit sports title. Features smooth ball physics, a variety of trick shots, and a relaxing lounge atmosphere with a smooth jazz soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('side-pocket-japan', 'SNES', 'Side Pocket (Japan)', '1993', 'Sports', 'Irem', '2', 'Pool', 'Realistic pool and billiards simulation (Japanese release).', 'Master the cue in the official Japanese edition.', 'Play Side Pocket on the Super Famicom.', 'The foundational 16-bit pool experience. Master the angles and spin to clear the pockets and unlock bonus stages in this highly polished simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('side-pocket-usa', 'SNES', 'Side Pocket (USA)', '1993', 'Sports', 'Irem', '2', 'Pool', 'Realistic pool and billiards simulation (USA release).', 'Challenge the pro circuit in the definitive 16-bit pool game.', 'Play Side Pocket for the Super Nintendo.', 'Features a variety of modes including Pocket Game and 9-Ball. Use precise aim and power to become a pool hall legend on the SNES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silva-saga-ii---the-legend-of-light-and-darkness-japan', 'SNES', 'Silva Saga II - The Legend of Light and Darkness (Japan)', '1994', 'RPG', 'Sigma Enterprises', '1', 'JRPG', 'Turn-based JRPG featuring a mercenary system.', 'Recruit soldiers and living statues to save the world.', 'Explore Silva Saga II on the Super Famicom.', 'A visually impressive 16-bit RPG. Features a unique system where you hire mercenaries and customize powerful idols to fight alongside your party in turn-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simant-japan', 'SNES', 'SimAnt (Japan)', '1991', 'Simulation', 'Maxis', '1', 'God Game', 'Strategic life simulation of an ant colony.', 'Lead your ant colony to dominate the backyard and the house.', 'Play Maxis'' SimAnt on the Super Famicom.', 'The Japanese edition of the unique 16-bit sim. Manage the colony''s food, defense, and breeding while avoiding predators like spiders and lawnmowers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simant-usa', 'SNES', 'SimAnt (USA)', '1991', 'Simulation', 'Maxis', '1', 'God Game', 'Strategic life simulation of an ant colony.', 'Defeat the rival red ants and conquer the garden.', 'Experience SimAnt on the Super Nintendo.', 'A 16-bit strategy masterpiece. Control an individual ant and the entire colony''s behavior in a quest to spread your nest across the entire suburban landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simant-usa-beta', 'SNES', 'SimAnt (USA) (Beta)', '1991', 'Simulation', 'Maxis', '1', 'God Game', 'Strategic life simulation (Pre-release build).', 'Test the early ant AI and colony growth mechanics.', 'Check out the SimAnt Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the scent-trail system and the tuning of the environmental hazards before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-europe', 'SNES', 'SimCity (Europe)', '1991', 'Simulation', 'Maxis', '1', 'City Builder', 'City-building simulation with a Nintendo twist.', 'Build a thriving metropolis and manage your citizens'' needs.', 'Play the legendary SimCity on the SNES.', 'A 16-bit masterpiece of urban planning. Manage zoning, taxes, and disasters with the help of Dr. Wright. Features iconic Nintendo-exclusive rewards like the Mario Statue and Bowser disasters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-france', 'SNES', 'SimCity (France)', '1991', 'Simulation', 'Maxis', '1', 'City Builder', 'City-building simulation (French localization).', 'Créez votre ville de rêve dans la version française.', 'Jouez à SimCity en français sur le SNES.', 'The complete 16-bit simulation localized for French players. Manage pollution, crime, and budget to transform a small village into a sprawling French-speaking megalopolis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-germany', 'SNES', 'SimCity (Germany)', '1991', 'Simulation', 'Maxis', '1', 'City Builder', 'City-building simulation (German localization).', 'Baue deine Traumstadt in dieser deutschen Version.', 'Spielen Sie SimCity auf Deutsch für das SNES.', 'A fully localized 16-bit experience. Balance industrial growth and residential happiness while dealing with unique scenarios in this classic Maxis simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-japan', 'SNES', 'SimCity (Japan)', '1991', 'Simulation', 'Maxis', '1', 'City Builder', 'City-building simulation (Original Japanese release).', 'Experience the foundational city sim in Japan.', 'Play SimCity on the Super Famicom.', 'The official 16-bit Japanese release. Features the same deep strategy and charming Nintendo-themed secrets that made the console port a worldwide success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-usa', 'SNES', 'SimCity (USA)', '1991', 'Simulation', 'Maxis', '1', 'City Builder', 'City-building simulation with real-time feedback.', 'Achieve the Megalopolis rank in this 16-bit classic.', 'Experience the original SimCity for the Super Nintendo.', 'Master the balance of R-C-I zones. Use the 16-bit power to manage a complex urban ecosystem, featuring a legendary soundtrack and addictive strategic gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-2000-europe', 'SNES', 'SimCity 2000 (Europe)', '1995', 'Simulation', 'Maxis', '1', 'City Builder', 'Advanced city-building with isometric perspective.', 'Evolve your city into the future with subways and arcologies.', 'Play SimCity 2000 on the Super Nintendo.', 'A massive 16-bit upgrade featuring underground water pipes, varied terrain elevations, and futuristic structures. A more complex and rewarding simulation for urban planners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-2000-japan', 'SNES', 'SimCity 2000 (Japan)', '1995', 'Simulation', 'Maxis', '1', 'City Builder', 'Advanced city-building (Japanese release).', 'Experience the next generation of city sims in Japan.', 'Play SimCity 2000 on the Super Famicom.', 'The official 16-bit Japanese release of the sequel. Includes a variety of scenarios and deep customization options for managing a modern, high-tech Japanese city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-2000-usa', 'SNES', 'SimCity 2000 (USA)', '1995', 'Simulation', 'Maxis', '1', 'City Builder', 'Advanced city-building with futuristic technology.', 'Manage a 16-bit world with newspapers and diverse zones.', 'Experience SimCity 2000 for the Super Nintendo.', 'Build mountains, launch space arcologies, and manage the city''s power grid. A technical 16-bit achievement that brings the complex PC simulation to the home console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-jr-japan', 'SNES', 'SimCity Jr. (Japan)', '1992', 'Simulation', 'Maxis', '1', 'City Builder', 'Simplified city-building for younger audiences.', 'Build a happy town in this accessible 16-bit sim.', 'Experience SimCity Jr. on the Super Famicom.', 'A Japan-exclusive "lite" version of the classic sim. Features cute graphics, simplified menus, and a more streamlined approach to urban management, perfect for beginners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simearth---the-living-planet-japan-rev-0a', 'SNES', 'SimEarth - The Living Planet (Japan) (Rev 0A)', '1991', 'Simulation', 'Maxis', '1', 'God Simulation', 'Global scale life and planet simulation.', 'Manage the Earth''s evolution from a rock to a civilization.', 'Experience SimEarth on the Super Famicom.', 'A deep 16-bit "God game" from Maxis. Control the atmosphere, plate tectonics, and the evolution of species to ensure the survival of life on your planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simearth---the-living-planet-usa', 'SNES', 'SimEarth - The Living Planet (USA)', '1991', 'Simulation', 'Maxis', '1', 'God Simulation', 'Global scale life and planet simulation (USA release).', 'Guide the evolution of life in this complex 16-bit sim.', 'Play the planet-building SimEarth on the SNES.', 'Features various scenarios including the terraforming of Mars. Manage the 16-bit environment to move from simple organisms to a space-faring civilization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpsons-the---bart-no-fushigi-na-yume-no-daibouken-japan', 'SNES', 'Simpsons, The - Bart no Fushigi na Yume no Daibouken (Japan)', '1992', 'Platformer', 'Konami', '1', 'Action Platformer', 'Action-adventure mini-game collection starring Bart Simpson.', 'Collect the lost pages of Bart''s homework in his dreams.', 'Play Bart no Fushigi na Yume on the Super Famicom.', 'The Japanese release of "Bart''s Nightmare". Features a variety of gameplay styles, from side-scrolling action as Bartman to Godzilla-style rampages in the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpsons-the---barts-nightmare-europe', 'SNES', 'Simpsons, The - Bart''s Nightmare (Europe)', '1992', 'Platformer', 'Konami', '1', 'Action Platformer', 'Action-adventure mini-game collection based on the TV show.', 'Survive the dream world and recover your homework.', 'Experience Bart''s Nightmare for the Super Nintendo.', 'A surreal 16-bit journey. Navigate the dangerous streets of Springfield in Bart''s mind to find portals leading to diverse and challenging mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpsons-the---barts-nightmare-usa', 'SNES', 'Simpsons, The - Bart''s Nightmare (USA)', '1992', 'Platformer', 'Konami', '1', 'Action Platformer', 'Action-adventure mini-game collection with iconic characters.', 'Master the 16-bit dream levels and save Bart''s grades.', 'Play the classic Bart''s Nightmare on the SNES.', 'Features impressive graphics that capture the show''s aesthetic. Battle itchy and scratchy, fly through the clouds, and survive the school corridors in this 90s classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simulation-pro-yakyuu-japan', 'SNES', 'Simulation Pro Yakyuu (Japan)', '1995', 'Sports', 'Compile', '1', 'Baseball Simulation', 'Realistic professional baseball simulation.', 'Win the Japan Series in this technical 16-bit sports sim.', 'Experience Simulation Pro Yakyuu on the Super Famicom.', 'Focuses on the statistical and management side of baseball. Analyze player data and make strategic calls from the dugout to lead your team to victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sink-or-swim-europe', 'SNES', 'Sink or Swim (Europe)', '1993', 'Puzzle', 'Bullfrog Productions', '2', 'Action Puzzle', 'Puzzle-platformer where you rescue passengers on a ship.', 'Guide the survivors to safety before the ship sinks.', 'Play the challenging Sink or Swim on the SNES.', 'Similar to Lemmings. Use various items to clear hazards and direct the clueless passengers to the exit across dozens of water-themed 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sink-or-swim-usa', 'SNES', 'Sink or Swim (USA)', '1993', 'Puzzle', 'Bullfrog Productions', '2', 'Action Puzzle', 'Puzzle-platformer featuring Kevin the conveyor-belt hero.', 'Save the crew of the SS Lucifer in this 16-bit puzzler.', 'Experience Sink or Swim for the Super Nintendo.', 'Master the environment by manipulating levers, bridges, and valves. A clever logic game that rewards quick thinking and precise timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ski-paradise-with-snowboard-japan', 'SNES', 'Ski Paradise with Snowboard (Japan)', '1994', 'Sports', 'Nichibutsu', '1', 'Skiing / Snowboarding', 'Winter sports simulation with skiing and snowboarding.', 'Master the snowy slopes and win the 16-bit tournament.', 'Play Ski Paradise on the Super Famicom.', 'Features both downhill skiing and snowboarding modes. Use the 16-bit Mode 7 effects to navigate realistic mountain tracks and perform stunts for high scores.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('skuljagger---revolt-of-the-westicans-usa', 'SNES', 'Skuljagger - Revolt of the Westicans (USA)', '1992', 'Action', 'American Softworks', '1', 'Action Platformer', 'Action-platformer with a focus on collectible items.', 'Overthrow the evil Captain Whitescar in this 16-bit quest.', 'Experience the adventure of Skuljagger on the SNES.', 'Play as Storm Jaki in a vibrant tropical setting. Use your sword to battle pirates and find the hidden "Westican" gems to unlock new powers and secret paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('skuljagger---revolt-of-the-westicans-usa-beta', 'SNES', 'Skuljagger - Revolt of the Westicans (USA) (Beta)', '1992', 'Action', 'American Softworks', '1', 'Action Platformer', 'Action-platformer (Pre-release build).', 'Test the early sword combat and gem-collecting mechanics.', 'Check out the Skuljagger Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s movement physics and the evolution of the jungle and pirate ship level designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sky-mission-japan', 'SNES', 'Sky Mission (Japan)', '1993', 'Shooter', 'Naxat Soft', '1', 'Vertical Shooter', 'First-person flight combat and exploration.', 'Complete high-stakes missions in a futuristic fighter jet.', 'Fly high in Sky Mission for the Super Famicom.', 'A technical 16-bit flight sim. Use a cockpit view to engage in dogfights and bombing runs across a variety of 3D-style landscapes using the SNES hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('skyblazer-europe', 'SNES', 'Skyblazer (Europe)', '1993', 'Action', 'Sony Imagesoft', '1', 'Action Platformer', 'Atmospheric action-platformer with magical abilities.', 'Stop the sorcerer Ashura and save your home.', 'Play the epic Skyblazer for the Super Nintendo.', 'Developed by Sony. Features fluid 16-bit combat, wall-climbing, and a variety of elemental powers. A hidden gem known for its great music and tight controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('skyblazer-usa', 'SNES', 'Skyblazer (USA)', '1993', 'Action', 'Sony Imagesoft', '1', 'Action Platformer', 'Atmospheric action-platformer with magical abilities.', 'Master the elemental spells to defeat the dark gods.', 'Experience the classic Skyblazer on the SNES.', 'Navigate through stunning 16-bit levels using acrobatic moves and magical strikes. One of the most polished and visually impressive platformers of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('skyblazer-usa-beta1', 'SNES', 'Skyblazer (USA) (Beta1)', '1993', 'Action', 'Sony Imagesoft', '1', 'Action Platformer', 'Action-platformer (Early development build).', 'Test the early wall-climb mechanics and boss patterns.', 'Check out the Skyblazer Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of Sky''s magical meter and the initial implementation of the Mode 7 world map.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('skyblazer-usa-beta2', 'SNES', 'Skyblazer (USA) (Beta2)', '1993', 'Action', 'Sony Imagesoft', '1', 'Action Platformer', 'Action-platformer (Revised development build).', 'Explore unreleased stage layouts and enemy placements.', 'Discover the Skyblazer Beta 2 on the SNES.', 'An advanced 16-bit prototype. Features nearly final assets but with different enemy density and specific item locations for testing purposes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slap-stick-japan', 'SNES', 'Slap Stick (Japan)', '1994', 'Action', 'Irem', '1', 'Beat ''em Up', 'Quirky turn-based RPG with robot customization.', 'Build and program your own robots to save the world.', 'Explore Slap Stick on the Super Famicom.', 'Known as "Robotrek" in the West. A unique 16-bit RPG where you create up to three custom robots, managing their stats, weapons, and specialized combat moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slayers-japan', 'SNES', 'Slayers (Japan)', '1994', 'RPG', 'Banpresto', '1', 'JRPG', 'Tactical JRPG based on the iconic fantasy anime.', 'Join Lina Inverse and her party on a magical 16-bit quest.', 'Experience the legend of Slayers on the Super Famicom.', 'A first-person JRPG that captures the humor and power of the series. Use powerful "Dragon Slave" spells and interact with the fan-favorite cast in a faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slayers-japan-en-by-filler-v020-incomplete', 'SNES', 'Slayers (Japan) [En by Filler v0.20] (Incomplete)', '1994', 'RPG', 'Banpresto', '1', 'JRPG', 'Tactical JRPG (English Translation - Incomplete).', 'Experience the world of Lina Inverse with translated text.', 'Play Slayers in English (v0.20) on the SNES.', 'An early-stage 16-bit fan translation. Allows players to experience the opening chapters and basic combat menus of this anime-inspired role-playing adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi---bangai-hen-japan-unl', 'SNES', 'SM Choukyoushi Hitomi - Bangai Hen (Japan) (Unl)', '1994', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure/puzzle (Unlicensed).', 'Navigate the scandalous scenarios as the dominant Hitomi.', 'Explore SM Choukyoushi Hitomi Bangai Hen (Unl).', 'An unlicensed 16-bit title featuring adult-oriented themes and dialogue. Combines simple adventure mechanics with provocative art styles typical of the underground Japanese market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi---bangai-hen-2---maki-no-love-love-panic-japan-unl', 'SNES', 'SM Choukyoushi Hitomi - Bangai Hen 2 - Maki no Love Love Panic (Japan) (Unl)', '1994', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed puzzle/adventure sequel (Unlicensed).', 'Resolve the "Love Love Panic" in this adult-themed sequel.', 'Play SM Choukyoushi Hitomi Bangai Hen 2 (Unl).', 'The second unlicensed 16-bit spin-off. Features expanded character interactions and more complex puzzle scenarios centered around its mature-themed narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi---test-version-japan-unl', 'SNES', 'SM Choukyoushi Hitomi - Test Version (Japan) (Unl)', '1994', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure (Test Version - Unlicensed).', 'Test the early dialogue and adult scene triggers.', 'Check the SM Choukyoushi Hitomi Test Build.', 'A rare 16-bit development look at an unlicensed adult title. Witness the initial implementation of the character portraits and menu structures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi-japan-unl', 'SNES', 'SM Choukyoushi Hitomi (Japan) (Unl)', '1994', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure and simulation (Unlicensed).', 'Master the dominant arts in this controversial title.', 'Experience SM Choukyoushi Hitomi (Unl) on SNES.', 'The foundational 16-bit unlicensed adult game for the system. Features a mix of text-heavy adventure and simulation elements focused on its specific niche theme.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi-vol-2---trial-version-japan-unl', 'SNES', 'SM Choukyoushi Hitomi Vol. 2 - Trial Version (Japan) (Unl)', '1995', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure sequel (Trial - Unlicensed).', 'Preview the new scenarios in the second volume.', 'Try the SM Choukyoushi Hitomi Vol. 2 Trial.', 'A 16-bit demo version of the second installment. Offers a glimpse into the updated graphics and new character additions before the full unlicensed release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi-vol-2-japan-unl', 'SNES', 'SM Choukyoushi Hitomi Vol. 2 (Japan) (Unl)', '1995', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure and simulation (Unlicensed).', 'Expand your influence in this second adult volume.', 'Play SM Choukyoushi Hitomi Vol. 2 (Unl).', 'The direct 16-bit sequel to the unlicensed original. Features more detailed artwork and a longer story path involving various adult-themed challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi-vol-2-remix-japan-unl', 'SNES', 'SM Choukyoushi Hitomi Vol. 2 Remix (Japan) (Unl)', '1995', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure (Remix Edition - Unlicensed).', 'Experience the enhanced version of the second volume.', 'Play SM Choukyoushi Hitomi Vol. 2 Remix (Unl).', 'An updated 16-bit edition of the second volume. Includes refined color palettes, additional dialogue lines, and slight mechanical tweaks to the unlicensed adult sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi-vol-3---test-version-japan-unl', 'SNES', 'SM Choukyoushi Hitomi Vol. 3 - Test Version (Japan) (Unl)', '1996', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure (Vol 3 Test - Unlicensed).', 'Explore the early assets of the third installment.', 'Check the SM Choukyoushi Hitomi Vol. 3 Test.', 'A rare 16-bit development slice of the third volume. Shows the evolution of the series'' visual style and UI design for the underground Japanese market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi-vol-3-japan-unl-0810', 'SNES', 'SM Choukyoushi Hitomi Vol. 3 (Japan) (Unl) [0810]', '1996', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure and simulation (Unlicensed).', 'Complete the final chapters of Hitomi''s story.', 'Experience SM Choukyoushi Hitomi Vol. 3 (Unl).', 'The third main 16-bit entry in the unlicensed series. Features the most advanced graphics and complex narrative paths of the trilogy for mature audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm-choukyoushi-hitomi-vol-3-japan-unl-1087', 'SNES', 'SM Choukyoushi Hitomi Vol. 3 (Japan) (Unl) [1087]', '1996', 'Adventure', 'Unknown', '1', 'Adult Visual Novel', 'Adult-themed adventure and simulation (Unlicensed).', 'Experience an alternate build of the third volume.', 'Play SM Choukyoushi Hitomi Vol. 3 (Unl) [1087].', 'A slight variation of the third 16-bit installment. Features the same adult-themed gameplay with minor internal data differences and scenario ordering.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smart-ball-usa', 'SNES', 'Smart Ball (USA)', '1992', 'Platformer', 'GameTek', '1', 'Action Platformer', 'Physics-based puzzle platformer with a slime-like ball.', 'Navigate Jerry Bean through obstacles to the goal.', 'Experience the colorful Smart Ball on the SNES.', 'Known as "Jerry Boy" in Japan. A charming 16-bit platformer where you control a jelly ball that can stick to walls, stretch, and absorb items to solve puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-tv-japan', 'SNES', 'Smash T.V. (Japan)', '1990', 'Action', 'Williams Electronics', '2', 'Arcade Action', 'Ultraviolent top-down arena shooter.', 'Survive the lethal game show and win big prizes.', 'Play the explosive Smash T.V. on the Super Famicom.', 'A frantic 16-bit arcade port. Face waves of enemies in a futuristic game show. Use dual-stick style controls to blast through rooms and collect "Big Money!"');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-tennis-europe', 'SNES', 'Smash Tennis (Europe)', '1993', 'Sports', 'Namco', '2', 'Tennis', 'Fast-paced tennis simulation with diverse characters.', 'Win the international tennis circuit on various surfaces.', 'Play the addictive Smash Tennis on the SNES.', 'Also known as Super Family Tennis. Features a zoomed-out perspective, responsive controls, and a variety of courts including grass, clay, and even a beach.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-tennis-europe-beta', 'SNES', 'Smash Tennis (Europe) (Beta)', '1993', 'Sports', 'Namco', '2', 'Tennis', 'Tennis simulation (Pre-release build).', 'Test the early ball physics and character movements.', 'Check out the Smash Tennis Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the "Mode 7" style court rotations and the balancing of the AI''s serving speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smprgrevolutionv11a', 'SNES', 'SMPRGRevolutionV1.1a', '2019', 'RPG', 'Fan Made', '1', 'JRPG Hack', 'Fan-made Super Mario RPG modification.', 'Experience an overhauled version of the Mario RPG epic.', 'Play the SMPRGRevolution mod on the SNES.', 'A technical 16-bit fan expansion. Features rebalanced stats, new enemy encounters, and specific quality-of-life improvements to the original Square/Nintendo masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smurfs-2-the-europe-enfrdees', 'SNES', 'Smurfs 2, The (Europe) (En,Fr,De,Es)', '1995', 'Platformer', 'Infogrames', '1', 'Action Platformer', 'Side-scrolling platformer based on the movie "The Smurfs 2".', 'Rescue the Smurfs from Gargamel''s latest trap.', 'Experience The Smurfs 2 on the Super Nintendo.', 'A visually impressive 16-bit platformer featuring large sprites and vibrant colors. Travel across Europe to save your blue friends in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smurfs-the-europe-enfrdeesit', 'SNES', 'Smurfs, The (Europe) (En,Fr,De,Es,It)', '1994', 'Platformer', 'Infogrames', '1', 'Action Platformer', 'Side-scrolling platformer based on the classic comic.', 'Help the Smurfs survive the forest and Gargamel.', 'Play The Smurfs on the Super Nintendo.', 'A challenging 16-bit title with a high level of difficulty. Navigate through the woods, caves, and Gargamel''s castle with fluid animations and faithful art style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smw-the-crown-tale-by-bandicoot', 'SNES', 'SMW The Crown Tale by bandicoot', '2018', 'Platformer', 'Fan Made', '1', 'Story Platformer', 'Fan-made Super Mario World expansion hack.', 'Explore the kingdom of the Crown in this Mario adventure.', 'Play SMW: The Crown Tale on the SNES.', 'A high-quality 16-bit fan creation. Features custom music, unique level assets, and a completely new world map designed for veterans of the original Super Mario World.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snoopy-concert-japan', 'SNES', 'Snoopy Concert (Japan)', '1995', 'Music', 'Game Freak', '1', 'Music / Rhythm', 'Multi-genre adventure featuring Snoopy and the Peanuts gang.', 'Help Snoopy complete various tasks in the theme park.', 'Experience Snoopy Concert on the Super Famicom.', 'A charming 16-bit title from Hudson Soft. Switch between different gameplay styles including point-and-click, puzzles, and side-scrolling action to help the Peanuts cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snoopy-concert-japan-en-by-aeon-genesis-v10', 'SNES', 'Snoopy Concert (Japan) [En by Aeon Genesis v1.0]', '1995', 'Music', 'Game Freak', '1', 'Music / Rhythm', 'Adventure and puzzle (English Translation).', 'Enjoy Snoopy''s theme park adventure in English.', 'Play Snoopy Concert in English on the SNES.', 'The Aeon Genesis 16-bit translation. Makes this beautiful Peanuts game fully accessible, featuring witty dialogue and clear instructions for the various mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snow-white-in-happily-ever-after-usa', 'SNES', 'Snow White in Happily Ever After (USA)', '1994', 'Platformer', 'Capcom', '1', 'Action Platformer', 'Side-scrolling platformer based on the animated film.', 'Rescue the Prince and defeat the evil Queen.', 'Play Snow White in Happily Ever After on SNES.', 'A colorful 16-bit platformer. Choose between various characters to navigate enchanted forests and snowy mountains, featuring smooth controls and family-friendly gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('so-2-mice-walk-into-a-bar-by-snn-idol', 'SNES', 'So 2 Mice Walk Into a Bar... by S.N.N., idol', '2020', 'Adventure', 'Homebrew', '1', 'Narrative Adventure', 'Abstract and comedic fan-made SNES demo/mini-game.', 'Witness the surreal humor of two mice in a bar.', 'Check out So 2 Mice Walk Into a Bar on SNES.', 'A short, 16-bit community-made creative project. Showcases custom sprite work and humorous dialogue scripts within the Super Nintendo''s technical framework.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soccer-kid-europe-enfrdeesit', 'SNES', 'Soccer Kid (Europe) (En,Fr,De,Es,It)', '1994', 'Platformer', 'Krisalis Software', '1', 'Action Platformer', 'Platformer where your primary weapon is a soccer ball.', 'Travel the world and recover the stolen World Cup.', 'Experience the unique Soccer Kid on the SNES.', 'A clever 16-bit platformer. Use your soccer ball to attack enemies, trigger switches, and perform acrobatic jumps. Features large, detailed levels and great physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soccer-kid-japan', 'SNES', 'Soccer Kid (Japan)', '1994', 'Platformer', 'Krisalis Software', '1', 'Action Platformer', 'Soccer-based platformer (Japanese release).', 'Experience the globe-trotting adventure in Japan.', 'Play Soccer Kid on the Super Famicom.', 'The official 16-bit Japanese release. Retains the creative ball-juggling mechanics and challenging level design that made it a standout title in the European market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soccer-kid-japan-beta', 'SNES', 'Soccer Kid (Japan) (Beta)', '1994', 'Platformer', 'Krisalis Software', '1', 'Action Platformer', 'Soccer-based platformer (Pre-release build).', 'Test the early ball-handling and collision physics.', 'Check out the Soccer Kid Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the ball''s bounce logic and the initial implementation of the diverse international backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soccer-shootout-europe', 'SNES', 'Soccer Shootout (Europe)', '1994', 'Sports', 'Teque London', '2', 'Soccer', 'Simulation-style soccer game with a focus on realism.', 'Win the European cup with precise passing and tactics.', 'Play Soccer Shootout on the Super Nintendo.', 'A solid 16-bit sports title. Features a variety of modes including indoor soccer, penalty shootouts, and full-season tournaments with a focus on technical play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soldiers-of-fortune-usa', 'SNES', 'Soldiers of Fortune (USA)', '1993', 'Action', 'LucasArts', '2', 'Run and Gun', 'Top-down run-and-gun action shooter.', 'Blaze through levels and stop the technological menace.', 'Experience Soldiers of Fortune on the SNES.', 'Known as "The Chaos Engine" in Europe. A gritty 16-bit steampunk shooter featuring two-player co-op, six distinct characters, and highly challenging, maze-like levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solid-runner-japan', 'SNES', 'Solid Runner (Japan)', '1997', 'Racing', 'Sting', '1', 'Futuristic Racing', 'Cyberpunk dungeon-crawling RPG with turn-based combat.', 'Uncover the conspiracy in the city of Solid.', 'Explore the impressive Solid Runner on Super Famicom.', 'A late-gen 16-bit RPG marvel. Features incredible pre-rendered graphics, a sophisticated sci-fi story, and tactical combat involving specialized mecha-style suits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solstice-ii-japan', 'SNES', 'Solstice II (Japan)', '1993', 'Action', 'Imagineering', '1', 'Action Adventure', 'Isometric action-puzzle and platformer.', 'Navigate the wizard through the complex labyrinth of Solstice.', 'Play the mind-bending Solstice II on the SNES.', 'Known as "Equinox" in the West. A 16-bit isometric adventure. Solve intricate environmental puzzles and defeat massive bosses in a quest to rescue the wizard Shadax.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('song-master-japan', 'SNES', 'Song Master (Japan)', '1992', 'Music', 'ASCII', '1', 'Music Utility', 'Traditional turn-based JRPG with a focus on music.', 'Embark on a quest to become the ultimate Song Master.', 'Explore the melodic Song Master on the Super Famicom.', 'A rare 16-bit RPG where music plays a central role in the narrative and world-building. Features classic turn-based combat and detailed character sprites in a high-fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-blast-man-europe', 'SNES', 'Sonic Blast Man (Europe)', '1992', 'Action', 'Taito', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up based on the arcade hit.', 'Save the Earth from criminals and aliens as the superhero.', 'Play the explosive Sonic Blast Man on the SNES.', 'A 16-bit brawler featuring a superhero known for his powerful punches. Includes diverse levels ranging from city streets to alien ships, and unique bonus stages from the arcade original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-blast-man-japan', 'SNES', 'Sonic Blast Man (Japan)', '1992', 'Action', 'Taito', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up (Japanese release).', 'Defeat the evil forces in the official Japanese version.', 'Experience Sonic Blast Man on the Super Famicom.', 'The 16-bit debut of the "punching" hero in Japan. Master his signature moves and tackle challenging bosses in this high-energy action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-blast-man-usa', 'SNES', 'Sonic Blast Man (USA)', '1992', 'Action', 'Taito', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up starring the armored hero.', 'Protect the world from a global terrorist threat.', 'Experience the action-packed Sonic Blast Man on SNES.', 'Features large character sprites and intense 16-bit combat. Use specialized punches to destroy everything from thugs to massive mechanical bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-blast-man-ii-japan', 'SNES', 'Sonic Blast Man II (Japan)', '1994', 'Action', 'Taito', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up sequel with multiple characters.', 'Stop the new criminal organization with Sonic Blast Man.', 'Play Sonic Blast Man II on the Super Famicom.', 'An expanded 16-bit sequel. Features three playable characters, each with unique fighting styles and movesets, offering much more variety than the first game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-blast-man-ii-usa', 'SNES', 'Sonic Blast Man II (USA)', '1994', 'Action', 'Taito', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up sequel with 2-player co-op.', 'Team up to defeat the intergalactic threats.', 'Experience Sonic Blast Man II on the Super Nintendo.', 'Significant 16-bit improvement over the original. Includes cooperative multiplayer, branching paths, and more fluid combat mechanics for a superior brawling experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-in-smw', 'SNES', 'Sonic in SMW', '2010', 'Platformer', 'Fan Made', '1', 'Crossover Hack', 'Fan-made hack of Super Mario World featuring Sonic.', 'Navigate the Mushroom Kingdom with Sonic''s speed.', 'Play Sonic in SMW on the Super Nintendo.', 'A creative 16-bit romhack that replaces Mario with Sonic the Hedgehog. Features custom physics to mimic Sonic''s speed and momentum within the classic Mario levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-in-super-mario-world', 'SNES', 'Sonic in Super Mario World', '2010', 'Platformer', 'Fan Made', '1', 'Crossover Hack', 'Fan-made hack of Super Mario World featuring Sonic.', 'Complete Mario''s adventure using Sonic''s abilities.', 'Try Sonic in Super Mario World on the SNES.', 'A 16-bit community project that blends the two mascots. Features Sonic''s signature spin-jump and speed, providing a fresh way to experience the legendary 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog---snes-edition', 'SNES', 'Sonic the Hedgehog - SNES Edition', '2018', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'Unlicensed port/recreation of the Sega classic.', 'Experience Sonic''s first adventure on a Nintendo console.', 'Check out Sonic the Hedgehog SNES Edition (Unl).', 'A 16-bit unlicensed curiosity. Attempts to recreate the Green Hill Zone experience on the SNES hardware, showcasing fan efforts to cross the console divide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-snes', 'SNES', 'Sonic the Hedgehog (SNES)', '2018', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'Unlicensed port/recreation of the Sega classic.', 'Run through the zones in this unofficial 16-bit port.', 'Play Sonic the Hedgehog (Unl) on the SNES.', 'An unofficial 16-bit technical experiment. While lacking the polish of the Sega original, it stands as a fascinating piece of underground gaming history for the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-unl', 'SNES', 'Sonic the Hedgehog (Unl)', '1994', 'Platformer', 'Unlicensed', '1', 'Platformer', 'Unlicensed port/recreation of the Sega classic.', 'Experience the blue blur on the Super Famicom hardware.', 'Play Sonic the Hedgehog (Unl) on the SNES.', 'Features various attempts at 16-bit parallax scrolling and speed physics on the SNES, created by third-party developers without official Nintendo licensing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-2-hack', 'SNES', 'Sonic the Hedgehog 2 (hack)', '2005', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'Fan-made hack of Sonic 4 (Unl) or similar engine.', 'Play an alternate 16-bit Sonic adventure.', 'Experience the Sonic the Hedgehog 2 Hack on SNES.', 'A 16-bit modification of existing unlicensed Sonic games. Tweaks the palettes and level layouts to resemble the second entry of the series on the rival platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-4-world-unl', 'SNES', 'Sonic the Hedgehog 4 (World) (Unl)', '2019', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'Unlicensed side-scrolling platformer.', 'Complete a new, unofficial quest as Sonic the Hedgehog.', 'Play Sonic the Hedgehog 4 (Unl) on the SNES.', 'Actually a pirate port of "Speedy Gonzales: Los Gatos Bandidos" with the main character replaced by Sonic. A bizarre 16-bit historical artifact of the pirate game scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-wings-japan', 'SNES', 'Sonic Wings (Japan)', '1993', 'Shooter', 'Video System', '2', 'Vertical Shooter', 'Vertical-scrolling shoot ''em up (Shmup).', 'Choose your pilot and destroy the global military threat.', 'Experience the intense Sonic Wings on the Super Famicom.', 'Known as "Aero Fighters" in the West. A top-tier 16-bit shooter featuring diverse planes, fast-paced bullet patterns, and quirky humor across international stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soreyuke-ebisumaru-karakuri-meiro---kieta-goemon-no-nazo!!-japan', 'SNES', 'Soreyuke Ebisumaru Karakuri Meiro - Kieta Goemon no Nazo!! (Japan)', '1994', 'Action', 'Konami', '1', 'Action Adventure', 'Isometric puzzle-adventure starring Ebisumaru.', 'Solve the maze-like levels to find the missing Goemon.', 'Explore Ebisumaru''s Karakuri Meiro on the SNES.', 'A charming 16-bit spin-off from the Ganbare Goemon series. Use logic and timing to navigate complex traps and puzzles in a vibrant, feudal Japanese setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sos-usa', 'SNES', 'SOS (USA)', '1994', 'Adventure', 'Human Entertainment', '1', 'Survival Adventure', 'Cinematic survival adventure on a sinking ship.', 'Escape the sinking Lady Crithania and save the survivors.', 'Experience the atmospheric SOS on the Super Nintendo.', 'Uses 16-bit Mode 7 effects to rotate the entire world as the ship capsizes. A tense, non-linear adventure where every second counts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sotsugyou-bangai-hen---nee-mahjong-shiyo!-japan', 'SNES', 'Sotsugyou Bangai Hen - Nee Mahjong Shiyo! (Japan)', '1995', 'Mahjong', 'Jaleco', '1', 'Mahjong', 'Mahjong simulation featuring the cast of Sotsugyou.', 'Play Mahjong with the girls from the "Graduation" series.', 'Experience Nee Mahjong Shiyo! on the Super Famicom.', 'A 16-bit anime-style Mahjong game. Features voiced dialogue and high-quality character art from the popular Japanese life-simulation franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sougou-kakutougi-astral-bout-japan', 'SNES', 'Sougou Kakutougi Astral Bout (Japan)', '1992', 'Fighting', 'King Records', '2', 'Fighting', 'Technical MMA-style fighting game (RINGS).', 'Win the Astral Bout tournament using realistic grappling.', 'Play Astral Bout on the Super Famicom.', 'A unique 16-bit fighter focused on realism. Master submissions, strikes, and positioning in this early representation of mixed martial arts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sougou-kakutougi-astral-bout-2---the-total-fighters-japan', 'SNES', 'Sougou Kakutougi Astral Bout 2 - The Total Fighters (Japan)', '1994', 'Fighting', 'A-Wave', '2', 'Fighting', 'MMA-style fighting game sequel.', 'Defeat the total fighters in this technical 16-bit sim.', 'Experience Astral Bout 2 on the Super Famicom.', 'Features an expanded roster and refined grappling mechanics. A more polished 16-bit combat experience for fans of technical wrestling and martial arts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sougou-kakutougi-rings---astral-bout-3-japan', 'SNES', 'Sougou Kakutougi Rings - Astral Bout 3 (Japan)', '1995', 'Fighting', 'A-Wave', '2', 'Fighting', 'The final entry in the technical MMA trilogy.', 'Claim the RINGS championship in this advanced fighter.', 'Play Astral Bout 3 on the Super Famicom.', 'The most advanced 16-bit entry in the series. Features significantly improved animations, a deeper career mode, and a refined focus on ground-and-pound tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soukou-kihei-votoms---the-battling-road-japan', 'SNES', 'Soukou Kihei Votoms - The Battling Road (Japan)', '1991', 'Action', 'Takara', '1', 'Mecha Action', 'Mecha fighting game based on the classic anime.', 'Pilot the Scopedog and survive the "Battling" arena.', 'Explore Armored Trooper Votoms on the SNES.', 'A technical 16-bit mecha combat game. Features 2D fighting mechanics with specialized robot movement, capturing the gritty atmosphere of the Votoms universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-&-sword-japan', 'SNES', 'Soul & Sword (Japan)', '1993', 'RPG', 'Pandora Box', '1', 'Action RPG', 'Turn-based JRPG with a tactical equipment system.', 'Uncover the mystery of the Soul & Sword.', 'Experience Soul & Sword on the Super Famicom.', 'A late-gen 16-bit RPG featuring a unique "Card" system for actions and equipment. Offers a deep narrative and impressive environmental pixel art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-blade-world-unl', 'SNES', 'Soul Blade (World) (Unl)', '1998', 'Fighting', 'Unlicensed', '2', 'Weapon-Based Fighting', 'Unlicensed 2D fighting game (Pirate).', 'Fight through the roster in this unofficial 16-bit brawler.', 'Check out Soul Blade (Unl) on the Super Nintendo.', 'An unlicensed attempt to bring the 32-bit weapons fighter to the SNES. Features simplified 16-bit mechanics and a roster based on the SoulCalibur series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-blader-japan', 'SNES', 'Soul Blader (Japan)', '1992', 'RPG', 'Quintet', '1', 'Action RPG', 'The original Japanese release of Soul Blazer.', 'Restore the world''s life by defeating Deathtoll.', 'Play Soul Blader on the Super Famicom.', 'The first entry in Quintet''s "Heaven and Earth" 16-bit trilogy. Combine action-combat with town-building as you rescue souls to rebuild the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-blazer-europe', 'SNES', 'Soul Blazer (Europe)', '1992', 'RPG', 'Quintet', '1', 'Action RPG', 'Action-RPG focused on world restoration.', 'Rebuild the kingdom by clearing monster dens.', 'Experience the magic of Soul Blazer on the SNES.', 'A landmark 16-bit Action-RPG. Features a satisfying gameplay loop where every enemy defeated helps bring life back to the devastated environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-blazer-france', 'SNES', 'Soul Blazer (France)', '1992', 'RPG', 'Quintet', '1', 'Action RPG', 'Action-RPG (French localization).', 'Restaurez le monde dans cette version française.', 'Jouez à Soul Blazer en français sur le SNES.', 'The complete 16-bit adventure with full French text. Experience the emotional story and creative dungeon design of this Quintet classic in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-blazer-germany', 'SNES', 'Soul Blazer (Germany)', '1992', 'RPG', 'Quintet', '1', 'Action RPG', 'Action-RPG (German localization).', 'Erwecke die Welt zu neuem Leben auf Deutsch.', 'Spielen Sie Soul Blazer auf Deutsch für das SNES.', 'A fully localized 16-bit experience. Battle through themed worlds and master the specialized magic and swordplay required to save humanity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-blazer-usa', 'SNES', 'Soul Blazer (USA)', '1992', 'RPG', 'Quintet', '1', 'Action RPG', 'Action-RPG featuring real-time combat and town-building.', 'Defeat the forces of evil and restore the six realms.', 'Play the legendary Soul Blazer on the Super Nintendo.', 'Known for its addictive progression and deep themes. A 16-bit masterpiece that paved the way for Illusion of Gaia and Terranigma.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sound-novel-tsukuru-japan', 'SNES', 'Sound Novel Tsukuru (Japan)', '1996', 'Utility', 'Hudson Soft', '1', 'Visual Novel Creator', 'Creative tool for designing visual novels.', 'Write and create your own 16-bit digital stories.', 'Build stories with Sound Novel Tsukuru on SNES.', 'A unique 16-bit utility from Chunsoft. Use various backgrounds, music tracks, and branch-path scripts to create your own suspenseful sound novels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-ace-europe', 'SNES', 'Space Ace (Europe)', '1994', 'Action', 'Eurocom', '1', 'Interactive Movie', 'Action-platformer adaptation of the laserdisc classic.', 'Rescue Kimberly from the evil Commander Borf.', 'Experience the high-stakes Space Ace on the SNES.', 'A 16-bit reimagining of the arcade hit. Unlike the laserdisc original, this is a challenging side-scrolling platformer where Dexter must dodge traps and blast aliens to save the girl.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-ace-japan', 'SNES', 'Space Ace (Japan)', '1994', 'Action', 'Eurocom', '1', 'Interactive Movie', 'Action-platformer adaptation (Japanese release).', 'Navigate the cosmic perils in the official Japanese version.', 'Play Space Ace on the Super Famicom.', 'The official 16-bit Japanese port. Features vibrant graphics and a high level of difficulty as you switch between the agile Dexter and the powerful Ace to defeat Borf''s army.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-ace-usa', 'SNES', 'Space Ace (USA)', '1994', 'Action', 'Eurocom', '1', 'Interactive Movie', 'Action-platformer featuring transforming protagonists.', 'Defeat Borf and return to your adult form as Ace.', 'Play the action-packed Space Ace on the SNES.', 'A unique 16-bit title that blends cinematic timing with traditional platforming. Use your laser pistol and agility to survive treacherous alien worlds in this sci-fi adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-ace-usa-beta', 'SNES', 'Space Ace (USA) (Beta)', '1994', 'Action', 'Eurocom', '1', 'Interactive Movie', 'Action-platformer (Pre-release build).', 'Test the early collision physics and enemy spawns.', 'Check out the Space Ace Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s jumping arcs and the evolution of the level layouts before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-bazooka-japan', 'SNES', 'Space Bazooka (Japan)', '1992', 'Shooter', 'Kemco', '2', 'Light Gun Shooter', 'Light gun shooter using the Super Scope.', 'Defeat the alien invaders in this first-person shooter.', 'Experience Space Bazooka on the Super Famicom.', 'Known as "Battle Clash" in the West. A technical 16-bit masterpiece for the Super Scope, featuring massive mecha bosses and destructible environments in a futuristic tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-football---one-on-one-usa', 'SNES', 'Space Football - One on One (USA)', '1992', 'Sports', 'Argonaut Games', '2', 'Sports Arcade', 'Futuristic sports simulation (One-on-One).', 'Win the intergalactic soccer-style tournament in space.', 'Play Space Football on the Super Nintendo.', 'A unique 16-bit sports game using Mode 7 effects for a first-person perspective. Navigate your craft, steal the ball, and score goals in zero-gravity arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-funky-bob-japan', 'SNES', 'Space Funky B.O.B. (Japan)', '1993', 'Platformer', 'Irem', '1', 'Action Platformer', 'Action-platformer with a remote-controlled robot.', 'Escape the alien planet using your specialized robot arm.', 'Experience Space Funky B.O.B. on the Super Famicom.', 'Known as "B.O.B." in the West. A clever 16-bit platformer where you use various remote gadgets and weapon attachments to navigate industrial alien mazes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders---the-original-game-europe', 'SNES', 'Space Invaders - The Original Game (Europe)', '1997', 'Shooter', 'Taito', '2', 'Fixed Shooter', 'Faithful arcade port of the legendary shooter.', 'Defeat the waves of descending aliens for the high score.', 'Play Space Invaders on the Super Nintendo.', 'A 16-bit tribute to the arcade classic. Includes the original black-and-white mode, the "cellophane" version, and an updated mode with enhanced SNES graphics and sound.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders---the-original-game-japan', 'SNES', 'Space Invaders - The Original Game (Japan)', '1997', 'Shooter', 'Taito', '2', 'Fixed Shooter', 'Faithful arcade port (Original Japanese release).', 'Relive the arcade revolution in this 16-bit collection.', 'Experience Space Invaders on the Super Famicom.', 'The definitive 16-bit Japanese edition. Features a "Versus" mode for two players and multiple visual filters to recreate the 1978 arcade experience perfectly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders---the-original-game-usa', 'SNES', 'Space Invaders - The Original Game (USA)', '1997', 'Shooter', 'Taito', '2', 'Fixed Shooter', 'Faithful arcade port with updated features.', 'Defend Earth in the official North American version.', 'Play the classic Space Invaders on the SNES.', 'Features a competitive two-player mode where clearing lines of invaders sends more to your opponent''s screen. A perfect 16-bit recreation of a gaming legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-megaforce-usa', 'SNES', 'Space Megaforce (USA)', '1993', 'Shooter', 'Compile', '1', 'Vertical Shooter', 'Vertical-scrolling shoot ''em up (Shmup).', 'Blast through the alien fleet with an evolving arsenal.', 'Experience the legendary Space Megaforce on SNES.', 'Developed by Compile. Known as "Super Aleste" in Japan, it is one of the most technical 16-bit shooters, featuring eight weapon types and massive, screen-filling bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spankys-quest-europe', 'SNES', 'Spanky''s Quest (Europe)', '1993', 'Platformer', 'Natsume', '1', 'Puzzle Platformer', 'Puzzle-platformer starring a bubble-blowing monkey.', 'Climb the tower and defeat the evil witch''s minions.', 'Play the charming Spanky''s Quest on the SNES.', 'A unique 16-bit logic game. Bounce bubbles off your head to make them grow, then pop them to turn them into various sports balls that clear enemies from the screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spankys-quest-usa', 'SNES', 'Spanky''s Quest (USA)', '1993', 'Platformer', 'Natsume', '1', 'Puzzle Platformer', 'Puzzle-platformer starring a bubble-blowing monkey.', 'Complete the 16-bit trials to rescue your monkey friends.', 'Experience Spanky''s Quest for the Super Nintendo.', 'Features bright, colorful graphics and addictive gameplay. Master the bubble-bouncing physics across five themed worlds to reach the ultimate boss.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spark-world-japan', 'SNES', 'Spark World (Japan)', '1995', 'Action', 'Kaneko', '1', 'Action Platformer', 'Competitive top-down puzzle game (Bomberman style).', 'Defeat your rivals in a maze of explosive sparks.', 'Explore Spark World on the Super Famicom.', 'A 16-bit competitive gem. Similar to Bomberman but with a vehicular theme. Use various power-ups and specialized "spark" weapons to outmaneuver opponents in 4-player combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sparkster-europe', 'SNES', 'Sparkster (Europe)', '1994', 'Platformer', 'Minakuchi Engineering', '1', 'Action Platformer', 'Side-scrolling action starring the rocket-powered opossum.', 'Stop the Gedol Empire and rescue the princess.', 'Experience Sparkster on the Super Nintendo.', 'A 16-bit masterpiece from Konami. Use your jetpack to dash across levels, perform acrobatic sword slashes, and engage in epic, cinematic boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sparkster-japan', 'SNES', 'Sparkster (Japan)', '1994', 'Platformer', 'Minakuchi Engineering', '1', 'Action Platformer', 'Side-scrolling action-platformer (Japanese release).', 'Master the rocket-dash in the official Japanese version.', 'Play Sparkster on the Super Famicom.', 'The official 16-bit Japanese edition of the Rocket Knight sequel. Features incredible fluid animation, massive sprites, and some of the best music on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sparkster-usa', 'SNES', 'Sparkster (USA)', '1994', 'Platformer', 'Minakuchi Engineering', '1', 'Action Platformer', 'Side-scrolling action with intense jetpack mechanics.', 'Avenge your kingdom in this high-octane 16-bit quest.', 'Play the classic Sparkster on the SNES.', 'Separate from the Genesis version, this SNES entry features unique levels and mechanics. Use your rocket pack for both traversal and powerful "drill" attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spawn-europe', 'SNES', 'Spawn (Europe)', '1995', 'Action', 'Ukiyotei', '1', 'Action Adventure', 'Side-scrolling beat ''em up based on the Image comic.', 'Hunt down the 12 disciples of Malebolgia as Spawn.', 'Experience the dark world of Spawn on the SNES.', 'A visually stunning 16-bit brawler. Features massive, detailed sprites and a dark atmosphere. Use Spawn''s cape, chains, and magic to defeat the forces of Hell.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spawn-japan-proto', 'SNES', 'Spawn (Japan) (Proto)', '1995', 'Action', 'Ukiyotei', '1', 'Action Adventure', 'Side-scrolling beat ''em up (Japanese Prototype).', 'Test the early combat animations and cape physics.', 'Check out the Spawn Prototype on the Super Famicom.', 'A rare 16-bit development slice. Witness the initial implementation of Spawn''s special move meter and the evolution of the gritty urban backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spawn-usa', 'SNES', 'Spawn (USA)', '1995', 'Action', 'Ukiyotei', '1', 'Action Adventure', 'Side-scrolling beat ''em up starring the Hellspawn.', 'Reclaim your soul in this cinematic 16-bit brawler.', 'Play the official Spawn game on the SNES.', 'Features complex combat mechanics including defensive blocks and special magical attacks. A challenging 16-bit title that captures the dark aesthetic of Todd McFarlane''s creation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spectre-europe', 'SNES', 'Spectre (Europe)', '1994', 'Action', 'Velocity', '1', 'Action Shooter', '3D-style tank combat using Mode 7 and scaling.', 'Destroy the enemy cyber-tanks in a futuristic arena.', 'Experience the 3D action of Spectre on the SNES.', 'A 16-bit port of the Macintosh classic. Navigate a wireframe-style 3D world, collect flags, and engage in tactical tank warfare in both solo and multiplayer modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spectre-usa', 'SNES', 'Spectre (USA)', '1994', 'Action', 'Velocity', '1', 'Action Shooter', '3D-style tank combat simulation (USA release).', 'Master the arena in this 16-bit vehicular shooter.', 'Play the futuristic Spectre on the Super Nintendo.', 'Features multiple tank types and a fast-paced "Battle" mode. A technical 16-bit achievement that provides a unique sense of depth and speed for the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speed-racer-usa', 'SNES', 'Speed Racer (USA)', '1993', 'Action', 'Radical Entertainment', '1', 'Arcade Racing', 'Fast-paced racing based on the classic anime.', 'Win the world grand prix with the legendary Mach 5.', 'Race to victory in Speed Racer for the SNES.', 'A high-speed 16-bit racer. Use the Mach 5''s special gadgets, including the rotary saws and jumping jacks, to overcome obstacles and sabotage rival racers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedy-gonzales---level-6-1-bugfix', 'SNES', 'Speedy Gonzales - Level 6-1 bugfix', '1995', 'Platformer', 'Sunsoft', '1', 'Action Platformer', 'Side-scrolling platformer (Technical Bugfix).', 'Complete the game without the infamous level 6-1 crash.', 'Play the fixed Speedy Gonzales on the SNES.', 'A 16-bit fan correction for a known retail bug. This version ensures that players can progress past the sixth world, which was impossible on certain original cartridges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedy-gonzales-in-los-gatos-bandidos-europe-proto', 'SNES', 'Speedy Gonzales in Los Gatos Bandidos (Europe) (Proto)', '1995', 'Platformer', 'Sunsoft', '1', 'Action Platformer', 'Side-scrolling platformer (European Prototype).', 'Explore the early speed physics and level designs.', 'Check out the Speedy Gonzales Proto on the SNES.', 'A rare 16-bit development look at the European version. Witness the initial implementation of the rescue mechanics and the evolution of the desert stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedy-gonzales-in-los-gatos-bandidos-usa', 'SNES', 'Speedy Gonzales in Los Gatos Bandidos (USA)', '1995', 'Platformer', 'Sunsoft', '1', 'Action Platformer', 'Fast-paced side-scrolling platformer.', 'Rescue your mice friends from the cats'' traps.', 'Play Speedy Gonzales in Los Gatos Bandidos on SNES.', 'A high-speed 16-bit title similar to Sonic. Run through diverse levels, use your speed to bypass obstacles, and find hidden areas to rescue the captured mice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedy-gonzales-in-los-gatos-bandidos-usa-beta', 'SNES', 'Speedy Gonzales in Los Gatos Bandidos (USA) (Beta)', '1995', 'Platformer', 'Sunsoft', '1', 'Action Platformer', 'Side-scrolling platformer (Pre-release build).', 'Test the early dash mechanics and boss triggers.', 'Check out the Speedy Gonzales Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the speed-boost physics and the initial implementation of the humorous death animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedy-gonzales-in-los-gatos-bandidos-usa-rev-a', 'SNES', 'Speedy Gonzales in Los Gatos Bandidos (USA) (Rev A)', '1995', 'Platformer', 'Sunsoft', '1', 'Action Platformer', 'Fast-paced side-scrolling platformer (Updated Revision).', 'Experience the refined quest in this polished 16-bit version.', 'Play Speedy Gonzales (Rev A) on the SNES.', 'The updated 16-bit retail version. Fixes minor graphical glitches and improves performance during high-speed sequences, offering the most stable official experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spellcraft-usa-proto', 'SNES', 'SpellCraft (USA) (Proto)', '1992', 'RPG', 'American Softworks', '1', 'Action RPG', 'Tactical JRPG with a focus on spell crafting (Prototype).', 'Master the elements and defeat the dark sorcerers.', 'Explore the unreleased SpellCraft on the SNES.', 'A rare 16-bit unreleased prototype. Features a complex magic system where players combine components to create spells, blended with real-time tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-europe', 'SNES', 'Spider-Man (Europe)', '1994', 'Action', 'Western Technologies', '1', 'Action Platformer', 'Side-scrolling action-platformer based on the TAS series.', 'Stop the Kingpin and the Sinister Six in NYC.', 'Play Spider-Man (The Animated Series) on SNES.', 'A 16-bit action title based on the hit 90s cartoon. Use web-swinging, wall-crawling, and spider-sense to navigate through expansive urban levels and defeat iconic Marvel villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-usa', 'SNES', 'Spider-Man (USA)', '1994', 'Action', 'Western Technologies', '1', 'Action Platformer', 'Side-scrolling action-platformer (USA release).', 'Protect New York City from the Sinister Six''s plot.', 'Experience Spider-Man on the Super Nintendo.', 'Features multiple guest appearances from other Marvel heroes. Master Spidey''s web-fluid management and combat skills in this challenging 16-bit superhero adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-usa-beta', 'SNES', 'Spider-Man (USA) (Beta)', '1994', 'Action', 'Western Technologies', '1', 'Action Platformer', 'Side-scrolling action-platformer (Pre-release build).', 'Test the web-swinging physics and boss AI.', 'Check out the Spider-Man Beta on the SNES.', 'A rare 16-bit development look at the animated series tie-in. Witness early level layouts and sprite animations before the final balancing of the web-slinging mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-&-venom---maximum-carnage-europe', 'SNES', 'Spider-Man & Venom - Maximum Carnage (Europe)', '1994', 'Action', 'Software Creations', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up based on the comic event.', 'Stop Carnage''s massacre by choosing between Spidey or Venom.', 'Play Spider-Man & Venom: Maximum Carnage on SNES.', 'A 16-bit cult classic. Features a striking art style based on the comics and a brutal difficulty curve. Use various Marvel cameos to clear waves of enemies in NYC.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-&-venom---maximum-carnage-usa', 'SNES', 'Spider-Man & Venom - Maximum Carnage (USA)', '1994', 'Action', 'Software Creations', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up (USA release).', 'Team up with Venom to defeat the insane Carnage.', 'Experience Maximum Carnage on the Super Nintendo.', 'The official 16-bit adaptation of the 1993 crossover. Famous for its red-colored cartridge and intense soundtrack, offering one of the most faithful comic-book experiences on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-&-venom---separation-anxiety-europe', 'SNES', 'Spider-Man & Venom - Separation Anxiety (Europe)', '1995', 'Action', 'Software Creations', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring 2-player co-op.', 'Stop the Phage and the other symbiote clones.', 'Play Separation Anxiety on the Super Nintendo.', 'The 16-bit sequel to Maximum Carnage. Unlike its predecessor, it features a simultaneous 2-player mode where Spidey and Venom must work together to dismantle the Jury.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-&-venom---separation-anxiety-usa', 'SNES', 'Spider-Man & Venom - Separation Anxiety (USA)', '1995', 'Action', 'Software Creations', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up (USA release).', 'Defeat the five symbiotes and rescue the city.', 'Experience Spider-Man & Venom: Separation Anxiety on SNES.', 'A 16-bit brawler with larger levels and cooperative gameplay. Battle through secret laboratories and urban streets to face the ultimate symbiote threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-and-the-x-men-in-arcades-revenge-europe', 'SNES', 'Spider-Man and the X-Men in Arcade''s Revenge (Europe)', '1992', 'Action', 'Software Creations', '1', 'Action Platformer', 'Multi-character action-platformer featuring Marvel heroes.', 'Escape Arcade''s Murderworld as the X-Men and Spider-Man.', 'Play Arcade''s Revenge on the Super Nintendo.', 'A challenging 16-bit crossover. Switch between Spider-Man, Wolverine, Cyclops, Storm, and Gambit, each with unique levels designed around their specific superpowers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-and-the-x-men-in-arcades-revenge-usa', 'SNES', 'Spider-Man and the X-Men in Arcade''s Revenge (USA)', '1992', 'Action', 'Software Creations', '1', 'Action Platformer', 'Multi-character action-platformer (USA release).', 'Defeat Arcade and survive the deadly amusement park.', 'Experience Spider-Man and the X-Men on the SNES.', 'Features a legendary soundtrack by Tim Follin. Master the diverse gameplay styles, from Storm''s underwater levels to Gambit''s platforming challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-and-the-x-men-in-arcades-revenge-usa-4-man-version', 'SNES', 'Spider-Man and the X-Men in Arcade''s Revenge (USA) (4 Man Version)', '1992', 'Action', 'Software Creations', '4', 'Action Platformer', 'Action-platformer (Modified 4-Man Version).', 'Play through Arcade''s Revenge with specialized hero tweaks.', 'Try the 4-Man Version of Spider-Man/X-Men on SNES.', 'A 16-bit fan modification that adjusts character stats and level progression, offering a fresh take on the punishing difficulty of the original Murderworld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spindizzy-worlds-europe', 'SNES', 'Spindizzy Worlds (Europe)', '1993', 'Puzzle', 'ASCII Entertainment', '1', 'Puzzle Platformer', 'Isometric puzzle and exploration game.', 'Navigate the spinning world and collect the golden orbs.', 'Play the mind-bending Spindizzy Worlds on the SNES.', 'A technical 16-bit isometric adventure. Control the GERALD craft through complex geometric landscapes, managing momentum and fuel while solving intricate environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spindizzy-worlds-japan', 'SNES', 'Spindizzy Worlds (Japan)', '1993', 'Puzzle', 'ASCII Entertainment', '1', 'Puzzle Platformer', 'Isometric puzzle and exploration (Japanese release).', 'Master the momentum in the official Japanese edition.', 'Experience Spindizzy Worlds on the Super Famicom.', 'The official 16-bit Japanese port. Features a high level of difficulty and hundreds of levels across two different solar systems, showcasing impressive isometric physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spindizzy-worlds-usa', 'SNES', 'Spindizzy Worlds (USA)', '1993', 'Puzzle', 'ASCII Entertainment', '1', 'Puzzle Platformer', 'Isometric puzzle and exploration (USA release).', 'Solve the cosmic labyrinths in this 16-bit puzzler.', 'Play Spindizzy Worlds for the Super Nintendo.', 'A meditative yet challenging logic game. Use the 16-bit rotation mechanics to find the best path through floating platforms and hazardous traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spirou-europe-enfrdees', 'SNES', 'Spirou (Europe) (En,Fr,De,Es)', '1995', 'Platformer', 'Infogrames', '1', 'Action Platformer', 'Side-scrolling platformer based on the Belgian comic.', 'Rescue Count Champignac in this vibrant 16-bit quest.', 'Play Spirou on the Super Nintendo.', 'A beautifully animated 16-bit platformer. Guide the famous bellhop through international locations, featuring smooth controls and art that perfectly captures the Franco-Belgian style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sporting-news-power-baseball-the-usa', 'SNES', 'Sporting News Power Baseball, The (USA)', '1994', 'Sports', 'HAL America', '2', 'Baseball Simulation', 'Realistic baseball simulation with depth.', 'Win the pennant in this professional 16-bit sports sim.', 'Experience Sporting News Power Baseball on the SNES.', 'Features detailed player stats and smooth animations. Focuses on a realistic broadcast presentation and deep management options for baseball enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-illustrated-championship-football-&-baseball-usa', 'SNES', 'Sports Illustrated Championship Football & Baseball (USA)', '1994', 'Sports', 'Malibu Interactive', '2', 'Sports Simulation', 'Multi-sport simulation (Football & Baseball).', 'Master two sports in one 16-bit competitive package.', 'Play SI Championship Football & Baseball on SNES.', 'A unique 16-bit sports compilation. Features realistic play-calling in football and traditional arcade-style action in baseball, endorsed by Sports Illustrated.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-illustrated-championship-football-&-baseball-usa-beta', 'SNES', 'Sports Illustrated Championship Football & Baseball (USA) (Beta)', '1994', 'Sports', 'Malibu Interactive', '2', 'Sports Simulation', 'Multi-sport simulation (Pre-release build).', 'Test the ball physics across both sporting modes.', 'Check out the SI Championship Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the stat-tracking menus and the tuning of the fielder AI before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spot-goes-to-hollywood-usa-proto-1995-08-05', 'SNES', 'Spot Goes to Hollywood (USA) (Proto) (1995-08-05)', '1995', 'Platformer', 'Eurocom', '1', 'Action Platformer', 'Isometric platformer starring the 7-Up mascot (Proto).', 'Explore the movie-themed worlds in this unreleased proto.', 'Check out Spot Goes to Hollywood on the SNES.', 'A rare 16-bit unreleased prototype of the isometric sequel. Navigate through detailed 3D-style movie sets, collecting red spots and dodging hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spriggan-powered-japan', 'SNES', 'Spriggan Powered (Japan)', '1996', 'Shooter', 'Naxat Soft', '1', 'Horizontal Shooter', 'Horizontal-scrolling shoot ''em up (Shmup).', 'Defeat the mechanized empire with your magical armor.', 'Experience Spriggan Powered on the Super Famicom.', 'A late-gen 16-bit masterpiece. Features incredible pre-rendered graphics, a shield-based power-up system, and some of the most impressive boss fights in the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sprinter-monogatari---mezase!!-ikkakusenkin-japan', 'SNES', 'Sprinter Monogatari - Mezase!! Ikkakusenkin (Japan)', '1994', 'Action', 'TOSE', '1', 'Sports Action', 'Horse racing and management simulation.', 'Train your sprinter to become the champion of the track.', 'Play Sprinter Monogatari on the Super Famicom.', 'A detailed 16-bit horse racing sim. Manage training schedules, breeding, and race tactics to earn a fortune in the high-stakes world of Japanese racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('squirrel', 'SNES', 'Squirrel', '1997', 'Platformer', 'Homebrew', '1', 'Indie Platformer', 'Action-platformer featuring a squirrel (Homebrew/Indie).', 'Collect nuts and survive the forest in this modern 16-bit game.', 'Experience the indie title Squirrel on the SNES.', 'A modern 16-bit creation for the SNES. Features classic platforming mechanics and colorful pixel art, showcasing the enduring appeal of the Super Nintendo hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('squitters-spider-quest', 'SNES', 'Squitter''s Spider Quest', '2016', 'Platformer', 'Homebrew', '1', 'Indie Platformer', 'Action-platformer featuring a spider (Fan-made).', 'Navigate the webs and survive the garden hazards.', 'Play Squitter''s Spider Quest on the SNES.', 'A creative 16-bit modification or homebrew title. Focuses on web-slinging mechanics and environmental puzzles from a spider''s perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('st-andrews---eikou-to-rekishi-no-old-course-japan', 'SNES', 'St. Andrews - Eikou to Rekishi no Old Course (Japan)', '1996', 'Sports', 'T&E Soft', '1', 'Golf Simulation', 'Realistic golf simulation on the historic Old Course.', 'Master the winds of St. Andrews in this 16-bit sim.', 'Play St. Andrews Old Course on the Super Famicom.', 'A technical 16-bit golf game featuring a faithful digital recreation of the legendary Scottish course. Includes realistic terrain physics and weather effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stable-star---kyuusha-monogatari-japan', 'SNES', 'Stable Star - Kyuusha Monogatari (Japan)', '1996', 'Simulation', 'Artdink', '1', 'Horse Racing Simulation', 'Horse racing management and RPG hybrid.', 'Build your stable and raise a legendary racing horse.', 'Explore Stable Star on the Super Famicom.', 'A deep 16-bit simulation from Koei. Focuses on the life of a stable manager, blending social interactions with horse breeding and tactical race management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox---ex', 'SNES', 'Star Fox - EX', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', 'Fan-made expansion/overhaul of Star Fox (EX).', 'Experience an expanded Lylat System with new features.', 'Play the Star Fox EX mod on the Super Nintendo.', 'An impressive 16-bit fan modification that adds new levels, ships, and features to the original Star Fox engine, pushing the Super FX chip to its limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-japan', 'SNES', 'Star Fox (Japan)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', 'Groundbreaking 3D rail shooter (Original Japanese release).', 'Save the Lylat System from Andross as the Star Fox team.', 'Experience the original Star Fox on the Super Famicom.', 'The 16-bit debut of real 3D on SNES. Known as "Starwing" in Europe, it used the Super FX chip to render polygonal ships and environments for the first time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-usa', 'SNES', 'Star Fox (USA)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', 'Groundbreaking 3D rail shooter (USA release).', 'Defeat the forces of Venom in this 16-bit 3D classic.', 'Play the legendary Star Fox on the Super Nintendo.', 'A landmark title that defined 3D gaming on home consoles. Control Fox McCloud in the Arwing through diverse planets with cinematic action and branching paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-usa-rev-b', 'SNES', 'Star Fox (USA) (Rev B)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D rail shooter (Updated Revision B).', 'Experience the most polished version of the Lylat epic.', 'Play Star Fox (Rev B) on the Super Nintendo.', 'The final 16-bit retail revision. Includes minor bug fixes and optimizations for the Super FX chip, providing the most stable version of the original adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-usa-super-weekend-competition', 'SNES', 'Star Fox (USA) (Super Weekend Competition)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D rail shooter (Competitive Weekend Version).', 'Achieve the highest score in this rare competition build.', 'Play Star Fox Super Weekend on the SNES.', 'A rare 16-bit historical artifact used in official 1993 Nintendo tournaments. Features a timed, high-score focused version of the game with unique level shortcuts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-2', 'SNES', 'Star Fox 2', '1995', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D multi-directional space combat and strategy.', 'Defend Corneria from Andross in this non-linear sequel.', 'Experience the official Star Fox 2 on the SNES.', 'Originally unreleased in the 90s. Features six playable characters, transforming Arwings (Walker mode), and a real-time strategy map where you intercept threats across the Lylat System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-2-japan-proto-alt-1-en+hack-by-aeon-genesis-v10-final-version', 'SNES', 'Star Fox 2 (Japan) (Proto) (Alt 1) [En+Hack by Aeon Genesis v1.0] (Final Version)', '1995', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D space combat (English Fan-Patched Final).', 'Play the legendary unreleased sequel in English.', 'Play Star Fox 2 Final Version in English on SNES.', 'The definitive 16-bit fan restoration by Aeon Genesis. Based on the leaked final prototype, it offers the full cinematic experience with translated dialogue and optimized Super FX 2 performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-2-japan-proto-alt-1-en+hack-by-aeon-genesis-v10-fix-by-manuloewe-final-version', 'SNES', 'Star Fox 2 (Japan) (Proto) (Alt 1) [En+Hack by Aeon Genesis v1.0] [Fix by ManuLoewe] (Final Version)', '1995', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D space combat (English Final with Technical Fixes).', 'Experience the smoothest version of the Star Fox sequel.', 'Play Star Fox 2 (ManuLoewe Fix) on the SNES.', 'An enhanced 16-bit version that applies technical stability fixes to the Aeon Genesis translation, ensuring perfect compatibility with modern hardware and original flashcarts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-2-japan-proto2', 'SNES', 'Star Fox 2 (Japan) (Proto2)', '1995', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D space combat (Early Development Prototype).', 'Explore the early evolution of the Arwing''s Walker mode.', 'Check out the Star Fox 2 Proto 2 on the SNES.', 'A rare 16-bit development slice. Features early mission structures and different character select screens, offering a glimpse into the game''s design process before its 1995 cancellation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-exploration-showcase-7863', 'SNES', 'Star Fox Exploration Showcase 7.86.3', '2021', 'Demo', 'Homebrew', '1', 'Tech Demo', '3D space combat (Exploration Hack 7.86.3).', 'Unlock the hidden debug features of the Lylat System.', 'Explore the Star Fox Exploration Showcase on SNES.', 'A 16-bit technical mod designed to showcase the internal assets of the Star Fox engine. Allows players to fly through unreleased test environments and view hidden object models.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-exploration-showcase-8481', 'SNES', 'Star Fox Exploration Showcase 8.48.1', '2022', 'Demo', 'Homebrew', '1', 'Tech Demo', '3D space combat (Exploration Hack 8.48.1).', 'Discover hidden 3D assets and technical secrets.', 'Experience Star Fox Exploration Showcase 8 on SNES.', 'An updated 16-bit technical demonstration. Features expanded camera controls and the ability to trigger unused scripted events, pushing the Super FX chip to its limits for research.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-ocean-japan', 'SNES', 'Star Ocean (Japan)', '1996', 'RPG', 'Tri-Ace', '1', 'Action RPG', 'Epic JRPG with real-time combat and voice acting.', 'Travel across planets to stop a galactic biological threat.', 'Experience the stunning Star Ocean on Super Famicom.', 'One of the most advanced 16-bit RPGs. Uses the S-DD1 chip for high-quality compression, featuring pre-rendered backgrounds, voice clips during battle, and a deep crafting system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-ocean-japan-en-by-dejap-v10', 'SNES', 'Star Ocean (Japan) [En by DeJap v1.0]', '1996', 'RPG', 'Tri-Ace', '1', 'Action RPG', 'Epic JRPG (Full English Translation v1.0).', 'Experience the first Star Ocean in English.', 'Play Star Ocean in English on the Super Nintendo.', 'The legendary 16-bit fan translation by DeJap. Brings the massive sci-fi narrative and complex "Private Action" character system to Western players for the first time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---deep-space-nine---crossroads-of-time-europe', 'SNES', 'Star Trek - Deep Space Nine - Crossroads of Time (Europe)', '1995', 'Action', 'Novotrade', '1', 'Action Platformer', 'Cinematic action-adventure based on the TV series.', 'Stop a Bajoran terrorist plot as Sisko and the crew.', 'Play Star Trek: DS9 Crossroads of Time on SNES.', 'A multi-genre 16-bit adventure. Combines side-scrolling platforming and combat on alien worlds with tactical dialogue sequences and space-station exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---deep-space-nine---crossroads-of-time-usa', 'SNES', 'Star Trek - Deep Space Nine - Crossroads of Time (USA)', '1995', 'Action', 'Novotrade', '1', 'Action Platformer', 'Cinematic action-adventure (USA release).', 'Protect Deep Space Nine in this 16-bit sci-fi quest.', 'Experience Star Trek: DS9 for the Super Nintendo.', 'Features digitized sprites of the show''s cast. Navigate through 16-bit environments inspired by the Alpha Quadrant, solving puzzles and battling the Jem''Hadar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---deep-space-nine---crossroads-of-time-usa-beta', 'SNES', 'Star Trek - Deep Space Nine - Crossroads of Time (USA) (Beta)', '1995', 'Action', 'Novotrade', '1', 'Action Platformer', 'Cinematic action-adventure (Pre-release build).', 'Test the early phaser combat and platforming levels.', 'Check out the Star Trek: DS9 Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s movement animations and the evolution of the space station''s hub area.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---starfleet-academy-europe', 'SNES', 'Star Trek - Starfleet Academy (Europe)', '1995', 'Simulation', 'Interplay', '1', 'Space Simulation', 'Space flight simulation and bridge command.', 'Graduate from the Academy and become a Starfleet officer.', 'Experience Star Trek: Starfleet Academy on SNES.', 'A technical 16-bit flight sim. Complete various bridge-command scenarios, managing shields, weapons, and crew while navigating through 3D space environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---starfleet-academy-germany', 'SNES', 'Star Trek - Starfleet Academy (Germany)', '1995', 'Simulation', 'Interplay', '1', 'Space Simulation', 'Space flight simulation (German localization).', 'Bestehe die Prüfungen der Sternenflotte auf Deutsch.', 'Spielen Sie Starfleet Academy auf Deutsch für das SNES.', 'The complete 16-bit simulation localized for German players. Master the bridge controls and diplomatic choices across dozens of challenging training missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---starfleet-academy-usa', 'SNES', 'Star Trek - Starfleet Academy (USA)', '1995', 'Simulation', 'Interplay', '1', 'Space Simulation', 'Space flight simulation and tactical combat.', 'Master the bridge of a Federation starship in 16-bit.', 'Play Star Trek: Starfleet Academy for the SNES.', 'Includes various mission types from dogfights to diplomatic negotiations. A unique simulation that emphasizes tactical decision-making over pure arcade action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---the-next-generation---futures-past-europe', 'SNES', 'Star Trek - The Next Generation - Future''s Past (Europe)', '1994', 'Action', 'Sculptured Software', '1', 'Action Platformer', 'Tactical adventure based on the TNG series.', 'Save the Romulan neutral zone as Captain Picard.', 'Play Star Trek: TNG Future''s Past on the SNES.', 'A 16-bit mix of top-down away-team missions and bridge-view space combat. Navigate the Enterprise through the sector and solve the mystery of an ancient civilization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---the-next-generation---futures-past-usa', 'SNES', 'Star Trek - The Next Generation - Future''s Past (USA)', '1994', 'Action', 'Sculptured Software', '1', 'Action Platformer', 'Tactical adventure and space combat (USA release).', 'Command the Enterprise-D in this 16-bit sci-fi sim.', 'Experience Star Trek: TNG Future''s Past on SNES.', 'Features a non-linear mission structure. Manage ship energy, transport teams to planets for puzzle-solving, and engage in tactical 16-bit battles with Warbirds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stardust-suplex-japan', 'SNES', 'Stardust Suplex (Japan)', '1995', 'Fighting', 'Human Entertainment', '2', 'Professional Wrestling', '2D professional wrestling with anime-style graphics.', 'Win the wrestling championship in this 16-bit fighter.', 'Experience Stardust Suplex on the Super Famicom.', 'A technical 16-bit wrestling game from Varie. Features an all-female cast, fluid animations, and a deep moveset including high-flying maneuvers and submission holds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stargate-europe-enfrde', 'SNES', 'Stargate (Europe) (En,Fr,De)', '1994', 'Action', 'Probe Entertainment', '1', 'Action Platformer', 'Cinematic action-platformer based on the 1994 film.', 'Travel through the gate and defeat the false god Ra.', 'Play the official Stargate on the Super Nintendo.', 'A visually impressive 16-bit title. Use grenades and machine guns to fight through Abydos, featuring a mix of action, mission objectives, and puzzle-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stargate-japan', 'SNES', 'Stargate (Japan)', '1994', 'Action', 'Probe Entertainment', '1', 'Action Platformer', 'Cinematic action-platformer (Japanese release).', 'Experience the sci-fi epic in the Japanese edition.', 'Play Stargate on the Super Famicom.', 'The official 16-bit Japanese port. Features the same cinematic presentation and high level of difficulty, capturing the atmosphere of the movie''s desert world and high-tech temple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stargate-usa', 'SNES', 'Stargate (USA)', '1994', 'Action', 'Probe Entertainment', '1', 'Action Platformer', 'Cinematic action-platformer featuring Daniel and O''Neil.', 'Navigate the 16-bit desert world and free the slaves.', 'Experience the high-stakes Stargate on the SNES.', 'Known for its detailed sprites and faithful adaptation of the film''s plot. Master the 16-bit combat and complete diverse mission goals to find the way back home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stargate-usa-beta', 'SNES', 'Stargate (USA) (Beta)', '1994', 'Action', 'Probe Entertainment', '1', 'Action Platformer', 'Cinematic action-platformer (Pre-release build).', 'Test the early gunplay and Abydos stage layouts.', 'Check out the Stargate Beta on the Super Nintendo.', 'A rare 16-bit development slice. Witness the initial implementation of the cinematic cutscenes and the tuning of the enemy AI behavior before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starwing-europe', 'SNES', 'Starwing (Europe)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', 'Groundbreaking 3D rail shooter (European release).', 'Defeat Andross in the official European edition.', 'Experience the classic Starwing on the SNES.', 'The PAL version of Star Fox. Named "Starwing" due to trademark issues in Europe, it features the same revolutionary 16-bit 3D gameplay powered by the Super FX chip.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starwing-europe-rev-a', 'SNES', 'Starwing (Europe) (Rev A)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D rail shooter (Updated European Revision).', 'Defeat Andross in the most polished PAL version.', 'Play Starwing (Rev A) on the Super Nintendo.', 'The optimized 16-bit European release. Fixes minor performance issues and localization bugs from the initial launch, providing the smoothest Super FX experience for PAL consoles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starwing-europe-super-weekend-competition', 'SNES', 'Starwing (Europe) (Super Weekend Competition)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D rail shooter (European Competition Edition).', 'Achieve the top score in this rare 16-bit tournament.', 'Experience the Starwing Super Weekend on SNES.', 'A legendary 16-bit historical artifact. Used in the 1993 European Nintendo competitions, featuring a timed score-attack mode with unique shortcuts and bonus items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starwing-germany', 'SNES', 'Starwing (Germany)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D rail shooter (German localization).', 'Rette das Lylat-System in der deutschen Version.', 'Spielen Sie Starwing auf Deutsch für das SNES.', 'The complete 16-bit 3D classic with full German text. Command Fox McCloud''s team through polygonal worlds in this landmark title for the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('starwing-germany-competition-edition', 'SNES', 'Starwing (Germany) (Competition Edition)', '1993', 'Shooter', 'Nintendo', '1', 'On-Rails Shooter', '3D rail shooter (German Competition Edition).', 'Win the German 16-bit Starwing championship.', 'Experience the Starwing Competition Edition (Germany).', 'A rare promotional 16-bit cartridge used in German gaming events. Features the high-score focused "Super Weekend" gameplay loop designed for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stealth-japan', 'SNES', 'Stealth (Japan)', '1992', 'Action', 'ASCII', '1', 'Isometric Action', 'Tactical stealth-action and strategy.', 'Infiltrate enemy territory without being detected.', 'Explore the tactical Stealth on Super Famicom.', 'A unique 16-bit strategy title. Focuses on line-of-sight mechanics and careful movement to complete covert missions during a fictional military conflict.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('steel-talons-usa', 'SNES', 'Steel Talons (USA)', '1994', 'Shooter', 'Atari Games', '1', 'Vehicle Combat', '3D helicopter combat simulation.', 'Complete dangerous missions in an ATLH helicopter.', 'Experience Steel Talons on the Super Nintendo.', 'A 16-bit port of the Atari arcade hit. Uses polygonal-style graphics to simulate flight and ground-attack missions across various desert and urban environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sterling-sharpe-end-2-end-usa', 'SNES', 'Sterling Sharpe End 2 End (USA)', '1995', 'Sports', 'Midway', '2', 'American Football', 'Realistic American Football simulation.', 'Lead your team to the championship with Sterling Sharpe.', 'Play Sterling Sharpe End 2 End on the SNES.', 'A technical 16-bit football sim. Features detailed playbooks, smooth field scrolling, and a focus on realistic player stats endorsed by the legendary wide receiver.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('steven-seagal-is-the-final-option-usa-proto', 'SNES', 'Steven Seagal Is The Final Option (USA) (Proto)', '1994', 'Action', 'Virgin Interactive', '1', 'Action Shooter', 'Side-scrolling beat ''em up (Unreleased Prototype).', 'Defeat the underworld as the martial arts master.', 'Explore Steven Seagal Is The Final Option on SNES.', 'A rare 16-bit unreleased brawler. Features digitized sprites of Steven Seagal and a technical combat system focused on aikido throws and joint locks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stone-protectors-japan-proto', 'SNES', 'Stone Protectors (Japan) (Proto)', '1994', 'Action', 'Eurocom', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up (Japanese Prototype).', 'Stop the Zokks in this anime-inspired 16-bit brawler.', 'Check out Stone Protectors on the Super Famicom.', 'A rare 16-bit development look at the Japanese localization. Features vibrant graphics and specialized moves for each of the five gem-powered heroes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stone-protectors-usa', 'SNES', 'Stone Protectors (USA)', '1994', 'Action', 'Eurocom', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up based on the toy line.', 'Recover the Great Crystals and defeat Zok.', 'Play the action-packed Stone Protectors on SNES.', 'A colorful and high-energy 16-bit brawler. Combines traditional beat ''em up gameplay with a variety of special moves and rock-and-roll themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-combat-europe', 'SNES', 'Street Combat (Europe)', '1993', 'Action', 'Players', '2', 'Beat ''em Up', '2D fighting game with futuristic warriors.', 'Defeat the master fighters in this localized 16-bit brawler.', 'Experience Street Combat on the Super Nintendo.', 'The Western version of Ranma 1/2: Chounai Gekitouhen. Replaces the anime characters with generic cybernetic warriors while retaining the original combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-combat-usa', 'SNES', 'Street Combat (USA)', '1993', 'Action', 'Players', '2', 'Beat ''em Up', '2D fighting game with specialized combatants.', 'Win the underground tournament in this 16-bit fighter.', 'Play Street Combat for the Super Nintendo.', 'Features a variety of fighter types, from robots to martial artists. A unique 16-bit curiosity that showcases how Japanese games were re-skinned for Western markets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-alpha-2-europe', 'SNES', 'Street Fighter Alpha 2 (Europe)', '1996', 'Fighting', 'Capcom', '2', '2D Fighting', 'High-speed 2D fighting game (Alpha series).', 'Experience the prequel saga with advanced 16-bit graphics.', 'Play Street Fighter Alpha 2 on the SNES.', 'A technical miracle on 16-bit hardware. Uses the S-DD1 chip to deliver massive sprites and advanced mechanics like Custom Combos and Alpha Counters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-alpha-2-usa', 'SNES', 'Street Fighter Alpha 2 (USA)', '1996', 'Fighting', 'Capcom', '2', '2D Fighting', 'High-speed 2D fighting game (USA release).', 'Master the legendary combos in this 16-bit masterpiece.', 'Experience Street Fighter Alpha 2 on the SNES.', 'Features an iconic roster including Ryu, Ken, and Akuma. Brings the deep, technical gameplay of the arcade original to the Super Nintendo with impressive fidelity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ex-plus-alpha', 'SNES', 'Street Fighter EX Plus Alpha', '1997', 'Fighting', 'Arika', '2', '3D Fighting', '3D-to-2D fighting game (Unlicensed/Pirate).', 'Fight through the EX roster in this unofficial port.', 'Check out the 16-bit Soul Blade/Street Fighter EX.', 'A bizarre 16-bit unlicensed curiosity. Attempts to translate the 32-bit polygonal fighter into a 2D sprite-based experience on the SNES hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii---the-world-warrior-europe', 'SNES', 'Street Fighter II - The World Warrior (Europe)', '1992', 'Fighting', 'Capcom', '2', '2D Fighting', 'The foundational 2D fighting game.', 'Defeat the eight world warriors and M. Bison.', 'Play the classic Street Fighter II on the SNES.', 'The game that revolutionized the genre. Experience the 16-bit masterpiece that defined competitive gaming, featuring iconic characters and pixel-perfect controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii---the-world-warrior-japan', 'SNES', 'Street Fighter II - The World Warrior (Japan)', '1992', 'Fighting', 'Capcom', '2', '2D Fighting', 'The foundational 2D fighting game (Japanese release).', 'Challenge the world''s best in the original Japanese port.', 'Play Street Fighter II on the Super Famicom.', 'The massive 16-bit hit that sold millions in Japan. Features the complete arcade roster and the timeless soundtrack that defined the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii---the-world-warrior-usa', 'SNES', 'Street Fighter II - The World Warrior (USA)', '1992', 'Fighting', 'Capcom', '2', '2D Fighting', 'The foundational 2D fighting game (USA release).', 'Become the world champion in this 16-bit legend.', 'Experience Street Fighter II for the Super Nintendo.', 'Master the Hadouken and Sonic Boom. This 16-bit port set the standard for all home console fighters to follow, offering near arcade-quality play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii-turbo---hyper-fighting-europe', 'SNES', 'Street Fighter II Turbo - Hyper Fighting (Europe)', '1993', 'Fighting', 'Capcom', '2', '2D Fighting', 'Enhanced 2D fighting game with increased speed.', 'Master the faster "Hyper Fighting" rules and boss play.', 'Play Street Fighter II Turbo on the SNES.', 'The definitive 16-bit update. Adds the four bosses as playable characters, new special moves for the original roster, and significantly increased game speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii-turbo---hyper-fighting-europe-rev-a', 'SNES', 'Street Fighter II Turbo - Hyper Fighting (Europe) (Rev A)', '1993', 'Fighting', 'Capcom', '2', '2D Fighting', 'Enhanced 2D fighting game (Updated Revision).', 'Experience the most balanced 16-bit Turbo edition.', 'Play Street Fighter II Turbo (Rev A) on the SNES.', 'A refined 16-bit revision that fixes minor graphical glitches and balances the damage scaling for the four Grand Masters (Balrog, Vega, Sagat, and Bison).');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii-turbo---hyper-fighting-japan-rev-0a', 'SNES', 'Street Fighter II Turbo - Hyper Fighting (Japan) (Rev 0A)', '1993', 'Fighting', 'Capcom', '2', '2D Fighting', 'Enhanced 2D fighting game (Japanese Revision).', 'Master the high-speed combat in the revised Japanese port.', 'Play Street Fighter II Turbo on the Super Famicom.', 'The optimized 16-bit Japanese release. Features the "Hyper" mode for extreme speed and the traditional "Turbo" mode for competitive balance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii-turbo---hyper-fighting-usa', 'SNES', 'Street Fighter II Turbo - Hyper Fighting (USA)', '1993', 'Fighting', 'Capcom', '2', '2D Fighting', 'High-speed 2D fighting game (USA retail).', 'Defeat your rivals at lightning speed in 16-bit.', 'Experience Street Fighter II Turbo on the SNES.', 'Considered by many to be the best fighting game on the system. Master the refined hitboxes and the expanded move lists of the world''s greatest warriors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-zero-2-japan', 'SNES', 'Street Fighter Zero 2 (Japan)', '1996', 'Fighting', 'Capcom', '2', '2D Fighting', 'High-speed 2D fighting game (Japanese Alpha 2).', 'Experience the prequel lore in the original Japanese version.', 'Play Street Fighter Zero 2 on the Super Famicom.', 'The official 16-bit Japanese release. Features the full "Zero" roster and cinematic story endings, pushing the SNES hardware to its absolute limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-hockey-95-usa', 'SNES', 'Street Hockey ''95 (USA)', '1995', 'Sports', 'FTL Games', '2', 'Ice Hockey', 'Fast-paced urban sports simulation.', 'Win the street hockey tournament in the city.', 'Play Street Hockey ''95 on the Super Nintendo.', 'A unique 16-bit sports title. Swap traditional ice for asphalt and use a variety of "street" moves and power-ups to defeat rival teams in various urban arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-hockey-95-usa-beta', 'SNES', 'Street Hockey ''95 (USA) (Beta)', '1995', 'Sports', 'FTL Games', '2', 'Ice Hockey', 'Urban sports simulation (Pre-release build).', 'Test the early skating physics and puck logic.', 'Check out the Street Hockey ''95 Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the character''s rollerblade animations and the tuning of the AI''s defensive behavior.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-racer-europe', 'SNES', 'Street Racer (Europe)', '1994', 'Racing', 'Vivid Image', '4', 'Arcade Racing', 'Mode 7 racing game with 8-player local play.', 'Outrace and outfight your rivals in this 16-bit classic.', 'Experience the chaotic Street Racer on the SNES.', 'A technical 16-bit marvel. Similar to Mario Kart but with a focus on combat and a smooth frame rate that supports up to 4 players on a split-screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-racer-europe-rev-a', 'SNES', 'Street Racer (Europe) (Rev A)', '1994', 'Racing', 'Vivid Image', '4', 'Arcade Racing', 'Mode 7 racing game (Updated European Revision).', 'Master the combat-racing tracks in this refined edition.', 'Play Street Racer (Rev A) on the Super Nintendo.', 'The updated 16-bit PAL release. Optimizes the Mode 7 scrolling and fixes minor multiplayer synchronization issues for a smoother competitive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-racer-japan', 'SNES', 'Street Racer (Japan)', '1994', 'Racing', 'Vivid Image', '4', 'Arcade Racing', 'Mode 7 racing game (Japanese release).', 'Win the world championship in the official Japanese version.', 'Play Street Racer on the Super Famicom.', 'The 16-bit Japanese edition of the hit racer. Features quirky characters, diverse tracks, and the addictive "Soccer" and "Rumble" bonus modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-racer-usa', 'SNES', 'Street Racer (USA)', '1994', 'Racing', 'Vivid Image', '4', 'Arcade Racing', 'Mode 7 racing game featuring diverse characters.', 'Use specialized attacks to clear the track and win.', 'Experience Street Racer for the Super Nintendo.', 'Master the unique abilities of characters like Hodja or Surf. A high-energy 16-bit racer that pushes the SNES hardware with impressive scaling and rotation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-racer-usa-beta', 'SNES', 'Street Racer (USA) (Beta)', '1994', 'Racing', 'Vivid Image', '4', 'Arcade Racing', 'Mode 7 racing game (Pre-release build).', 'Test the early weapon logic and track scaling.', 'Check out the Street Racer Beta on the SNES.', 'A rare 16-bit development slice. Witness the fine-tuning of the character-specific combat moves and the initial implementation of the bonus mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strike-gunner-stg-japan', 'SNES', 'Strike Gunner S.T.G (Japan)', '1991', 'Shooter', 'Athena', '2', 'Vertical Shooter', 'Vertical-scrolling shoot ''em up with a weapon-selection system.', 'Defeat the alien invasion using customizable jet fighters.', 'Experience the intense Strike Gunner S.T.G on SNES.', 'A technical 16-bit shooter. Before each stage, choose from a variety of specialized sub-weapons like homing missiles or sonic waves to complement your dual-pilot fire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strike-gunner-stg-usa', 'SNES', 'Strike Gunner S.T.G (USA)', '1991', 'Shooter', 'Athena', '2', 'Vertical Shooter', 'Vertical-scrolling shoot ''em up (USA release).', 'Master the 16-bit skies in this cooperative shooter.', 'Play Strike Gunner S.T.G on the Super Nintendo.', 'Features a robust two-player mode where pilots can link their ships for combined firepower. Battle through diverse environments from high-tech bases to jungle landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('striker-europe-enfrdeesitnlsv', 'SNES', 'Striker (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1994', 'Sports', 'Rage Software', '2', 'Soccer Simulation', 'Fast-paced soccer simulation with Mode 7 effects.', 'Win the World Cup in this agile 16-bit sports sim.', 'Play the classic Striker on the Super Nintendo.', 'Known for its incredible speed and "3D" perspective. Features over 40 teams, indoor soccer modes, and highly responsive controls that emphasize quick passing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('striker-europe-enfrdeesitnlsv-beta', 'SNES', 'Striker (Europe) (En,Fr,De,Es,It,Nl,Sv) (Beta)', '1994', 'Sports', 'Rage Software', '2', 'Soccer Simulation', 'Fast-paced soccer simulation (Pre-release build).', 'Test the early ball physics and Mode 7 rotation.', 'Check out the Striker Beta on the Super Nintendo.', 'A rare 16-bit development look. Witness the fine-tuning of the camera angles and the initial implementation of the penalty shootout mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stunt-race-fx-europe', 'SNES', 'Stunt Race FX (Europe)', '1994', 'Racing', 'Nintendo', '2', '3D Arcade Racing', '3D polygonal racing game using the Super FX chip.', 'Win the 16-bit stunt grand prix in a world of polygons.', 'Experience Stunt Race FX on the Super Nintendo.', 'A technical marvel. Use the Super FX chip to race sentient, expressive vehicles across tracks filled with obstacles, jumps, and impressive 3D geometry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stunt-race-fx-usa', 'SNES', 'Stunt Race FX (USA)', '1994', 'Racing', 'Nintendo', '2', '3D Arcade Racing', '3D polygonal racing game featuring three vehicle types.', 'Master the physics of the F-Type, COUPE, and 4WD.', 'Play the revolutionary Stunt Race FX on SNES.', 'Includes a "Stunt Radio Control" mode and a challenging battle mode. One of the few 16-bit games to offer a fully 3D racing experience with real-time scaling and rotation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sufami-turbo-add-on-base-cassette-japan', 'SNES', 'Sufami Turbo Add-On Base Cassette (Japan)', '1996', 'Hardware', 'Nintendo', '1', 'Peripheral System', 'Hardware interface for Bandai''s mini-cartridge system.', 'The base unit required to play Sufami Turbo games.', 'Explore the Sufami Turbo Add-On for Super Famicom.', 'A unique 16-bit peripheral. This base cartridge allowed users to slot in two smaller games at once, enabling data sharing between specific Bandai titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sugoi-hebereke-japan', 'SNES', 'Sugoi Hebereke (Japan)', '1994', 'Action', 'Sunsoft', '4', 'Party Action', 'Competitive 2D arena fighter with Hebereke characters.', 'Defeat your rivals in this quirky "chibi" brawler.', 'Play Sugoi Hebereke on the Super Famicom.', 'A fast-paced 4-player fighting game. Features colorful sprites, environmental hazards, and the surreal humor the Sunsoft "Ufouria" series is known for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sugoro-quest++---dicenics-japan', 'SNES', 'Sugoro Quest++ - Dicenics (Japan)', '1993', 'RPG', 'Technos Japan', '2', 'Turn-Based RPG', 'RPG and board game hybrid featuring dice-based combat.', 'Defeat the Dark Lord using strategic dice rolls.', 'Explore Sugoro Quest++ Dicenics on SNES.', 'A charming 16-bit hybrid. Navigate a board-game world where encounters are resolved through a unique "Dicenics" system, blending luck with tactical RPG growth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sugoroku-ginga-senki-japan', 'SNES', 'Sugoroku Ginga Senki (Japan)', '1994', 'Board Game', 'Bottom Up', '2', 'Dice Board Game', 'Sci-fi strategy board game set in outer space.', 'Conquer the galaxy through strategic dice play and trade.', 'Play Sugoroku Ginga Senki on Super Famicom.', 'A deep 16-bit cosmic simulation. Manage a fleet of ships, colonize planets, and outmaneuver rival factions in a high-stakes board game for control of the universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sunset-riders-europe', 'SNES', 'Sunset Riders (Europe)', '1993', 'Action', 'Konami', '2', 'Run and Gun', 'Side-scrolling run-and-gun western action.', 'Hunt down the four outlaws and claim the bounties.', 'Experience Sunset Riders on the Super Nintendo.', 'A pixel-perfect 16-bit arcade port. Choose between Steve, Billy, Bob, or Cormano to blast through the Wild West, featuring iconic boss fights and bonus stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sunset-riders-usa', 'SNES', 'Sunset Riders (USA)', '1993', 'Action', 'Konami', '2', 'Run and Gun', 'Side-scrolling run-and-gun western (USA release).', 'Clean up the frontier in this legendary 16-bit shooter.', 'Play the classic Sunset Riders on the SNES.', 'Features simultaneous 2-player action and vibrant graphics. Ride horses, dodge stampedes, and take down the toughest outlaws in this Konami masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('supapoon-japan', 'SNES', 'Supapoon (Japan)', '1995', 'Puzzle', 'Thinking Rabbit', '2', 'Physics Puzzle', 'Gravity-based puzzle game with a cute protagonist.', 'Clear the boards by matching colored slimes.', 'Explore the colorful Supapoon on Super Famicom.', 'A unique 16-bit puzzler. Control a bouncing character to clear blocks while managing gravity and momentum in a series of increasingly difficult levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('supapoon-dx-japan', 'SNES', 'Supapoon DX (Japan)', '1996', 'Puzzle', 'Thinking Rabbit', '2', 'Physics Puzzle', 'Enhanced gravity-based puzzle sequel.', 'Master the new block types in this polished puzzle DX.', 'Experience Supapoon DX on the Super Famicom.', 'The refined 16-bit edition. Features improved graphics, more complex level designs, and a robust 2-player competitive mode to test your speed and logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world', 'SNES', 'Super "Mario" World', '1990', 'Platform', 'Nintendo', '2', 'Platformer', 'Bootleg/Unlicensed platformer starring "Mario".', 'Navigate the bizarre unlicensed world as a fake Mario.', 'Check out the bootleg Super Mario World on SNES.', 'A 16-bit curiosity. Actually a re-skinned version of other platformers, serving as a fascinating (and often glitchy) artifact of the pirate game era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-3d-baseball-japan', 'SNES', 'Super 3D Baseball (Japan)', '1996', 'Sports', 'Culture Brain', '2', 'Baseball Arcade', 'Realistic baseball simulation with digitized elements.', 'Win the professional league in this technical 16-bit sim.', 'Play Super 3D Baseball on the Super Famicom.', 'Uses Mode 7 and sprite scaling to create a "3D" perspective from the batter''s box. Features a heavy focus on realistic pitch physics and player statistics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-4wd---the-baja-japan', 'SNES', 'Super 4WD - The Baja (Japan)', '1992', 'Racing', 'Lenar', '2', 'Off-Road Racing', 'Off-road racing simulation based on the Baja 1000.', 'Conquer the desert terrain in your custom 4WD.', 'Experience Super 4WD: The Baja on SNES.', 'A technical 16-bit racer using Mode 7 for terrain simulation. Manage your vehicle''s damage and fuel while navigating through night stages and sand dunes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-adventure-island-europe', 'SNES', 'Super Adventure Island (Europe)', '1992', 'Platform', 'Hudson Soft', '2', 'Platformer', 'Side-scrolling platformer with tropical themes.', 'Rescue Princess Leilani from the evil Witch Doctor.', 'Play Super Adventure Island on the SNES.', 'A vibrant 16-bit debut for Master Higgins. Features a legendary hip-hop inspired soundtrack by Yuzo Koshiro and fast-paced, fruit-collecting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-adventure-island-usa', 'SNES', 'Super Adventure Island (USA)', '1992', 'Platform', 'Hudson Soft', '2', 'Platformer', 'Side-scrolling platformer featuring Master Higgins.', 'Survive the 16-bit hazards of the tropical islands.', 'Experience Super Adventure Island for the SNES.', 'Master the skateboard and stone axe mechanics. A colorful and challenging platformer that showcases high-quality sprite work and catchy melodies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-adventure-island-ii-europe', 'SNES', 'Super Adventure Island II (Europe)', '1994', 'Platform', 'Hudson Soft', '2', 'Platformer', 'Action-RPG and exploration platformer.', 'Search the islands to find your missing bride, Tina.', 'Play Super Adventure Island II on the SNES.', 'A massive departure for the series. Features a world map, equippable weapons, and Metroidvania-style exploration across diverse themed islands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-adventure-island-ii-usa', 'SNES', 'Super Adventure Island II (USA)', '1994', 'Platform', 'Hudson Soft', '2', 'Platformer', 'Action-RPG and exploration platformer (USA release).', 'Master the elemental swords in this 16-bit epic.', 'Experience Super Adventure Island II on the SNES.', 'Unlike the first game, this 16-bit entry focuses on puzzle-solving and character growth, offering a much deeper and more atmospheric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-air-diver-europe', 'SNES', 'Super Air Diver (Europe)', '1992', 'Shooter', 'Asmik', '2', 'Aerial Shooter', 'First-person flight combat simulator.', 'Complete high-stakes aerial missions as a fighter pilot.', 'Experience Super Air Diver on the Super Nintendo.', 'A technical 16-bit sim using Mode 7. Engaged in dogfights and bombing runs across a 3D-style landscape, managing fuel and missile lock-ons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-air-diver-japan', 'SNES', 'Super Air Diver (Japan)', '1992', 'Shooter', 'Asmik', '2', 'Aerial Shooter', 'First-person flight combat (Original Japanese release).', 'Master the F-15 Strike Eagle in the Japanese version.', 'Play Super Air Diver on the Super Famicom.', 'Known as Lock-On in some regions. Features a cockpit perspective and intense aerial combat missions that push the SNES hardware''s rotation capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-air-diver-2-japan', 'SNES', 'Super Air Diver 2 (Japan)', '1994', 'Shooter', 'Asmik', '2', 'Aerial Shooter', 'First-person flight combat sequel with improved graphics.', 'Command advanced jets in this 16-bit aerial follow-up.', 'Experience Super Air Diver 2 on Super Famicom.', 'Features more fluid frame rates and a wider variety of mission objectives. A refined 16-bit flight experience with more detailed cockpit and environment art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-aleste-europe', 'SNES', 'Super Aleste (Europe)', '1993', 'Shooter', 'Compile', '2', 'Vertical Shooter', 'Vertical-scrolling shoot ''em up (European release).', 'Stop the alien threat in this technical 16-bit shmup.', 'Experience the legendary Super Aleste on SNES.', 'A technical masterpiece by Compile. Features an incredible weapon system with eight upgrades and some of the most impressive sprite counts on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-aleste-japan', 'SNES', 'Super Aleste (Japan)', '1993', 'Shooter', 'Compile', '2', 'Vertical Shooter', 'Vertical-scrolling shoot ''em up (Original Japanese release).', 'Master the evolving arsenal of the Aleste fighter.', 'Play Super Aleste on the Super Famicom.', 'Commonly known as Space Megaforce in the US. This 16-bit shooter is famous for its fast pace, massive boss battles, and a pulse-pounding electronic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-alfred-chicken-usa', 'SNES', 'Super Alfred Chicken (USA)', '1993', 'Platform', 'Twilight', '2', 'Platformer', 'Side-scrolling platformer starring a heroic chicken.', 'Rescue your eggs and defeat the Meka-Chicken.', 'Play the quirky Super Alfred Chicken on the SNES.', 'A vibrant 16-bit platformer. Guide Alfred through surreal worlds, using his peck attack and dives to defeat enemies and solve environmental puzzles to save his unhatched family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-aoki-ookami-to-shiroki-mejika---genchou-hishi-japan', 'SNES', 'Super Aoki Ookami to Shiroki Mejika - Genchou Hishi (Japan)', '1993', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy simulation set in the Mongol Empire.', 'Unify the world as Genghis Khan through conquest.', 'Master Genchou Hishi on the Super Famicom.', 'A deep 16-bit historical sim from Koei. Manage resources, forge alliances, and lead massive armies across Eurasia to build the greatest empire in history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-aquatic-games-the-usa', 'SNES', 'Super Aquatic Games, The (USA)', '1992', 'Sports', 'Hudson Soft', '4', 'Multi-Sport', 'Olympic-style sports simulation featuring aquatic animals.', 'Win the gold medal in various wacky water sports.', 'Play The Super Aquatic Games on the SNES.', 'A fun 16-bit sports title starring James Pond. Compete in events like the 100m Splash and Hop, Skip, and Jump, featuring colorful graphics and 2-player competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-aquatic-games-the-usa-beta', 'SNES', 'Super Aquatic Games, The (USA) (Beta)', '1992', 'Sports', 'Hudson Soft', '4', 'Multi-Sport', 'Aquatic sports simulation (Pre-release build).', 'Test the early event physics and character animations.', 'Check out the Super Aquatic Games Beta on SNES.', 'A rare 16-bit development look. Witness the initial implementation of the button-mashing mechanics and the tuning of the AI difficulty for the aquatic events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bc-kid-europe', 'SNES', 'Super B.C. Kid (Europe)', '1994', 'Platform', 'Hudson Soft', '2', 'Platformer', 'Side-scrolling platformer featuring a prehistoric hero.', 'Defeat the King Drool and save the dinosaur kingdom.', 'Experience Super B.C. Kid on the SNES.', 'Known as Super Bonk in the US. A creative 16-bit platformer where you use your head to smash enemies, eat meat to transform, and navigate bizarre prehistoric levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-back-to-the-future-part-ii-japan', 'SNES', 'Super Back to the Future Part II (Japan)', '1993', 'Action', 'Daft', '1', 'Action Platformer', 'Side-scrolling action-platformer with hoverboard mechanics.', 'Travel to 2015 and stop Griff Tannen''s gang.', 'Play Super Back to the Future Part II on SNES.', 'A Japan-exclusive gem. Control Marty McFly on his hoverboard through beautifully detailed 16-bit levels based on the movie, featuring fluid movement and Mode 7 sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-baken-ou-95-japan', 'SNES', 'Super Baken Ou ''95 (Japan)', '1995', 'Sports', 'Sunsoft', '2', 'Baseball Simulation', 'Horse racing and betting simulation.', 'Win a fortune on the 1995 professional racing circuit.', 'Experience Super Baken Ou ''95 on Super Famicom.', 'A detailed 16-bit gambling sim. Analyze real-world horse statistics, monitor track conditions, and place strategic bets to become the ultimate track mogul.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-baseball-simulator-1000-usa', 'SNES', 'Super Baseball Simulator 1.000 (USA)', '1989', 'Sports', 'Culture Brain', '2', 'Baseball Simulation', 'Arcade-style baseball with super-powered abilities.', 'Win the season using specialized "Ultra" plays.', 'Play Super Baseball Simulator 1.000 on SNES.', 'A unique 16-bit sports game. Customize your team with super-powered pitches and hits that defy physics, adding a strategic and chaotic layer to traditional baseball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bases-loaded-usa', 'SNES', 'Super Bases Loaded (USA)', '1991', 'Sports', 'Jaleco', '2', 'Baseball Simulation', 'Realistic baseball simulation with detailed animation.', 'Lead your team to the World Series championship.', 'Experience Super Bases Loaded on the SNES.', 'The 16-bit debut of the Jaleco series. Features a smooth telephoto-style perspective and realistic player movements, emphasizing a professional broadcast feel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bases-loaded-3---license-to-steal-usa', 'SNES', 'Super Bases Loaded 3 - License to Steal (USA)', '1994', 'Sports', 'Jaleco', '2', 'Baseball Simulation', 'Baseball simulation with expanded management features.', 'Steal the win and master the professional league.', 'Play Super Bases Loaded 3 on the SNES.', 'The final 16-bit entry in the series. Features refined controls, updated rosters, and an emphasis on "License to Steal" mechanics for aggressive base running.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bases-loaded-ii-usa', 'SNES', 'Super Bases Loaded II (USA)', '1992', 'Sports', 'Jaleco', '2', 'Baseball Simulation', 'Enhanced baseball simulation with updated graphics.', 'Climb the rankings in this polished 16-bit sports sim.', 'Experience Super Bases Loaded II on the SNES.', 'Features improved field perspective and more fluid player transitions. A solid 16-bit baseball title that balances arcade fun with deep statistical tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-batter-up-usa', 'SNES', 'Super Batter Up (USA)', '1991', 'Sports', 'Namco', '2', 'Baseball Arcade', 'Traditional arcade-style baseball simulation.', 'Hit home runs and win the championship league.', 'Play Super Batter Up on the Super Nintendo.', 'A fast-paced 16-bit baseball title from Namco. Features a clean, accessible interface and responsive batting mechanics, making it perfect for quick competitive matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battleship-europe', 'SNES', 'Super Battleship (Europe)', '1994', 'Strategy', 'Mindscape', '2', 'Naval Strategy', 'Tactical naval combat and strategy simulation.', 'Sink the enemy fleet using high-tech weaponry.', 'Experience Super Battleship on the Super Nintendo.', 'A 16-bit strategy title based on the board game. Includes both a traditional mode and a cinematic mission mode featuring real-time ship movement and torpedo combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battleship-usa', 'SNES', 'Super Battleship (USA)', '1994', 'Strategy', 'Mindscape', '2', 'Naval Strategy', 'Tactical naval combat (USA release).', 'Command a modern naval fleet in this 16-bit sim.', 'Play the strategic Super Battleship on the SNES.', 'Manage your radar, weapon systems, and ship damage while engaging enemy destroyers and submarines in high-stakes ocean warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank---war-in-the-gulf-usa', 'SNES', 'Super Battletank - War in the Gulf (USA)', '1993', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'First-person tank combat simulation (Gulf War theme).', 'Complete desert missions in the M1 Abrams tank.', 'Play Super Battletank on the Super Nintendo.', 'A technical 16-bit sim. Use the tank''s sights to engage targets, manage fuel and ammo, and navigate the desert using a map and compass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank---war-in-the-gulf-usa-rev-a', 'SNES', 'Super Battletank - War in the Gulf (USA) (Rev A)', '1993', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'First-person tank combat (Updated Revision).', 'Experience the refined tank combat in this version.', 'Play Super Battletank (Rev A) on the SNES.', 'An updated 16-bit revision that improves frame rates during intense combat and optimizes the cockpit UI for better visibility.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank-europe', 'SNES', 'Super Battletank (Europe)', '1992', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'First-person tank combat (European release).', 'Command the armored division in the 16-bit Gulf War.', 'Experience Super Battletank on the SNES.', 'The PAL release of the tank sim. Offers a realistic cockpit perspective and challenging missions where positioning and long-range accuracy are key to survival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank-japan', 'SNES', 'Super Battletank (Japan)', '1992', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'First-person tank combat (Japanese release).', 'Master the M1 Abrams in the official Japanese version.', 'Play Super Battletank on the Super Famicom.', 'Features a dedicated mission structure and technical manuals translated for the Japanese market. A gritty 16-bit simulation of modern armored warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank-2-europe', 'SNES', 'Super Battletank 2 (Europe)', '1994', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'Advanced first-person tank combat sequel.', 'Return to the front lines with improved 16-bit tech.', 'Experience Super Battletank 2 on the SNES.', 'Significantly improves on the original with faster scaling, more diverse mission types, and the ability to call in air strikes and use secondary weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank-2-japan', 'SNES', 'Super Battletank 2 (Japan)', '1994', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'Advanced tank combat (Japanese release).', 'Command the heavy armor in the Japanese sequel.', 'Play Super Battletank 2 on the Super Famicom.', 'Features high-quality 16-bit digitized graphics and an improved engine that makes the first-person tank movement feel more fluid and responsive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank-2-spain', 'SNES', 'Super Battletank 2 (Spain)', '1994', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'Advanced tank combat (Spanish localization).', 'Lidera el combate de tanques en español.', 'Juega a Super Battletank 2 en español para SNES.', 'A rare 16-bit localization. Features full Spanish text for mission briefings and cockpit controls, allowing Spanish-speaking players to fully master the simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank-2-usa', 'SNES', 'Super Battletank 2 (USA)', '1994', 'Simulation', 'Mindscape', '1', 'Tank Combat', 'Advanced tank combat with night-vision missions.', 'Survive the 16-bit battlefield with modern armor.', 'Play the intense Super Battletank 2 on the SNES.', 'Includes challenging night-vision stages and more interactive environments. The definitive 16-bit tank experience for military enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bikkuriman-japan', 'SNES', 'Super Bikkuriman (Japan)', '1993', 'RPG', 'BEC', '1', 'Action RPG', 'Action-platformer based on the anime series.', 'Defeat the dark forces as a powerful Bikkuriman hero.', 'Play Super Bikkuriman on the Super Famicom.', 'A fast-paced 16-bit action game. Transform into different armored forms, each with unique abilities, to battle through colorful stages based on the popular franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-billiard-championship-pool-japan', 'SNES', 'Super Billiard Championship Pool (Japan)', '1993', 'Sports', 'Namco', '2', 'Billiards', 'Professional billiards and pool simulation.', 'Clear the table and win the 16-bit tournament.', 'Experience Super Billiard Championship on SNES.', 'A polished 16-bit pool sim. Features realistic ball physics, multiple game modes like 9-ball and rotation, and a challenging AI tournament mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-birdie-rush-japan', 'SNES', 'Super Birdie Rush (Japan)', '1994', 'Sports', 'Jaleco', '1', 'Golf', 'Traditional golf simulation with a focus on speed.', 'Master the 16-bit fairways and earn the birdie.', 'Play Super Birdie Rush on the Super Famicom.', 'A vibrant and accessible 16-bit golf title. Features intuitive swing mechanics and beautiful course designs that emphasize fun over complex simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-bass-japan', 'SNES', 'Super Black Bass (Japan)', '1992', 'Sports', 'Starfish', '1', 'Fishing', 'The original Japanese bass fishing simulation.', 'Catch the legendary black bass in Japanese lakes.', 'Play Super Black Bass on the Super Famicom.', 'The game that started the 16-bit fishing craze. Features a dual-perspective view: top-down for lure placement and underwater for the actual struggle with the fish.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-bass-usa', 'SNES', 'Super Black Bass (USA)', '1992', 'Sports', 'Starfish', '1', 'Fishing', 'Realistic bass fishing simulation (USA release).', 'Win the bass tournament circuit in this 16-bit sim.', 'Experience Super Black Bass on the Super Nintendo.', 'Features realistic weather effects and lure physics. Master the "fighting" mechanic to reel in massive fish without snapping your line.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-bass-2-japan', 'SNES', 'Super Black Bass 2 (Japan)', '1993', 'Sports', 'Starfish', '1', 'Fishing', 'Enhanced bass fishing simulation sequel.', 'Master the new lures and lakes in this 16-bit sequel.', 'Experience Super Black Bass 2 on Super Famicom.', 'Features improved graphics and more responsive fish AI. Includes a wider variety of equipment and a deeper career mode for aspiring 16-bit anglers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-bass-3-japan', 'SNES', 'Super Black Bass 3 (Japan)', '1994', 'Sports', 'Starfish', '1', 'Fishing', 'The most advanced 16-bit bass fishing simulation.', 'Conquer the professional world tour in the final entry.', 'Play Super Black Bass 3 on the Super Famicom.', 'A technical marvel for a fishing game. Features incredible underwater animations, a massive selection of tackle, and highly realistic environmental conditions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-bass-3-japan-rev-a', 'SNES', 'Super Black Bass 3 (Japan) (Rev A)', '1994', 'Sports', 'Starfish', '1', 'Fishing', 'Advanced bass fishing (Updated Revision).', 'Experience the refined fishing simulation in Rev A.', 'Play Super Black Bass 3 (Rev A) on Super Famicom.', 'The final 16-bit retail revision. Optimizes the fish behavior algorithms and fixes minor graphical glitches during the lure-retrieval sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-blueyoshi-kart-11', 'SNES', 'Super BlueYoshi Kart 1.1', '2019', 'Racing', 'Fanmade', '4', 'Arcade Kart', 'Fan-made Mario Kart modification featuring Blue Yoshi.', 'Race as Blue Yoshi in this custom 16-bit overhaul.', 'Try Super BlueYoshi Kart on the SNES.', 'A creative 16-bit romhack of Super Mario Kart. Replaces characters and adds custom track palettes for a fresh take on the racing classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-blueyoshi-kart-expert-11', 'SNES', 'Super BlueYoshi Kart EXPERT 1.1', '2019', 'Racing', 'Fanmade', '4', 'Arcade Kart', 'Fan-made Mario Kart (Expert Edition Hack).', 'Test your skills on brutal custom 16-bit tracks.', 'Play BlueYoshi Kart EXPERT on the SNES.', 'A high-difficulty modification of Super Mario Kart. Features redesigned tracks with extreme hazards and tighter turns for veterans seeking a new challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman---panic-bomber-w-japan', 'SNES', 'Super Bomberman - Panic Bomber W (Japan)', '1992', 'Puzzle', 'Hudson Soft', '2', 'Action Puzzle', 'Falling-block puzzle game with a Bomberman theme.', 'Match three heads of the same color to clear the board.', 'Experience Super Bomberman: Panic Bomber W on SNES.', 'A unique 16-bit puzzle spin-off. Combine classic falling-block mechanics with the explosive power of Bomberman''s bombs to trigger chain reactions and defeat your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-europe', 'SNES', 'Super Bomberman (Europe)', '1993', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down maze-based action and combat.', 'Defeat enemies and boss monsters using timed explosions.', 'Play the legendary Super Bomberman on the SNES.', 'The first 16-bit entry to feature the famous 4-player Multitap mode. Blast your way through a cooperative campaign or destroy your friends in the iconic battle mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-japan', 'SNES', 'Super Bomberman (Japan)', '1993', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down action and multiplayer combat (Original release).', 'Become the ultimate bomber in the Japanese original.', 'Experience Super Bomberman on the Super Famicom.', 'The game that redefined local multiplayer. Master the art of trap-setting and power-up collection in this foundational 16-bit action masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-usa', 'SNES', 'Super Bomberman (USA)', '1993', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down maze-based action (USA release).', 'Stop the Diamond Blue forces in this 16-bit classic.', 'Play Super Bomberman for the Super Nintendo.', 'Features a full single-player adventure and the definitive competitive battle mode. Use kick and throw power-ups to dominate the 16-bit arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-2---caravan-event-ban-japan', 'SNES', 'Super Bomberman 2 - Caravan Event Ban (Japan)', '1994', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down action (Limited Caravan Event Version).', 'Achieve the highest score in the timed Caravan challenge.', 'Check out Super Bomberman 2 (Caravan Ban) on SNES.', 'A rare 16-bit promotional edition. Features a specialized "Score Attack" mode used in 1994 Japanese gaming tournaments, focusing on quick clears and point efficiency.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-2-europe', 'SNES', 'Super Bomberman 2 (Europe)', '1994', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down action and puzzle-solving sequel.', 'Defeat the Five Dastardly Bombers to save Earth.', 'Play Super Bomberman 2 on the Super Nintendo.', 'Widely considered the best battle mode in the series. Features unique level hazards, improved AI, and a much more cinematic and varied single-player campaign.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-2-japan', 'SNES', 'Super Bomberman 2 (Japan)', '1994', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down action sequel (Original Japanese release).', 'Master the new bomb types in this 16-bit sequel.', 'Experience Super Bomberman 2 on the Super Famicom.', 'Introduces the ability to pick up and throw bombs. A 16-bit classic that perfected the balance between competitive strategy and chaotic fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-2-usa', 'SNES', 'Super Bomberman 2 (USA)', '1994', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down action sequel (USA release).', 'Blast your way through the space stations of the Five Bombers.', 'Play Super Bomberman 2 for the Super Nintendo.', 'Navigate through five massive worlds with unique boss encounters. The 16-bit battle mode features more stages and custom rules than ever before.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-3-europe', 'SNES', 'Super Bomberman 3 (Europe)', '1995', 'Action', 'Hudson Soft', '5', 'Bomber Action', 'Top-down action with riding mounts (Louies).', 'Travel the world and stop the return of Bagular.', 'Experience Super Bomberman 3 on the SNES.', 'The first 16-bit entry to support 5 players simultaneously. Introduces "Louies," kangaroo-like creatures that provide special abilities and an extra life during combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-3-japan', 'SNES', 'Super Bomberman 3 (Japan)', '1995', 'Action', 'Hudson Soft', '5', 'Bomber Action', 'Top-down action with riding mounts (Japanese release).', 'Master the Louie mounts in the original Japanese version.', 'Play Super Bomberman 3 on the Super Famicom.', 'Expanded 16-bit multiplayer fun. Includes a diverse cast of international Bomberman characters and a colorful, globe-trotting single-player adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-3-japan-beta', 'SNES', 'Super Bomberman 3 (Japan) (Beta)', '1995', 'Action', 'Hudson Soft', '5', 'Bomber Action', 'Top-down action (Pre-release build).', 'Test the early Louie physics and stage interactions.', 'Check out the Super Bomberman 3 Beta on SNES.', 'A rare 16-bit development look. Witness the initial implementation of the mount system and the early layout of the world map before final balancing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-4-english---translated', 'SNES', 'Super Bomberman 4 (English - Translated)', '1996', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down action featuring mount transformations (English).', 'Ride dinosaurs and stop the galaxy threat in English.', 'Play Super Bomberman 4 in English on the SNES.', 'A fan-translated 16-bit masterpiece. Introduces the "Creature" system where defeated enemies become mounts, and features an expansive roster of playable Bombers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-4-japan', 'SNES', 'Super Bomberman 4 (Japan)', '1996', 'Action', 'Hudson Soft', '4', 'Bomber Action', 'Top-down action with creature mounts (Original release).', 'Explore time and space in this massive 16-bit sequel.', 'Play Super Bomberman 4 on the Super Famicom.', 'One of the most creative entries in the series. Includes a revenge system where defeated players can toss bombs from the sidelines, keeping the action intense.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-5---caravan-event-ban-japan', 'SNES', 'Super Bomberman 5 - Caravan Event Ban (Japan)', '1997', 'Action', 'Hudson Soft', '5', 'Bomber Action', 'Top-down action (Final Caravan Event Version).', 'Master the timed challenge in the final Caravan edition.', 'Check out Super Bomberman 5 (Caravan Ban) on SNES.', 'A rare promotional 16-bit variant. Designed for high-score competitions, featuring specific level layouts that reward speed and tactical bombing patterns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-5-english---translated', 'SNES', 'Super Bomberman 5 (English - Translated)', '1997', 'Action', 'Hudson Soft', '5', 'Bomber Action', 'Top-down action with non-linear progression (English).', 'Complete the final 16-bit saga with full English text.', 'Play Super Bomberman 5 in English on the SNES.', 'The ultimate fan-translated 16-bit experience. Features a non-linear map with multiple endings and the most polished battle mode in the entire SNES library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bomberman-5-japan', 'SNES', 'Super Bomberman 5 (Japan)', '1997', 'Action', 'Hudson Soft', '5', 'Bomber Action', 'Top-down action with non-linear progression (Original).', 'Achieve 100% completion in the final SNES Bomberman.', 'Experience Super Bomberman 5 on the Super Famicom.', 'A love letter to the series. Includes maps and bosses based on previous games, offering hundreds of paths and the most refined 16-bit explosive gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bombliss-japan', 'SNES', 'Super Bombliss (Japan)', '1995', 'Puzzle', 'Hudson Soft', '2', 'Block Puzzle', 'Falling-block puzzle game with Tetris mechanics.', 'Clear the board using explosive Bombliss pieces.', 'Play Super Bombliss on the Super Famicom.', 'A technical 16-bit puzzle game. Combine traditional Tetris-style block clearing with bombs that destroy surrounding tiles, adding a strategic layer to the classic formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bonk-usa', 'SNES', 'Super Bonk (USA)', '1994', 'Platformer', 'Hudson Soft', '2', 'Cartoon Platformer', 'Side-scrolling platformer with a giant baby hero.', 'Save the prehistoric world by head-butting your enemies.', 'Experience Super Bonk for the Super Nintendo.', 'A surreal 16-bit platformer. Grow huge or shrink tiny by eating different meats. Features massive boss fights and incredibly creative, often bizarre, level designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-boss-collection', 'SNES', 'Super Boss Collection', '1994', 'Compilation', 'Various', '1', 'Game Collection', 'Collection of classic arcade and boss rush modes.', 'Challenge the toughest 16-bit bosses in one collection.', 'Play Super Boss Collection on the Super Famicom.', 'A unique 16-bit utility/game that allows players to jump directly into intense boss encounters from various popular titles, testing their combat skills to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bowling-japan', 'SNES', 'Super Bowling (Japan)', '1992', 'Sports', 'Namco', '4', 'Bowling', 'Realistic bowling simulation with diverse characters.', 'Achieve the perfect 300 score in this 16-bit sim.', 'Play Super Bowling on the Super Famicom.', 'Features smooth animations and precise control over spin and power. A relaxing yet technical 16-bit sports title that captures the feel of a real bowling alley.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bowling-usa', 'SNES', 'Super Bowling (USA)', '1992', 'Sports', 'Namco', '4', 'Bowling', 'Realistic bowling simulation (USA release).', 'Win the professional bowling tournament in 16-bit.', 'Experience Super Bowling for the Super Nintendo.', 'Master the lane conditions and pick the right ball. Includes a fun "Golf" mode where bowling pins are placed in golf-like layouts for a unique challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-buster-bros-usa', 'SNES', 'Super Buster Bros. (USA)', '1990', 'Action', 'Data East', '2', 'Arcade Action', 'Balloon-popping puzzle action (Pang).', 'Clear the screen of bouncing bubbles across the world.', 'Play the addictive Super Buster Bros. on the SNES.', 'A pixel-perfect arcade port. Use your harpoon to split larger bubbles into smaller ones until they disappear. Features a tense "Panic Mode" and a globe-trotting Tour.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-buster-bros-usa-beta', 'SNES', 'Super Buster Bros. (USA) (Beta)', '1990', 'Action', 'Data East', '2', 'Arcade Action', 'Balloon-popping action (Pre-release build).', 'Test the early bubble splitting physics and harpoon speed.', 'Check out the Super Buster Bros. Beta on the SNES.', 'A rare 16-bit development slice. Shows the evolution of the level backgrounds and the initial implementation of the various power-up items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-buster-bros-usa-rev-a', 'SNES', 'Super Buster Bros. (USA) (Rev A)', '1990', 'Action', 'Data East', '2', 'Arcade Action', 'Balloon-popping action (Updated Revision).', 'Experience the refined bubble-popping in Rev A.', 'Play Super Buster Bros. (Rev A) on the SNES.', 'The updated 16-bit retail version. Fixes minor slowdown issues during intense stages and optimizes the sprite flickering during crowded bubble sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-caesars-palace-usa', 'SNES', 'Super Caesars Palace (USA)', '1993', 'Casino', 'Illusion Softworks', '1', 'Gambling', 'Casino simulation featuring a variety of games.', 'Turn your starting stake into a fortune at Caesars Palace.', 'Experience Super Caesars Palace on the SNES.', 'Includes Blackjack, Roulette, Slots, and Poker. A detailed 16-bit gambling sim that captures the atmosphere and variety of a high-stakes Las Vegas casino.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-caesars-palace-usa-beta', 'SNES', 'Super Caesars Palace (USA) (Beta)', '1993', 'Casino', 'Illusion Softworks', '1', 'Gambling', 'Casino simulation (Pre-release build).', 'Test the early odds-calculators and mini-game UI.', 'Check out the Super Caesars Palace Beta on the SNES.', 'A rare 16-bit development look. Witness the initial implementation of the NPC interactions and the testing of the various slot machine RNG algorithms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-casino---caesars-palace-japan', 'SNES', 'Super Casino - Caesars Palace (Japan)', '1992', 'Casino', 'Illusion Softworks', '1', 'Gambling', 'Casino simulation (Japanese release).', 'Experience the Las Vegas thrill in the Japanese version.', 'Play Super Casino: Caesars Palace on Super Famicom.', 'The official 16-bit Japanese edition. Features localized menus and instructions, allowing Japanese players to master the rules of international casino gambling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-casino---caesars-palace-japan-rev-a', 'SNES', 'Super Casino - Caesars Palace (Japan) (Rev A)', '1992', 'Casino', 'Illusion Softworks', '1', 'Gambling', 'Casino simulation (Japanese Revision).', 'Master the casino floor in this updated 16-bit sim.', 'Play Super Casino (Rev A) on the Super Famicom.', 'The refined 16-bit Japanese version. Includes minor bug fixes for the save system and optimizes the loading times between the various gambling rooms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-casino-2-japan', 'SNES', 'Super Casino 2 (Japan)', '1994', 'Casino', 'Illusion Softworks', '1', 'Gambling', 'Casino simulation sequel with expanded games.', 'Win big in the sequel to the premier 16-bit casino.', 'Experience Super Casino 2 on the Super Famicom.', 'Features a wider variety of games and improved graphics. Navigate through a luxury resort and try your luck at the most advanced gambling sim on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-castles-japan', 'SNES', 'Super Castles (Japan)', '1991', 'Strategy', 'Vic Tokai', '1', 'Turn-Based Strategy', 'Strategy and construction game set in the Middle Ages.', 'Build and defend your fortress from invading armies.', 'Play the strategic Super Castles on Super Famicom.', 'A unique 16-bit hybrid. Combine city-building elements with real-time tactical defense, managing resources to ensure your castle survives the siege.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-castlevania-iv-europe', 'SNES', 'Super Castlevania IV (Europe)', '1991', 'Action', 'Konami', '1', 'Action Platformer', 'Cinematic side-scrolling action-platformer.', 'Defeat Count Dracula in the ultimate 16-bit quest.', 'Experience Super Castlevania IV on the SNES.', 'A masterpiece of atmosphere and music. Features the multidirectional whip, impressive Mode 7 effects, and some of the best 16-bit level designs in gaming history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-castlevania-iv-usa', 'SNES', 'Super Castlevania IV (USA)', '1991', 'Action', 'Konami', '1', 'Action Platformer', 'Cinematic side-scrolling action-platformer (USA).', 'Master the whip and survive the halls of Castlevania.', 'Play the legendary Super Castlevania IV on the SNES.', 'Considered one of the finest games on the system. Control Simon Belmont through 11 haunted stages with a hauntingly beautiful soundtrack and perfect controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-castlevania-iv-uncensored', 'SNES', 'Super Castlevania IV Uncensored', '1991', 'Action', 'Konami', '1', 'Action Platformer', 'Cinematic action-platformer (Uncensored Hack).', 'Experience the original gothic vision without censorship.', 'Play Super Castlevania IV Uncensored on the SNES.', 'A 16-bit fan restoration. Reinstates the blood effects, religious symbols, and original boss sprites that were removed or altered for the Western release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chase-hq-europe', 'SNES', 'Super Chase H.Q. (Europe)', '1992', 'Racing', 'Taito', '2', 'Arcade Racing', 'High-speed racing and vehicle combat.', 'Chase down and ram criminal vehicles to make an arrest.', 'Play Super Chase H.Q. on the Super Nintendo.', 'A fast-paced 16-bit arcade port. Use nitro boosts to catch up to dangerous fugitives within the time limit and ram their cars until they are forced to pull over.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chase-hq-usa', 'SNES', 'Super Chase H.Q. (USA)', '1992', 'Racing', 'Taito', '2', 'Arcade Racing', 'High-speed racing and vehicle combat (USA release).', 'Master the 16-bit pursuit in the official USA version.', 'Experience Super Chase H.Q. for the SNES.', 'Features a behind-the-car perspective with smooth scaling. Race through city streets and highways to take down high-priority targets in this intense Taito classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-fighter-japan', 'SNES', 'Super Chinese Fighter (Japan)', '1995', 'Fighting', 'Culture Brain', '2', 'Arcade Fighter', '2D arena fighting game with RPG characters.', 'Win the martial arts tournament with the Super Chinese cast.', 'Play Super Chinese Fighter on Super Famicom.', 'A colorful 16-bit fighter. Choose from the heroes and villains of the Super Chinese RPG series, featuring specialized special moves and fast-paced combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-world-japan', 'SNES', 'Super Chinese World (Japan)', '1992', 'Action RPG', 'Culture Brain', '2', 'Top-Down Action', 'Action-RPG with side-scrolling combat.', 'Save Chinaland from the invaders in this hybrid RPG.', 'Explore Super Chinese World on the Super Famicom.', 'Known as Super Ninja Boy in the West. Combines top-down world exploration and turn-based menus with real-time side-scrolling battles and platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-world-2---uchuu-ichibu-toudaikai-japan', 'SNES', 'Super Chinese World 2 - Uchuu Ichibu Toudaikai (Japan)', '1993', 'Action RPG', 'Culture Brain', '2', 'Top-Down Action', 'Action-RPG sequel with intergalactic themes.', 'Travel to space and win the ultimate fighting tournament.', 'Play Super Chinese World 2 on Super Famicom.', 'An expanded 16-bit sequel. Features improved combat mechanics, more diverse planetary environments, and the ability to switch between different fighting styles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-world-2---uchuu-ichibu-toudaikai-japan-sample', 'SNES', 'Super Chinese World 2 - Uchuu Ichibu Toudaikai (Japan) (Sample)', '1993', 'Action RPG', 'Culture Brain', '2', 'Top-Down Action', 'Action-RPG sequel (Sample/Demo Version).', 'Test the early combat flow and space exploration.', 'Check out the Super Chinese World 2 Sample on SNES.', 'A rare 16-bit development look. Offers a limited playthrough of the initial stages to showcase the improved graphics and new space-travel mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-world-3-japan', 'SNES', 'Super Chinese World 3 (Japan)', '1995', 'Action RPG', 'Culture Brain', '2', 'Top-Down Action', 'The final entry in the action-RPG trilogy.', 'Restore peace to the galaxy in this massive 16-bit finale.', 'Experience Super Chinese World 3 on Super Famicom.', 'The most refined entry in the series. Features a more traditional RPG structure with high-quality sprite work and complex boss battles across multiple worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-conflict---the-mideast-europe', 'SNES', 'Super Conflict - The Mideast (Europe)', '1991', 'Strategy', 'Jaleco', '2', 'Turn-Based Strategy', 'Hex-based tactical military simulation.', 'Win the modern Middle East conflict through strategy.', 'Play Super Conflict on the Super Nintendo.', 'A deep 16-bit wargame. Command a variety of units including tanks, helicopters, and infantry across desert terrains, focusing on supply lines and tactical positioning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-conflict---the-mideast-usa', 'SNES', 'Super Conflict - The Mideast (USA)', '1991', 'Strategy', 'Jaleco', '2', 'Turn-Based Strategy', 'Hex-based tactical military simulation (USA release).', 'Outmaneuver the enemy in this 16-bit strategic sim.', 'Experience Super Conflict: The Mideast on SNES.', 'Features a campaign mode with escalating difficulty. Manage your resources and unit deployments in turn-based combat to secure victory in the desert.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-copa-brazil-espt', 'SNES', 'Super Copa (Brazil) (Es,Pt)', '1992', 'Sports', 'U.S. Gold', '2', 'Soccer', 'Soccer simulation localized for the South American market.', 'Win the championship in this 16-bit soccer classic.', 'Play Super Copa in Spanish and Portuguese on SNES.', 'A specialized version of Tony Meola''s Sidekicks. Features localized teams and text, offering a fast-paced 16-bit soccer experience with Mode 7 field effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-cup-soccer-japan', 'SNES', 'Super Cup Soccer (Japan)', '1992', 'Sports', 'Namco', '2', 'Soccer', 'Fast-paced soccer simulation (Japanese release).', 'Master the 16-bit pitch in this polished soccer title.', 'Experience Super Cup Soccer on the Super Famicom.', 'Features smooth animations and intuitive controls. Includes various modes such as exhibition, league, and tournament play with a focus on arcade-style fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-daikoukai-jidai-japan', 'SNES', 'Super Daikoukai Jidai (Japan)', '1993', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Naval exploration and trading simulation (Koei).', 'Explore the high seas and build a global trade empire.', 'Play Super Daikoukai Jidai on Super Famicom.', 'Known as Uncharted Waters. A deep 16-bit historical sim. Navigate the globe, trade commodities, and engage in naval combat during the Age of Discovery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dany-france', 'SNES', 'Super Dany (France)', '1994', 'Platformer', 'Cryo Interactive', '1', 'European Platformer', 'Side-scrolling platformer based on the French character.', 'Navigate the 16-bit levels and find the hidden secrets.', 'Experience Super Dany on the Super Famicom.', 'A colorful platformer exclusive to the French market (and Japan). Use various abilities to overcome obstacles and enemies in a whimsical, cartoonish world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dany-france-beta', 'SNES', 'Super Dany (France) (Beta)', '1994', 'Platformer', 'Cryo Interactive', '1', 'European Platformer', 'Side-scrolling platformer (French Beta).', 'Test the early platforming physics and enemy AI.', 'Check out the Super Dany Beta on the SNES.', 'A rare 16-bit development slice. Witness the initial implementation of the character''s movement and the early layout of the French-themed stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dogfight-japan', 'SNES', 'Super Dogfight (Japan)', '1993', 'Simulation', 'Namco', '2', 'Flight Combat', 'Realistic flight combat simulation.', 'Master the dogfight in this technical 16-bit flight sim.', 'Play Super Dogfight on the Super Famicom.', 'Features a cockpit perspective and realistic flight physics. Engaged in intense 1-on-1 aerial duels and complex missions using Mode 7 for 3D-style navigation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey', 'SNES', 'Super Donkey', '1994', 'Platformer', 'Unlicensed', '1', 'Simple Platformer', 'Early development build or hack of Donkey Kong Country.', 'Explore the prototype physics of the Kongs.', 'Check out the Super Donkey build on the SNES.', 'A fascinating 16-bit historical artifact. Shows early asset testing or modifications related to the pre-rendered platforming style of the Donkey Kong series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-japan', 'SNES', 'Super Donkey Kong (Japan)', '1994', 'Platformer', 'Rare', '2', 'Platformer', 'Groundbreaking pre-rendered side-scrolling platformer.', 'Recover the banana hoard from King K. Rool.', 'Play the legendary Super Donkey Kong on the SNES.', 'The Japanese release of Donkey Kong Country. Revolutionized 16-bit graphics with pre-rendered 3D sprites, featuring perfect controls and an iconic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-japan-rev-a', 'SNES', 'Super Donkey Kong (Japan) (Rev A)', '1994', 'Platformer', 'Rare', '2', 'Platformer', 'Pre-rendered platformer (Updated Revision).', 'Experience the most stable 16-bit Kong adventure.', 'Play Super Donkey Kong (Rev A) on Super Famicom.', 'The refined 16-bit Japanese version. Fixes minor graphical glitches and optimizes loading times for the bonus rooms and transitional cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-2---dixie-&-diddy-japan', 'SNES', 'Super Donkey Kong 2 - Dixie & Diddy (Japan)', '1995', 'Platformer', 'Rare', '2', 'Platformer', 'Pre-rendered platformer sequel starring Dixie and Diddy.', 'Rescue Donkey Kong from the clutches of the Kremlings.', 'Play Super Donkey Kong 2 on the Super Famicom.', 'The Japanese release of Diddy''s Kong Quest. Widely considered one of the best 16-bit platformers ever made, featuring complex level design and incredible music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-2---dixie-&-diddy-japan-rev-a', 'SNES', 'Super Donkey Kong 2 - Dixie & Diddy (Japan) (Rev A)', '1995', 'Platformer', 'Rare', '2', 'Platformer', 'Pre-rendered platformer sequel (Updated Revision).', 'Master the 16-bit pirate world in this refined version.', 'Play Super Donkey Kong 2 (Rev A) on SNES.', 'The updated 16-bit retail version in Japan. Fixes specific sound bugs and optimizes the performance during the dense swamp and bramble levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-3---nazo-no-krems-tou-japan', 'SNES', 'Super Donkey Kong 3 - Nazo no Krems-tou (Japan)', '1996', 'Platformer', 'Rare', '2', 'Platformer', 'The final entry in the 16-bit Kong trilogy.', 'Explore the Northern Kremispher and find the lost Kongs.', 'Play Super Donkey Kong 3 on the Super Famicom.', 'The Japanese release of Dixie Kong''s Double Trouble. Features a more interactive world map, new vehicle mechanics, and stunning late-gen 16-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-3---nazo-no-krems-tou-japan-rev-a', 'SNES', 'Super Donkey Kong 3 - Nazo no Krems-tou (Japan) (Rev A)', '1996', 'Platformer', 'Rare', '2', 'Platformer', 'Pre-rendered platformer (Updated Revision).', 'Achieve 103% completion in the final 16-bit Kong title.', 'Play Super Donkey Kong 3 (Rev A) on SNES.', 'The refined 16-bit final edition. Includes minor balancing tweaks for the mini-games and optimizes the pre-rendered water and lighting effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-double-dragon-europe', 'SNES', 'Super Double Dragon (Europe)', '1992', 'Beat ''em Up', 'Technōs Japan', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up with technical combat.', 'Defeat the Shadow Warriors using martial arts mastery.', 'Experience Super Double Dragon on the SNES.', 'A deep 16-bit brawler. Unlike other titles in the genre, it features a guard button that allows you to catch enemy punches and perform devastating counter-attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-double-dragon-europe-beta', 'SNES', 'Super Double Dragon (Europe) (Beta)', '1992', 'Beat ''em Up', 'Technōs Japan', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up (European Beta).', 'Test the early counter-mechanics and stage flow.', 'Check out the Super Double Dragon Beta on SNES.', 'A rare 16-bit development look. Features a slightly different speed and some unused sprites, showing the evolution of Billy and Jimmy''s combat moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-double-dragon-usa', 'SNES', 'Super Double Dragon (USA)', '1992', 'Beat ''em Up', 'Technōs Japan', '2', 'Arcade Beat ''em Up', 'Side-scrolling beat ''em up (USA release).', 'Clean up the streets in this technical 16-bit brawler.', 'Play the classic Super Double Dragon on the SNES.', 'Features an adjustable power meter for special attacks and highly detailed backgrounds. A must-play for fans of strategic, methodical beat ''em ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-double-yakuman-japan', 'SNES', 'Super Double Yakuman (Japan)', '1993', 'Gambling', 'Namco', '1', 'Mahjong', 'Traditional Mahjong simulation with 2-player support.', 'Achieve the ultimate Yakuman hand in 16-bit.', 'Play Super Double Yakuman on the Super Famicom.', 'A polished 16-bit Mahjong title. Features a variety of AI opponents and a clean interface designed for quick and competitive matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-double-yakuman-ii-japan', 'SNES', 'Super Double Yakuman II (Japan)', '1994', 'Gambling', 'Namco', '1', 'Mahjong', 'Enhanced Mahjong simulation sequel.', 'Master the tiles in this refined 16-bit sequel.', 'Experience Super Double Yakuman II on Super Famicom.', 'Features improved character artwork and more varied game modes, including a story-based tournament path for solo players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-drakkhen-japan', 'SNES', 'Super Drakkhen (Japan)', '1995', 'Action RPG', 'Kemco', '1', 'Isometric RPG', 'Action-RPG with a 3D perspective and open world.', 'Explore the world of Dragon Earth and stop the dark cult.', 'Play Super Drakkhen on the Super Famicom.', 'Known as Dragon View in the West. A unique 16-bit hybrid featuring a first-person world map and side-scrolling action combat in dungeons and towns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-drift-out---world-rally-championships-japan', 'SNES', 'Super Drift Out - World Rally Championships (Japan)', '1995', 'Racing', 'Visco', '2', 'Rally Racing', 'Isometric rally racing simulation.', 'Win the World Rally Championship across global tracks.', 'Play the high-speed Super Drift Out on the SNES.', 'A 16-bit racing gem featuring smooth isometric graphics. Master the art of drifting on snow, dirt, and asphalt with realistic car handling and a wide variety of licensed-style rally vehicles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dropzone-europe', 'SNES', 'Super Dropzone (Europe)', '1994', 'Shooter', 'Eurocom', '2', 'Arcade Shooter', 'Fast-paced arena-based shooter.', 'Defend the human colonies from alien invasion in 16-bit.', 'Experience Super Dropzone on the Super Nintendo.', 'A frantic 16-bit update of the arcade classic. Fly in all directions, rescue scientists, and blast alien armadas in this high-intensity intergalactic dogfight.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dunk-shot-japan', 'SNES', 'Super Dunk Shot (Japan)', '1994', 'Sports', 'Taito', '2', 'Basketball', 'Basketball simulation with a focus on arcade action.', 'Lead your team to the 16-bit basketball finals.', 'Play Super Dunk Shot on the Super Famicom.', 'Known as "Bill Laimbeer''s Combat Basketball" in the West, but with a traditional sports theme in Japan. Features responsive controls and a classic top-down perspective for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dunk-star-japan', 'SNES', 'Super Dunk Star (Japan)', '1994', 'Sports', 'Taito', '2', 'Basketball', 'Competitive basketball simulation.', 'Master the court and become a 16-bit basketball star.', 'Experience Super Dunk Star on the Super Famicom.', 'A polished 16-bit sports title featuring detailed character sprites and a heavy emphasis on timing for shots, rebounds, and defensive steals in a professional league format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-duper-metroid-version-21', 'SNES', 'Super Duper Metroid Version 2.1', '2021', 'Action', 'Hack', '1', 'Enhanced Action', 'Enhanced fan-made Super Metroid modification.', 'Explore a revitalized Zebes with new puzzles and items.', 'Play the Super Duper Metroid v2.1 mod on the SNES.', 'A massive 16-bit fan overhaul of the original masterpiece. Features redesigned room layouts, rebalanced difficulty, and a modified progression path for veteran bounty hunters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-earth-defense-force-europe', 'SNES', 'Super Earth Defense Force (Europe)', '1992', 'Shooter', 'Jaleco', '2', 'Vertical Shooter', 'Horizontal-scrolling shoot ''em up (Shmup).', 'Save Earth from the Aja Soft invaders.', 'Experience Super Earth Defense Force on the SNES.', 'A classic 16-bit shooter where you choose from a variety of weapon types at the start of each mission. Features impressive Mode 7 effects and challenging boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-earth-defense-force-japan', 'SNES', 'Super Earth Defense Force (Japan)', '1992', 'Shooter', 'Jaleco', '2', 'Vertical Shooter', 'Horizontal-scrolling shoot ''em up (Japanese release).', 'Defend the planet in the original Japanese version.', 'Play Super Earth Defense Force on the Super Famicom.', 'Known for its tactical weapon-selection system. Level up your chosen armament through 16-bit stages filled with mechanized enemies and massive environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-earth-defense-force-usa', 'SNES', 'Super Earth Defense Force (USA)', '1992', 'Shooter', 'Jaleco', '2', 'Vertical Shooter', 'Horizontal-scrolling shoot ''em up (USA release).', 'Master the evolving weapon system in 16-bit.', 'Play the action-packed Super E.D.F. on the SNES.', 'Navigate through six intense levels of aerial combat. Manage your satellite drones to provide offensive cover or defensive shields in this high-stakes sci-fi shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-f-1-hero-japan', 'SNES', 'Super F-1 Hero (Japan)', '1994', 'Racing', 'Varie', '1', 'Formula One', 'F-1 racing simulation with an arcade feel.', 'Outspeed your rivals and win the 16-bit Grand Prix.', 'Play Super F-1 Hero on the Super Famicom.', 'Features a fast-paced Mode 7 engine. Customize your car''s settings and compete on various international tracks in a quest to become the ultimate formula racing champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-f1-circus-japan', 'SNES', 'Super F1 Circus (Japan)', '1992', 'Racing', 'Nichibutsu', '1', 'Formula One', 'Technical Formula 1 racing simulation.', 'Master the nuances of F-1 racing in this 16-bit sim.', 'Experience Super F1 Circus on the Super Famicom.', 'A pioneer of technical racing on the system. Focuses on realistic car setups, pit-stop strategy, and precise driving lines across faithfully recreated global circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-f1-circus-2-japan', 'SNES', 'Super F1 Circus 2 (Japan)', '1993', 'Racing', 'Nichibutsu', '1', 'Formula One', 'Enhanced Formula 1 racing simulation sequel.', 'Climb the ranks in this refined 16-bit racing sequel.', 'Play Super F1 Circus 2 on the Super Famicom.', 'Features improved physics and more detailed cockpit views. A serious 16-bit sim that rewards players for mastering throttle control and aerodynamic configurations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-f1-circus-3-japan', 'SNES', 'Super F1 Circus 3 (Japan)', '1994', 'Racing', 'Nichibutsu', '1', 'Formula One', 'The third entry in the technical F-1 series.', 'Achieve world championship glory in this 16-bit finale.', 'Experience Super F1 Circus 3 on the Super Famicom.', 'Optimizes the Mode 7 racing engine for a smoother frame rate. Includes updated rosters and tracks, offering the most complete simulation of the original trilogy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-f1-circus-gaiden-japan', 'SNES', 'Super F1 Circus Gaiden (Japan)', '1994', 'Racing', 'Nichibutsu', '1', 'Formula One', 'F-1 racing simulation with an alternate focus.', 'Explore new tracks and car classes in this 16-bit spin-off.', 'Play Super F1 Circus Gaiden on the Super Famicom.', 'A unique entry that departs from the main series'' rigid structure, offering more experimental tracks and varied car types for a different 16-bit racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-f1-circus-limited-japan', 'SNES', 'Super F1 Circus Limited (Japan)', '1994', 'Racing', 'Nichibutsu', '1', 'Formula One', 'Limited edition Formula 1 racing simulation.', 'Master the exclusive tracks in this rare 16-bit edition.', 'Check out Super F1 Circus Limited on the SNES.', 'A refined version of the F1 Circus engine featuring specialized balancing and specific track modifications designed for high-level competitive play in the Japanese market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famicom-controller-test-program-japan', 'SNES', 'Super Famicom Controller Test Program (Japan)', '1994', 'Utility', 'Nintendo', '1', 'Hardware Test', 'Hardware diagnostic and test utility.', 'Test the functionality of your Super Famicom controller.', 'Check the Super Famicom Controller Test Program.', 'A rare 16-bit technical tool used by developers and repair shops to verify button inputs, D-pad accuracy, and the integrity of the controller''s internal circuitry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famicom-wars-english-translation', 'SNES', 'Super Famicom Wars (English translation)', '1998', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical military strategy (English).', 'Command your army in this legendary 16-bit strategy game.', 'Play Super Famicom Wars in English on the SNES.', 'The fan-translated 16-bit predecessor to Advance Wars. Capture cities, manage resources, and deploy various units in a deep, turn-based battle for territorial dominance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famicom-wars-japan-np', 'SNES', 'Super Famicom Wars (Japan) (NP)', '1998', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical military strategy (Nintendo Power).', 'Experience the foundational "Wars" gameplay in Japan.', 'Play Super Famicom Wars on the Super Famicom.', 'Originally a digital-only release via the Nintendo Power kiosk. Features iconic characters and the rock-paper-scissors unit balance that defined the modern strategy genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-family-circuit-japan', 'SNES', 'Super Family Circuit (Japan)', '1993', 'Racing', 'Namco', '2', 'Arcade Racing', 'Top-down circuit racing with a focus on fun.', 'Win the family grand prix in this colorful 16-bit racer.', 'Experience Super Family Circuit on the Super Famicom.', 'Developed by Namco. Features cute, stylized vehicles and a simple but addictive driving model, making it an accessible 16-bit alternative to more serious sims.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-family-gelaende-japan-np', 'SNES', 'Super Family Gelaende (Japan) (NP)', '1995', 'Sports', 'Namco', '4', 'Multisport', 'Skiing and winter sports simulation (Nintendo Power).', 'Conquer the snowy slopes in this 16-bit winter sim.', 'Play Super Family Gelaende on the Super Famicom.', 'A rare ski simulation released via the Nintendo Power service. Master the slaloms and downhill courses using precise 16-bit movement and timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-family-tennis-japan', 'SNES', 'Super Family Tennis (Japan)', '1994', 'Sports', 'Namco', '4', 'Tennis', 'Responsive tennis simulation with a "chibi" style.', 'Win the international tennis tour in 16-bit.', 'Play Super Family Tennis on the Super Famicom.', 'Known as "Smash Tennis" in Europe. Features diverse courts, including a beach and a forest, with some of the tightest and most fun tennis controls on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famista-japan', 'SNES', 'Super Famista (Japan)', '1992', 'Sports', 'Namco', '2', 'Baseball', 'Arcade-style baseball simulation (Namco).', 'Hit home runs with the legendary Famista teams.', 'Experience Super Famista on the Super Famicom.', 'The 16-bit debut of Namco''s popular baseball franchise. Features fast-paced gameplay, colorful graphics, and a focus on arcade-style fun over complex simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famista-2-japan', 'SNES', 'Super Famista 2 (Japan)', '1993', 'Sports', 'Namco', '2', 'Baseball', 'Enhanced baseball simulation sequel.', 'Lead your team to the pennant in this 16-bit sequel.', 'Play Super Famista 2 on the Super Famicom.', 'Introduces improved player animations and updated rosters. A solid 16-bit sports title that balances easy-to-learn mechanics with deep competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famista-3-japan', 'SNES', 'Super Famista 3 (Japan)', '1994', 'Sports', 'Namco', '2', 'Baseball', 'Baseball simulation with refined graphics.', 'Master the field in the third 16-bit Famista entry.', 'Experience Super Famista 3 on the Super Famicom.', 'Features more detailed stadium environments and expanded statistical tracking for players. Offers a polished and energetic 16-bit baseball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famista-4-japan', 'SNES', 'Super Famista 4 (Japan)', '1995', 'Sports', 'Namco', '2', 'Baseball', 'Advanced baseball simulation with realistic stats.', 'Win the Japan series in this technical 16-bit sim.', 'Play Super Famista 4 on the Super Famicom.', 'A significant visual upgrade for the series. Features more realistic player proportions and a refined batting engine that emphasizes timing and pitch placement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famista-4-japan-rev-a', 'SNES', 'Super Famista 4 (Japan) (Rev A)', '1995', 'Sports', 'Namco', '2', 'Baseball', 'Advanced baseball simulation (Updated Revision).', 'Experience the most balanced version of Famista 4.', 'Play Super Famista 4 (Rev A) on the Super Famicom.', 'A 16-bit revision that fixes minor AI glitches and optimizes the save system for long-term season play, providing the most stable version of the fourth installment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-famista-5-japan-rev-0a', 'SNES', 'Super Famista 5 (Japan) (Rev 0A)', '1996', 'Sports', 'Namco', '2', 'Baseball', 'The fifth and final SNES Famista entry.', 'Achieve baseball immortality in this 16-bit finale.', 'Experience Super Famista 5 on the Super Famicom.', 'The pinnacle of the series on 16-bit hardware. Includes the most comprehensive roster and refined gameplay mechanics, serving as a perfect swan song for the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-final-match-tennis-japan', 'SNES', 'Super Final Match Tennis (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Tennis', 'Professional-style tennis simulation.', 'Master the 16-bit courts in this technical tennis sim.', 'Play Super Final Match Tennis on the Super Famicom.', 'Focuses on a more realistic representation of tennis compared to the "Family" series. Features precise ball physics and various court surfaces that affect ball speed and bounce.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling---queens-special-japan', 'SNES', 'Super Fire Pro Wrestling - Queen''s Special (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Technical women''s wrestling (Joshi Puroresu).', 'Win the Queen''s Special tournament with top female wrestlers.', 'Play Super Fire Pro Wrestling: Queen''s Special on SNES.', 'A technical 16-bit wrestling sim featuring licensed-style female wrestlers. Master the signature "grapple and timing" system that made the Fire Pro series a cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling---queens-special-japan-en-by-phil-v10', 'SNES', 'Super Fire Pro Wrestling - Queen''s Special (Japan) [En by Phil v1.0]', '1993', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Technical women''s wrestling (English Translation).', 'Experience the premier female wrestling sim in English.', 'Play Fire Pro Queen''s Special in English on SNES.', 'The fan-translated 16-bit experience. Fully accessible menus and name translations for the deep roster of legendary Japanese female wrestlers and their complex movesets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-japan', 'SNES', 'Super Fire Pro Wrestling (Japan)', '1991', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Technical 2D wrestling simulation.', 'Master the timing-based grapple system in the series debut.', 'Experience the original Super Fire Pro Wrestling on SNES.', 'The 16-bit foundation of the Fire Pro legend. Replaces button mashing with precise timing, featuring a diverse roster of "inspired-by" real-world wrestling legends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-2-japan', 'SNES', 'Super Fire Pro Wrestling 2 (Japan)', '1992', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Enhanced technical 2D wrestling sequel.', 'Claim the championship belt in this refined 16-bit sequel.', 'Play Super Fire Pro Wrestling 2 on the Super Famicom.', 'Introduces more wrestlers and refined animations. Features the iconic Edit Mode, allowing players to create their own 16-bit wrestling superstars with custom stats and moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-iii---easy-type-japan', 'SNES', 'Super Fire Pro Wrestling III - Easy Type (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Technical wrestling (Simplified "Easy Type").', 'Enjoy the Fire Pro experience with more accessible controls.', 'Play Fire Pro III: Easy Type on the Super Famicom.', 'A 16-bit variant designed for beginners. Retains the deep moveset but tweaks the timing windows to make the technical grappling easier for new players to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-iii---final-bout-japan', 'SNES', 'Super Fire Pro Wrestling III - Final Bout (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Advanced technical wrestling simulation.', 'Defeat the world''s best in the "Final Bout" tournament.', 'Experience Fire Pro III: Final Bout on the Super Famicom.', 'A massive 16-bit upgrade. Features an expanded roster, significantly improved sprites, and more varied match types, including the grueling "Gruesome Fighting" mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-iii---final-bout-japan-rev-a', 'SNES', 'Super Fire Pro Wrestling III - Final Bout (Japan) (Rev A)', '1993', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Technical wrestling (Updated Revision).', 'Experience the most balanced version of Fire Pro III.', 'Play Fire Pro III (Rev A) on the Super Famicom.', 'The refined 16-bit retail version. Fixes minor AI glitches and optimizes the memory management for the extensive custom wrestler save slots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-special-japan', 'SNES', 'Super Fire Pro Wrestling Special (Japan)', '1994', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Story-driven technical wrestling simulation.', 'Live the tragic life of a pro wrestler in this dark RPG.', 'Experience the epic Fire Pro Special on Super Famicom.', 'Written by Goichi Suda (Suda51). This 16-bit title features a deep, emotional story mode alongside the series'' trademark technical wrestling gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-special-japan-rev-a', 'SNES', 'Super Fire Pro Wrestling Special (Japan) (Rev A)', '1994', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Story-driven wrestling (Updated Revision).', 'Navigate the dark world of pro wrestling in this refined sim.', 'Play Fire Pro Special (Rev A) on the Super Famicom.', 'The optimized 16-bit edition. Includes minor fixes to the branching narrative paths and stabilizes the performance during the massive "Battle Royale" matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-x-japan', 'SNES', 'Super Fire Pro Wrestling X (Japan)', '1995', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Advanced wrestling with a 4-player Multitap.', 'Battle through the technical ranks in this 16-bit classic.', 'Play Super Fire Pro Wrestling X on the Super Famicom.', 'The penultimate SNES entry. Introduces more fluid animations and a massive increase in move variety, supporting up to 4 players for chaotic tag-team action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-x-premium-japan', 'SNES', 'Super Fire Pro Wrestling X Premium (Japan)', '1996', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'The ultimate 16-bit wrestling simulation.', 'Master the deepest wrestling game of the 90s.', 'Experience Fire Pro X Premium on the Super Famicom.', 'The definitive version. Features a massive roster of over 80 wrestlers and an incredibly deep Edit Mode. Widely considered one of the greatest 16-bit sports games ever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fire-pro-wrestling-x-premium-japan-en-by-sydra-v070', 'SNES', 'Super Fire Pro Wrestling X Premium (Japan) [En by Sydra v0.70]', '1996', 'Sports', 'Human Entertainment', '2', 'Pro Wrestling', 'Wrestling simulation (English Translation).', 'Create and compete with custom wrestlers in English.', 'Play Fire Pro X Premium in English on the SNES.', 'The Sydra 16-bit translation. Makes the complex Edit Mode and menu systems fully accessible, allowing Western fans to enjoy the deepest 16-bit wrestler creator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-fishing---big-fight-japan', 'SNES', 'Super Fishing - Big Fight (Japan)', '1994', 'Sports', 'Nichibutsu', '1', 'Fishing', 'Realistic fishing simulation with diverse lakes.', 'Catch the biggest trophies in this technical 16-bit sim.', 'Experience Super Fishing: Big Fight on Super Famicom.', 'A polished 16-bit fishing title. Features a first-person perspective for casting and a detailed underwater view for the struggle, with highly realistic fish AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-formation-soccer-94---world-cup-final-data-japan', 'SNES', 'Super Formation Soccer ''94 - World Cup Final Data (Japan)', '1994', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Soccer simulation with updated World Cup data.', 'Relive the 1994 World Cup with the final tournament data.', 'Play Formation Soccer ''94 WC Data on Super Famicom.', 'A specialized 16-bit edition. Features the actual rosters and stats from the end of the 1994 tournament, optimized for hardcore soccer fans and historians.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-formation-soccer-94-japan', 'SNES', 'Super Formation Soccer ''94 (Japan)', '1994', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Forward-perspective soccer simulation.', 'Win the 1994 World Cup in this high-speed 16-bit sim.', 'Experience Super Formation Soccer ''94 on SNES.', 'Human''s flagship soccer series. Features a unique vertical "behind-the-player" camera and responsive 16-bit controls that emphasize tactical positioning and passing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-formation-soccer-95-della-serie-a---ucc-xaqua-version-japan', 'SNES', 'Super Formation Soccer ''95 della Serie A - UCC Xaqua Version (Japan)', '1995', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Soccer simulation (Special UCC Xaqua Version).', 'Win the Italian league in this rare promotional edition.', 'Check out SFS ''95 della Serie A (UCC Xaqua) on SNES.', 'A rare 16-bit promotional variant sponsored by Xaqua. Features the same deep Serie A gameplay but with exclusive branding and minor visual tweaks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-formation-soccer-95-della-serie-a-japan', 'SNES', 'Super Formation Soccer ''95 della Serie A (Japan)', '1995', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Official Serie A Italian league soccer simulation.', 'Master the Italian league with licensed-style teams.', 'Play SFS ''95 della Serie A on the Super Famicom.', 'Focuses exclusively on the Italian Serie A. Includes the era''s superstars and teams, utilizing the series'' trademark 16-bit vertical camera system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-formation-soccer-96---world-club-edition-japan', 'SNES', 'Super Formation Soccer ''96 - World Club Edition (Japan)', '1996', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Club-focused soccer simulation with global teams.', 'Lead your favorite world club to international glory.', 'Play Super Formation Soccer ''96 on Super Famicom.', 'The final 16-bit entry in the series. Features an enormous roster of club teams from across the world and the most refined version of the vertical gameplay engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-formation-soccer-japan', 'SNES', 'Super Formation Soccer (Japan)', '1992', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Forward-perspective soccer simulation (Debut).', 'Experience the game that changed 16-bit soccer.', 'Play the original Super Formation Soccer on SNES.', 'Known as "Super Soccer" in the West. This 16-bit classic introduced the immersive vertical perspective and the legendary final match against Team Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-formation-soccer-ii-japan', 'SNES', 'Super Formation Soccer II (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Enhanced soccer simulation sequel.', 'Defeat the international teams in this polished 16-bit sequel.', 'Experience Super Formation Soccer II on Super Famicom.', 'Features improved sprite scaling and more varied weather effects. A faster and more technical 16-bit soccer experience compared to the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-full-metal-europe-itsv-proto', 'SNES', 'Super Full Metal (Europe) (It,Sv) (Proto)', '1993', 'Action', 'Infogrames', '2', 'Run and Gun', 'Competitive arena combat (Unreleased Prototype).', 'Battle in high-tech arenas in this rare European proto.', 'Check out Super Full Metal on the Super Nintendo.', 'A rare 16-bit unreleased action title. Features top-down combat mechanics and futuristic environments, offering a glimpse into a cancelled 16-bit project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gachapon-world---sd-gundam-x-japan', 'SNES', 'Super Gachapon World - SD Gundam X (Japan)', '1992', 'Action/Brawler', 'Bandai', '2', 'Chibi Action', 'Tactical strategy with SD Gundam mecha.', 'Conquer the 16-bit map with your favorite mobile suits.', 'Play Super Gachapon World: SD Gundam X on SNES.', 'A deep 16-bit strategy game. Command "Super Deformed" Gundam units in turn-based combat, featuring cinematic 1-on-1 battle sequences when units engage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gachapon-world---sd-gundam-x-japan-en-by-serin9x-v151-incomplete', 'SNES', 'Super Gachapon World - SD Gundam X (Japan) [En by Serin9x v1.51] (Incomplete)', '1992', 'Action/Brawler', 'Bandai', '2', 'Chibi Action', 'SD Gundam strategy (English Translation).', 'Master the Gundam tactical war with translated text.', 'Play SD Gundam X in English on the Super Nintendo.', 'An incomplete but functional 16-bit fan translation. Makes the complex menus and unit stats accessible for fans of the Gundam multiverse and tactical sims.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-genjin-japan', 'SNES', 'Super Genjin (Japan)', '1991', 'Platform', 'Taito', '2', 'Cartoon Platformer', 'Prehistoric side-scrolling platformer (Bonk).', 'Save the dinosaur kingdom in the original Japanese version.', 'Play Super Genjin on the Super Famicom.', 'Known as "Super Bonk". A creative 16-bit platformer where you use your head to climb, smash enemies, and transform into various forms by eating meat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-genjin-2-japan', 'SNES', 'Super Genjin 2 (Japan)', '1994', 'Platform', 'Taito', '2', 'Cartoon Platformer', 'Prehistoric platformer sequel (Japan exclusive).', 'Explore even more bizarre prehistoric worlds in 16-bit.', 'Experience Super Genjin 2 on the Super Famicom.', 'The Japan-exclusive sequel. Features significantly improved graphics, more complex level designs, and even weirder transformations for the bald-headed hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-genjin-2-japan-en-by-gaijin-v10-~super-bonk-2', 'SNES', 'Super Genjin 2 (Japan) [En by Gaijin v1.0] (~Super Bonk 2)', '1994', 'Platform', 'Taito', '2', 'Cartoon Platformer', 'Prehistoric platformer sequel (English Translation).', 'Enjoy the exclusive Bonk sequel with full English text.', 'Play Super Bonk 2 (Super Genjin 2) in English on SNES.', 'The fan-translated 16-bit sequel. Fully translates the humorous dialogue and menu systems, making this superior sequel accessible to Western fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ghouls-n-ghosts---super-arthur', 'SNES', 'Super Ghouls N Ghosts - Super Arthur', '1991', 'Action Platformer', 'Capcom', '2', 'Arcade Action', 'Enhanced action-platformer modification (Super Arthur).', 'Play through the classic with a powered-up Arthur.', 'Try the Super Ghouls ''N Ghosts: Super Arthur hack.', 'A 16-bit fan modification. Allows Arthur to start with the Gold Armor and higher speed, reducing the legendary difficulty while retaining the atmospheric challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ghoulsn-ghosts-europe', 'SNES', 'Super Ghouls''n Ghosts (Europe)', '1991', 'Action Platformer', 'Capcom', '2', 'Arcade Action', 'Atmospheric and challenging action-platformer.', 'Rescue the Princess and defeat Sardius in 16-bit glory.', 'Play the legendary Super Ghouls ''N Ghosts on SNES.', 'A 16-bit masterpiece from Capcom. Known for its incredible music, double-jump mechanics, and punishing difficulty. Navigate haunted forests and ghost ships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ghoulsn-ghosts-usa', 'SNES', 'Super Ghouls''n Ghosts (USA)', '1991', 'Action Platformer', 'Capcom', '2', 'Arcade Action', 'Atmospheric action-platformer (USA release).', 'Survive the 16-bit nightmare and claim the legendary armor.', 'Experience Super Ghouls ''n Ghosts for the SNES.', 'Master the projectile-based combat and the "double jump" to survive 16-bit stages filled with zombies, demons, and massive environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ghoulsn-ghosts-maiden-patch-plus', 'SNES', 'Super Ghouls''n Ghosts Maiden Patch Plus', '1991', 'Action Platformer', 'Capcom', '2', 'Arcade Action', 'Technical optimization modification (Maiden Patch).', 'Experience the classic without the 16-bit slowdown.', 'Play Ghouls ''N Ghosts Maiden Patch Plus on SNES.', 'A technical 16-bit fan fix. Uses the SA-1 chip (in compatible emulators) or optimizations to eliminate the original game''s frame rate drops, making the action fluid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ghoulsn-ghosts-sprite-hack', 'SNES', 'Super Ghouls''n Ghosts sprite hack', '1991', 'Action Platformer', 'Capcom', '2', 'Arcade Action', 'Graphical character modification (Sprite Hack).', 'Experience the gothic adventure with a new character look.', 'Try the Ghouls ''N Ghosts Sprite Hack on the SNES.', 'A creative 16-bit fan mod that replaces Arthur''s character sprites with a different hero or refined animations, offering a fresh visual take on the 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-go-kart-racing', 'SNES', 'Super Go-Kart Racing', '1995', 'Racing', 'Atelier Double', '2', 'Top-Down Racing', 'Top-down Mode 7 go-kart racing.', 'Outpace your opponents on the 16-bit circuit.', 'Play Super Go-Kart Racing on the SNES.', 'A fast-paced 16-bit racer utilizing Mode 7 effects for smooth track rotation. Choose from various quirky drivers and master the tight handling to claim the gold trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-go-kart-racing---mirror-mode', 'SNES', 'Super Go-Kart Racing - Mirror Mode', '1995', 'Racing', 'Atelier Double', '2', 'Top-Down Racing', 'Top-down racing (Mirror Mode Hack).', 'Master the tracks in reverse in this mirrored racing challenge.', 'Try Super Go-Kart Racing Mirror Mode on SNES.', 'A creative 16-bit modification that flips every track horizontally. Tests the muscle memory of veteran players by forcing them to navigate the familiar circuits in a mirrored perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-goal!-europe', 'SNES', 'Super Goal! (Europe)', '1992', 'Sports', 'Taito', '2', 'Soccer', 'Side-scrolling soccer simulation.', 'Win the international cup in this 16-bit soccer sim.', 'Play the classic Super Goal! on the Super Nintendo.', 'Known as European Super Soccer. Features a horizontal field view, smooth 16-bit scrolling, and a variety of national teams with adjustable difficulty for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-goal!-2-usa', 'SNES', 'Super Goal! 2 (USA)', '1993', 'Sports', 'Taito', '2', 'Soccer', 'Vertical-perspective soccer simulation.', 'Lead your team to glory in this 16-bit soccer sequel.', 'Experience Super Goal! 2 on the Super Nintendo.', 'The USA release of Super Formation Soccer II. Features an immersive vertical camera angle, improved sprite scaling, and deep tactical options for substitutions and formations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-godzilla-japan', 'SNES', 'Super Godzilla (Japan)', '1993', 'Action/Adventure', 'Compile', '1', 'Cinematic Action', 'Strategic action and kaiju combat simulation.', 'Navigate the city and defeat enemy monsters as Godzilla.', 'Experience Super Godzilla on the Super Famicom.', 'A unique 16-bit hybrid. Guide Godzilla through a top-down map to manage destruction, leading into intense cinematic 1-on-1 battles against iconic foes like MechaGodzilla.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-godzilla-japan-rev-a', 'SNES', 'Super Godzilla (Japan) (Rev A)', '1993', 'Action/Adventure', 'Compile', '1', 'Cinematic Action', 'Strategic action and combat (Updated Revision).', 'Master the monster combat in this refined 16-bit version.', 'Play Super Godzilla (Rev A) on Super Famicom.', 'The optimized 16-bit Japanese release. Fixes minor graphical glitches during the cinematic combat sequences and balances the energy consumption for Godzilla''s special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-godzilla-usa', 'SNES', 'Super Godzilla (USA)', '1993', 'Action/Adventure', 'Compile', '1', 'Cinematic Action', 'Strategic action and kaiju combat (USA release).', 'Protect the planet from alien monsters as Godzilla.', 'Play the legendary Super Godzilla on the SNES.', 'Features a unique dual-gameplay system. Manage the blue energy meter to unleash devastating breath attacks in high-stakes 16-bit battles against massive cinematic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gomoku-narabe---renju-japan', 'SNES', 'Super Gomoku Narabe - Renju (Japan)', '1992', 'Board Game', 'Nichibutsu', '2', 'Traditional Board Game', 'Traditional board game (Gomoku/Connect Five).', 'Connect five stones in a row to defeat the AI.', 'Play Super Gomoku Narabe - Renju on Super Famicom.', 'A polished 16-bit version of the classic abstract strategy game. Features various difficulty levels and traditional Japanese Renju rules for a meditative and mental challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gomoku-shougi---jouseki-kenkyuu-hen-japan', 'SNES', 'Super Gomoku Shougi - Jouseki Kenkyuu Hen (Japan)', '1992', 'Board Game', 'Nichibutsu', '2', 'Traditional Board Game', 'Traditional board game and strategy study tool.', 'Master the art of Gomoku and Shougi in 16-bit.', 'Explore Super Gomoku Shougi on the Super Famicom.', 'A specialized 16-bit title that combines play with educational segments. Study famous board positions and historical matches to improve your tactical skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gussun-oyoyo-japan', 'SNES', 'Super Gussun Oyoyo (Japan)', '1994', 'Puzzle', 'Kaneko', '2', 'Arcade Puzzle', 'Puzzle-platformer with falling block mechanics.', 'Guide Gussun to the exit by placing blocks to clear a path.', 'Experience Super Gussun Oyoyo on the Super Famicom.', 'A brilliant 16-bit hybrid of Lemmings and Tetris. Use falling blocks to create stairs and bridges for the automatic-walking heroes while avoiding hazards and rising water.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gussun-oyoyo-japan-sample', 'SNES', 'Super Gussun Oyoyo (Japan) (Sample)', '1994', 'Puzzle', 'Kaneko', '2', 'Arcade Puzzle', 'Puzzle-platformer (Sample/Demo Version).', 'Test the early block physics and character AI.', 'Check out the Super Gussun Oyoyo Sample on SNES.', 'A rare 16-bit development look. Features a selection of initial stages to showcase the unique "falling block navigation" mechanics and the vibrant character animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gussun-oyoyo-2-japan', 'SNES', 'Super Gussun Oyoyo 2 (Japan)', '1995', 'Puzzle', 'Kaneko', '2', 'Arcade Puzzle', 'Advanced puzzle-platformer sequel.', 'Rescue your friends in this expanded 16-bit puzzle sequel.', 'Play Super Gussun Oyoyo 2 on the Super Famicom.', 'Significantly improves on the original with more complex level hazards, new block types, and a robust 2-player cooperative mode for dual puzzle-solving action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-gussun-oyoyo-2-japan-en-by-rpgone-v10', 'SNES', 'Super Gussun Oyoyo 2 (Japan) [En by RPGOne v1.0]', '1995', 'Puzzle', 'Kaneko', '2', 'Arcade Puzzle', 'Puzzle-platformer sequel (English Translation).', 'Enjoy the Gussun puzzle adventure with full English text.', 'Play Super Gussun Oyoyo 2 in English on SNES.', 'The RPGOne 16-bit fan translation. Fully translates the humorous story segments and level instructions, making this creative puzzle masterpiece accessible to Western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hq---criminal-chaser-japan', 'SNES', 'Super H.Q. - Criminal Chaser (Japan)', '1992', 'Action', 'Taito', '1', 'Arcade Chase', 'High-speed racing and vehicle combat (Japanese release).', 'Chase down criminals in the official Japanese version.', 'Play Super H.Q. - Criminal Chaser on Super Famicom.', 'The 16-bit sequel to the arcade hit Chase H.Q. Features improved scaling, nitro boosts, and intense ramming combat as you take down fugitives on the highway.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hanafuda-japan', 'SNES', 'Super Hanafuda (Japan)', '1992', 'Card Game', 'Nichibutsu', '2', 'Traditional Card Game', 'Traditional Japanese card game simulation.', 'Master the "Flower Cards" in this polished 16-bit sim.', 'Experience Super Hanafuda on the Super Famicom.', 'Features beautiful 16-bit card art and multiple game modes. Learn the complex rules of Koi-Koi and other traditional gambling games in a relaxing digital format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hanafuda-2-japan', 'SNES', 'Super Hanafuda 2 (Japan)', '1994', 'Card Game', 'Nichibutsu', '2', 'Traditional Card Game', 'Enhanced traditional card game sequel.', 'Win the Hanafuda tournament in this 16-bit sequel.', 'Play Super Hanafuda 2 on the Super Famicom.', 'Features updated character graphics and more varied AI opponents. Includes a story mode that takes the player through various high-stakes 16-bit gambling dens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hauntroid', 'SNES', 'Super Hauntroid', '2023', 'Action/Adventure', 'Homebrew', '1', 'Metroidvania', 'Fan-made horror modification of Super Metroid.', 'Survive the haunted and decayed corridors of Zebes.', 'Play the spooky Super Hauntroid on the SNES.', 'A creative 16-bit total conversion hack. Features a dark, horror-themed aesthetic, redesigned map layouts, and a tense atmosphere that redefines the classic Metroid experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-high-impact-japan', 'SNES', 'Super High Impact (Japan)', '1991', 'Sports', 'Acclaim', '2', 'Arcade Football', 'Aggressive American Football simulation (Japanese release).', 'Crush the competition in this 16-bit arcade-style sim.', 'Play Super High Impact on the Super Famicom.', 'Features bone-crunching hits and over-the-top animations. A 16-bit port of the arcade hit that emphasizes hard-hitting action and high-scoring games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-high-impact-usa', 'SNES', 'Super High Impact (USA)', '1991', 'Sports', 'Acclaim', '2', 'Arcade Football', 'Aggressive American Football simulation (USA release).', 'Lead your team to victory with high-impact plays.', 'Experience Super High Impact on the Super Nintendo.', 'Includes a deep playbook and a 16-bit "tournament" mode. Features digitized sound effects and a fast-paced gameplay style that preceded the Blitz series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-high-impact-usa-beta', 'SNES', 'Super High Impact (USA) (Beta)', '1991', 'Sports', 'Acclaim', '2', 'Arcade Football', 'Aggressive American Football (Pre-release build).', 'Test the early collision physics and field scaling.', 'Check out the Super High Impact Beta on the SNES.', 'A rare 16-bit development slice. Witness the initial implementation of the "impact" animations and the tuning of the AI''s aggressive play-calling behavior.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hockey-94-japan', 'SNES', 'Super Hockey ''94 (Japan)', '1994', 'Sports', 'Taito', '2', 'Ice Hockey', 'Realistic ice hockey simulation (Japanese release).', 'Win the 16-bit hockey championship in Japan.', 'Play Super Hockey ''94 on the Super Famicom.', 'Features smooth skating animations and a technical approach to the sport. Focuses on precise passing and puck control for a more realistic 16-bit hockey experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hockey-europe', 'SNES', 'Super Hockey (Europe)', '1991', 'Sports', 'Taito', '2', 'Ice Hockey', 'Arcade-style ice hockey simulation (European release).', 'Compete for the cup in this 16-bit international sim.', 'Experience Super Hockey on the Super Nintendo.', 'Features a variety of international teams and fast-paced gameplay. Master the slap-shot and defensive checking to dominate the 16-bit ice arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-hockey-france-enfr', 'SNES', 'Super Hockey (France) (En,Fr)', '1991', 'Sports', 'Taito', '2', 'Ice Hockey', 'Ice hockey simulation (French localization).', 'Gagnez la coupe dans cette version française.', 'Jouez à Super Hockey en français sur le SNES.', 'The complete 16-bit hockey experience with full French text for menus and options. Compete against the world''s best teams in this agile sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-honmei---gi-seiha-japan', 'SNES', 'Super Honmei - GI Seiha (Japan)', '1994', 'Sports', 'Human Entertainment', '2', 'Horse Racing', 'Horse racing and management simulation.', 'Train and bet on the horses to conquer the GI races.', 'Explore Super Honmei on the Super Famicom.', 'A detailed 16-bit horse racing sim. Manage a stable of thoroughbreds, analyze track conditions, and place strategic bets to build a racing empire in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ice-hockey-europe', 'SNES', 'Super Ice Hockey (Europe)', '1992', 'Sports', 'Taito', '2', 'Ice Hockey', 'Professional-style ice hockey simulation.', 'Master the technical play in this 16-bit hockey sim.', 'Play Super Ice Hockey on the Super Nintendo.', 'Focuses on a more realistic representation of the sport. Includes strategic line changes, diverse rink sizes, and a heavy emphasis on 16-bit team tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-igo---go-ou-japan', 'SNES', 'Super Igo - Go Ou (Japan)', '1991', 'Board Game', 'Nichibutsu', '2', 'Traditional Board Game', 'Traditional board game (Igo/Go simulation).', 'Master the ancient game of Go in this technical 16-bit sim.', 'Experience Super Igo - Go Ou on the Super Famicom.', 'Features a sophisticated AI and various board sizes. A perfect 16-bit tool for both beginners and advanced players to practice the complex strategy of Go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-indy-champ-japan', 'SNES', 'Super Indy Champ (Japan)', '1993', 'Racing', 'Genki', '1', 'Arcade Racing', 'Formula-style open-wheel racing simulation.', 'Win the 16-bit Indy championship across diverse tracks.', 'Play Super Indy Champ on the Super Famicom.', 'Features a fast Mode 7 engine and customizable car settings. Navigate through realistic racing circuits and manage your pit stops to secure the world title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-inindou---datou-nobunaga-japan', 'SNES', 'Super Inindou - Datou Nobunaga (Japan)', '1992', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Top-down Mode 7 go-kart racing.', 'Outpace your opponents on the 16-bit circuit.', 'Play Super Go-Kart Racing on the SNES.', 'A fast-paced 16-bit racer utilizing Mode 7 effects for smooth track rotation. Choose from various quirky drivers and master the tight handling to claim the gold trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-international-cricket-europe', 'SNES', 'Super International Cricket (Europe)', '1993', 'Sports', 'Tiertex', '2', 'Cricket Simulation', 'Top-down racing (Mirror Mode Hack).', 'Master the tracks in reverse in this mirrored racing challenge.', 'Try Super Go-Kart Racing Mirror Mode on SNES.', 'A creative 16-bit modification that flips every track horizontally. Tests the muscle memory of veteran players by forcing them to navigate the familiar circuits in a mirrored perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-international-cricket-europe-beta', 'SNES', 'Super International Cricket (Europe) (Beta)', '1993', 'Sports', 'Tiertex', '2', 'Cricket Simulation', 'Side-scrolling soccer simulation.', 'Win the international cup in this 16-bit soccer sim.', 'Play the classic Super Goal! on the Super Nintendo.', 'Known as European Super Soccer. Features a horizontal field view, smooth 16-bit scrolling, and a variety of national teams with adjustable difficulty for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-james-pond-usa', 'SNES', 'Super James Pond (USA)', '1993', 'Platform', 'Millennium', '1', 'Cartoon Platformer', 'Vertical-perspective soccer simulation.', 'Lead your team to glory in this 16-bit soccer sequel.', 'Experience Super Goal! 2 on the Super Nintendo.', 'The USA release of Super Formation Soccer II. Features an immersive vertical camera angle, improved sprite scaling, and deep tactical options for substitutions and formations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-james-pond-usa-beta', 'SNES', 'Super James Pond (USA) (Beta)', '1993', 'Platform', 'Millennium', '1', 'Cartoon Platformer', 'Strategic action and kaiju combat simulation.', 'Navigate the city and defeat enemy monsters as Godzilla.', 'Experience Super Godzilla on the Super Famicom.', 'A unique 16-bit hybrid. Guide Godzilla through a top-down map to manage destruction, leading into intense cinematic 1-on-1 battles against iconic foes like MechaGodzilla.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-james-pond-ii-europe', 'SNES', 'Super James Pond II (Europe)', '1994', 'Platform', 'Millennium', '1', 'Cartoon Platformer', 'Strategic action and combat (Updated Revision).', 'Master the monster combat in this refined 16-bit version.', 'Play Super Godzilla (Rev A) on Super Famicom.', 'The optimized 16-bit Japanese release. Fixes minor graphical glitches during the cinematic combat sequences and balances the energy consumption for Godzilla''s special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-james-pond-ii-japan', 'SNES', 'Super James Pond II (Japan)', '1994', 'Platform', 'Millennium', '1', 'Cartoon Platformer', 'Strategic action and kaiju combat (USA release).', 'Protect the planet from alien monsters as Godzilla.', 'Play the legendary Super Godzilla on the SNES.', 'Features a unique dual-gameplay system. Manage the blue energy meter to unleash devastating breath attacks in high-stakes 16-bit battles against massive cinematic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-jangou-japan', 'SNES', 'Super Jangou (Japan)', '1992', 'Board Game', 'Nichibutsu', '2', 'Mahjong', 'Traditional board game (Gomoku/Connect Five).', 'Connect five stones in a row to defeat the AI.', 'Play Super Gomoku Narabe - Renju on Super Famicom.', 'A polished 16-bit version of the classic abstract strategy game. Features various difficulty levels and traditional Japanese Renju rules for a meditative and mental challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-jinsei-game-japan', 'SNES', 'Super Jinsei Game (Japan)', '1992', 'Board Game', 'Takara', '4', 'Life Simulation', 'Traditional board game and strategy study tool.', 'Master the art of Gomoku and Shougi in 16-bit.', 'Explore Super Gomoku Shougi on the Super Famicom.', 'A specialized 16-bit title that combines play with educational segments. Study famous board positions and historical matches to improve your tactical skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-jinsei-game-japan-rev-a', 'SNES', 'Super Jinsei Game (Japan) (Rev A)', '1992', 'Board Game', 'Takara', '4', 'Life Simulation', 'Puzzle-platformer with falling block mechanics.', 'Guide Gussun to the exit by placing blocks to clear a path.', 'Experience Super Gussun Oyoyo on the Super Famicom.', 'A brilliant 16-bit hybrid of Lemmings and Tetris. Use falling blocks to create stairs and bridges for the automatic-walking heroes while avoiding hazards and rising water.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-jinsei-game-2-japan', 'SNES', 'Super Jinsei Game 2 (Japan)', '1994', 'Board Game', 'Takara', '4', 'Life Simulation', 'Puzzle-platformer (Sample/Demo Version).', 'Test the early block physics and character AI.', 'Check out the Super Gussun Oyoyo Sample on SNES.', 'A rare 16-bit development look. Features a selection of initial stages to showcase the unique "falling block navigation" mechanics and the vibrant character animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-jinsei-game-3-japan', 'SNES', 'Super Jinsei Game 3 (Japan)', '1996', 'Board Game', 'Takara', '4', 'Life Simulation', 'Advanced puzzle-platformer sequel.', 'Rescue your friends in this expanded 16-bit puzzle sequel.', 'Play Super Gussun Oyoyo 2 on the Super Famicom.', 'Significantly improves on the original with more complex level hazards, new block types, and a robust 2-player cooperative mode for dual puzzle-solving action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-junkoid', 'SNES', 'Super Junkoid', '2023', 'Action/Homebrew', 'Homebrew', '1', 'Precision Platformer', 'Puzzle-platformer sequel (English Translation).', 'Enjoy the Gussun puzzle adventure with full English text.', 'Play Super Gussun Oyoyo 2 in English on SNES.', 'The RPGOne 16-bit fan translation. Fully translates the humorous story segments and level instructions, making this creative puzzle masterpiece accessible to Western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-keiba-japan', 'SNES', 'Super Keiba (Japan)', '1992', 'Sports', 'Human Entertainment', '1', 'Horse Racing', 'High-speed racing and vehicle combat (Japanese release).', 'Chase down criminals in the official Japanese version.', 'Play Super H.Q. - Criminal Chaser on Super Famicom.', 'The 16-bit sequel to the arcade hit Chase H.Q. Features improved scaling, nitro boosts, and intense ramming combat as you take down fugitives on the highway.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-keiba-2-japan', 'SNES', 'Super Keiba 2 (Japan)', '1994', 'Sports', 'Human Entertainment', '1', 'Horse Racing', 'Traditional Japanese card game simulation.', 'Master the "Flower Cards" in this polished 16-bit sim.', 'Experience Super Hanafuda on the Super Famicom.', 'Features beautiful 16-bit card art and multiple game modes. Learn the complex rules of Koi-Koi and other traditional gambling games in a relaxing digital format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-keirin-japan', 'SNES', 'Super Keirin (Japan)', '1992', 'Sports', 'Nichibutsu', '1', 'Cycling Racing', 'Enhanced traditional card game sequel.', 'Win the Hanafuda tournament in this 16-bit sequel.', 'Play Super Hanafuda 2 on the Super Famicom.', 'Features updated character graphics and more varied AI opponents. Includes a story mode that takes the player through various high-stakes 16-bit gambling dens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-kick-boxing---best-of-the-best-japan', 'SNES', 'Super Kick Boxing - Best of the Best (Japan)', '1993', 'Fighting', 'Human Entertainment', '2', 'Combat Sports', 'Fan-made horror modification of Super Metroid.', 'Survive the haunted and decayed corridors of Zebes.', 'Play the spooky Super Hauntroid on the SNES.', 'A creative 16-bit total conversion hack. Features a dark, horror-themed aesthetic, redesigned map layouts, and a tense atmosphere that redefines the classic Metroid experience.');
