INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-all-stars', 'SNES', 'Super Luigi All-Stars', '2023', 'Platform/Homebrew', 'Homebrew', '1', 'Mario-style Platformer', 'Vertical-scrolling shoot ''em up (Shmup).', 'Destroy the enemy armada in this intense 16-bit shooter.', 'Experience Super James Pond on the Super Nintendo.', 'A unique 16-bit aquatic shooter. Control the cybernetic secret agent fish through challenging levels filled with specialized power-ups and massive boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-arcade', 'SNES', 'Super Luigi Arcade', '2023', 'Arcade/Homebrew', 'Homebrew', '1', 'Classic Arcade Platformer', 'Side-scrolling platformer starring the secret agent fish.', 'Infiltrate Santa''s workshop and stop the evil Dr. Maybe.', 'Play Super James Pond II on the Super Nintendo.', 'Known as "Robocod". A creative 16-bit platformer where James Pond uses a metallic suit to stretch upwards and stick to ceilings, navigating massive toy-themed worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-land-by-gamma-v', 'SNES', 'Super Luigi Land by Gamma V', '2021', 'Platform/Homebrew', 'Gamma V', '1', 'Mario-style Platformer', 'Interactive logic and puzzle game.', 'Complete the Japanese logic puzzles in this 16-bit collection.', 'Experience Super Jikkyou Quiz on the Super Famicom.', 'A vibrant 16-bit quiz game featuring voiced commentary and a wide variety of topics. Test your knowledge against AI opponents in a game-show style format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-rpg-star-powered', 'SNES', 'Super Luigi RPG Star Powered', '2022', 'RPG/Homebrew', 'Homebrew', '1', 'Action RPG', 'Cinematic action-adventure set in ancient Japan.', 'Survive the traps and enemies in the ninja fortress.', 'Play Super Karakuri Ninpou Chou on Super Famicom.', 'A 16-bit action title featuring elaborate mechanical traps and cinematic cutscenes. Master the ninja arts to navigate a series of high-stakes missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luke-kart', 'SNES', 'Super Luke Kart', '2020', 'Racing/Homebrew', 'Homebrew', '4', 'Arcade Kart Racing', 'High-speed horse racing and management simulation.', 'Win the Keiba Triple Crown in this 16-bit sim.', 'Explore Super Keiba on the Super Famicom.', 'Features detailed horse breeding and training systems. Manage your stables and analyze the odds to become the most successful owner on the 16-bit racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luke-kart-v10', 'SNES', 'Super Luke Kart v1.0', '2020', 'Racing/Homebrew', 'Homebrew', '4', 'Arcade Kart Racing', 'Enhanced horse racing simulation sequel.', 'Climb the ranks in this refined 16-bit racing sequel.', 'Experience Super Keiba 2 on the Super Famicom.', 'Includes updated 16-bit graphics and more varied track conditions. Offers a deeper management experience with expanded statistical tracking for horses and jockeys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mad-champ-japan', 'SNES', 'Super Mad Champ (Japan)', '1994', 'Racing', 'Nichibutsu', '2', 'Arcade Racing', 'Turn-based strategy and management simulation.', 'Lead your favorite Keirin cycling team to the top.', 'Play Super Keirin on the Super Famicom.', 'A unique 16-bit sports strategy game. Manage the stamina and tactical positioning of your cyclists in high-speed arena races to win the championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-japan', 'SNES', 'Super Mahjong (Japan)', '1992', 'Board Game', 'Nichibutsu', '2', 'Mahjong', 'Action-platformer based on the anime series.', 'Defeat the mechanized threats in this 16-bit adventure.', 'Experience Super Kishin Zenki on the Super Famicom.', 'Based on Zenki. A fast-paced 16-bit brawler featuring massive transformations and powerful magical attacks to clear waves of demonic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-2---honkaku-4-nin-uchi-japan', 'SNES', 'Super Mahjong 2 - Honkaku 4 Nin Uchi (Japan)', '1993', 'Board Game', 'Nichibutsu', '4', 'Mahjong', 'Four-player traditional Mahjong simulation.', 'Defeat three AI opponents in a realistic 16-bit match.', 'Play Super Mahjong 2: Honkaku on Super Famicom.', 'A polished 16-bit Mahjong title featuring detailed hand animations and a robust scoring system. Includes various difficulty levels and a training mode for beginners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-2---honkaku-4-nin-uchi-japan-rev-a', 'SNES', 'Super Mahjong 2 - Honkaku 4 Nin Uchi (Japan) (Rev A)', '1993', 'Board Game', 'Nichibutsu', '4', 'Mahjong', 'Mahjong simulation (Updated Revision).', 'Experience the refined Mahjong logic in Rev A.', 'Play Super Mahjong 2 (Rev A) on Super Famicom.', 'The updated 16-bit retail version. Fixes minor scoring calculation bugs and optimizes the AI''s decision-making speed during late-game turns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-3---karakuchi-japan', 'SNES', 'Super Mahjong 3 - Karakuchi (Japan)', '1994', 'Board Game', 'Nichibutsu', '4', 'Mahjong', 'Advanced Mahjong simulation (Spicy/Karakuchi).', 'Challenge the expert-level AI in this 16-bit sequel.', 'Experience Super Mahjong 3: Karakuchi on SNES.', 'Features a much more aggressive AI and varied rule sets. Includes high-quality 16-bit character art and diverse tournament modes for seasoned Mahjong players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-taikai-japan', 'SNES', 'Super Mahjong Taikai (Japan)', '1995', 'Board Game', 'Nichibutsu', '4', 'Mahjong', 'Comprehensive Mahjong tournament simulation.', 'Rise through the ranks to win the 16-bit Grand Prix.', 'Play Super Mahjong Taikai on the Super Famicom.', 'A deep 16-bit Mahjong experience. Includes a story-driven tournament mode and a detailed encyclopedia of Mahjong terms and strategies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-taikai-japan-rev-a', 'SNES', 'Super Mahjong Taikai (Japan) (Rev A)', '1995', 'Board Game', 'Nichibutsu', '4', 'Mahjong', 'Mahjong simulation (Revision A).', 'Master the tiles in this stable 16-bit revision.', 'Play Super Mahjong Taikai (Rev A) on SNES.', 'The first major update. Optimizes the save data management and fixes minor sprite flickering during the tile-shuffling animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-taikai-japan-rev-c', 'SNES', 'Super Mahjong Taikai (Japan) (Rev C)', '1995', 'Board Game', 'Nichibutsu', '4', 'Mahjong', 'Mahjong simulation (Revision C).', 'Experience refined tournament play in Rev C.', 'Play Super Mahjong Taikai (Rev C) on SNES.', 'An incremental update that further balances the AI difficulty spikes in the mid-tier tournament brackets for a smoother progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mahjong-taikai-japan-rev-d', 'SNES', 'Super Mahjong Taikai (Japan) (Rev D)', '1995', 'Board Game', 'Nichibutsu', '4', 'Mahjong', 'Mahjong simulation (Final Revision D).', 'Play the definitive version of this Mahjong classic.', 'Play Super Mahjong Taikai (Rev D) on SNES.', 'The most stable 16-bit version of the game. Includes all previous bug fixes and provides the most accurate Mahjong logic available on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-marina-world', 'SNES', 'Super Marina World', '1993', 'Action', 'Taito', '2', 'Arcade Action', 'Fan-made total conversion of Mario World.', 'Navigate a maritime world as Mario in this unique hack.', 'Explore the custom levels of Super Marina World.', 'A creative 16-bit ROM hack. Features entirely redesigned water-themed levels, custom sprites, and a new world map inspired by nautical adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-all-stars-+-super-mario-world-improvement', 'SNES', 'Super Mario All-Stars + Super Mario World Improvement', '2021', 'Platform/Hack', 'Homebrew', '2', 'Mario Compilation', 'Enhanced 16-bit platformer compilation.', 'Play the definitive Mario collection with modern fixes.', 'Try Mario All-Stars + World Improvement on SNES.', 'A 16-bit fan enhancement. Fixes the "Luigi sprite" issues in Mario World and applies various physics and graphical patches to the All-Stars collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-all-stars-enhanced', 'SNES', 'Super Mario All-Stars Enhanced', '2021', 'Platform/Hack', 'Homebrew', '2', 'Mario Compilation', 'Enhanced 16-bit platformer collection.', 'Experience the 8-bit classics with refined 16-bit tech.', 'Play Super Mario All-Stars Enhanced on SNES.', 'A technical 16-bit mod. Improves sound quality, adds background layers to several stages, and restores specific visual details from the original NES versions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-all-stars-improvement-hack', 'SNES', 'Super Mario All-Stars Improvement Hack', '2021', 'Platform/Hack', 'Homebrew', '2', 'Mario Compilation', 'Technical physics and graphical overhaul hack.', 'Enjoy a more polished Mario All-Stars experience.', 'Try the Mario All-Stars Improvement Hack on SNES.', 'A 16-bit fan project focused on "fixing" the 16-bit ports. Includes physics corrections for Mario Bros 1 and 3, making them feel closer to the NES originals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-another-retro', 'SNES', 'Super Mario Another Retro', '2020', 'Platform/Hack', 'Homebrew', '1', 'Retro Platformer', 'Alternative fan-made Mario platformer.', 'Experience a "retro" take on the SNES Mario formula.', 'Play the Super Mario Another Retro hack on SNES.', 'A creative 16-bit mod that uses Super Mario World''s engine to recreate the aesthetics and tight level design philosophy of the 8-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-4-super-mario-world-prototype-edition-v-50---mario-+-luigi', 'SNES', 'Super Mario Bros 4 Super Mario World Prototype Edition v 5.0 - Mario + Luigi', '2022', 'Platform/Hack', 'Homebrew', '2', 'Mario Prototype Remix', 'Mario World Prototype/Beta recreation.', 'Explore the lost levels of the early SNES development.', 'Play Mario Bros 4 Prototype Edition on SNES.', 'A 16-bit historical reconstruction. Features level designs and sprites found in leaked Nintendo prototypes, offering a look at what Mario World could have been.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-5-reborn', 'SNES', 'Super Mario Bros. 5 Reborn', '2021', 'Platform/Hack', 'Homebrew', '1', 'Modern Mario Platformer', 'Fan-made sequel using the SNES Mario engine.', 'Survive a new 16-bit quest in this massive overhaul.', 'Experience Super Mario Bros. 5 Reborn on SNES.', 'A complete 16-bit total conversion hack. Features 80+ brand new levels, custom music, and unique power-ups, serving as a spiritual "true" sequel to Mario World.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-advance-2-:-super-mario-bros-3', 'SNES', 'Super Mario Bros. Advance 2 : Super Mario Bros. 3', '2023', 'Platform/Hack', 'Homebrew', '2', 'Mario Port Adaptation', 'Classic Mario 3 gameplay on the SNES engine.', 'Play Mario 3 with the refined physics of GBA/SNES.', 'Try Super Mario Bros. Advance 2 on the SNES.', 'A 16-bit fan port/mod. Adapts the features and physics of the GBA "Advance" series back into the SNES hardware for a unique hybrid experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-cd', 'SNES', 'Super Mario Bros. CD', '2020', 'Platform/Hack', 'Homebrew', '1', 'Experimental Platformer', 'Fan-made Mario adventure with CD-quality audio.', 'Experience Mario with a symphonic 16-bit soundtrack.', 'Play Super Mario Bros. CD on the Super Nintendo.', 'A MSU-1 technical mod. Retains the classic 16-bit gameplay but utilizes the MSU-1 chip to play high-fidelity, orchestral music during the adventure.');